/* 平成30年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h30.committeeSessions.push(...[{"id":"h30-20181029-9","meetingId":"h30-cm10","date":"2018年10月29日","dateIso":"2018-10-29","committee":"文教委員会","time":"午前１０時００分～午後 ３時２２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を106件抜き出しています。","topics":[{"id":"topic-01","title":"第７５号議案、品川区立保育所条例の一部を改正する条例","agenda":"第７５号議案、品川区立保育所条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"八潮南保育園の関係で、八潮わかば幼稚園と幼保一体施設になるということなのですが、完成したときのそれぞれの定員数を教えていただきたいのと、それから八潮北保育園についても、工事が終了してもとに戻るときの定数、それと平成３２年４月なので期間があと１年半ぐらいあると思うのですけれども、そうすると、この間の議論では、公設民営、民営化。","respondent":"吉田保育施設調整担当課長","answer":"民営化のところですけれども、八潮北保育園については、平成３４年から民営化いたしますので、平成３２年度に業者を選定する予定としています。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"幼保一体施設のほうについてなのですが、幼稚園部分と保育園部分、それぞれの定数を改めて確認したいので、別々に教えていただきたいと思います。そうすると、職員はどういうふうな処遇になるのか、全取っ替えになってしまうのか、ちょっとその辺が全くわからないので、今の考え方でいいですから教えていただきたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"平成３４年に委託になりますけれども、平成３３年度あたりで引き継ぎ保育を行いまして、平成３４年から受託した事業者に速やかに移行できるように１年間程度の猶予を考えて今のところ予定しているところです。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"幼保一体施設のほうなのですけれども、幼稚園部分といわゆる保育園部分と、あわせて、定員が９７人という理解でいいのですか。ちょっと違うのかなと思ったので、再確認で、それぞれの定数を教えていただきたいと思います。引き継ぎという言葉では。それから、八潮西保育園は八潮北保育園が終了してから引っ越し、改修というふうに同じようなスタイルでいく、そういうことでいいのかどうかを教えてください。","respondent":"吉田保育施設調整担当課長、佐藤保育課長","answer":"八潮西保育園につきましても、同様に、１年あとになりますけれども、平成３２年度に改修した後、平成３５年度から民営化のほうを進めていく予定で進めているところです。民営化実施時の保育士の採用の関係ですが、現時点での考え方になりますけれども、現行と同様に退職者の数に応じて新規の採用をしていますから、そういった形でやっていきたいと考えております。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"この民営化の問題は、品川区にとって初めてですよね。ここに来て、ごっそりと５園分を民営化するという方向が一、二年前から出されて、非常に懸念をしていたのです。しかし、進んでいるわけですから、保護者はもちろん、近隣の方々の理解も含めて、やはりきちんとそごのないように、信頼を持っていただけるような、そういう移行の仕方を強く求めておきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"わかりました。だけど、その辺のそういう意見もあるということは十分受けとめて、プロジェクトで検討中だということなのですけれども、しっかりと対応していただきたいということをちょっと悔しい思いも込めながら申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問","question":"今回は４園の所在地の変更と追加ということなのですけれども、やはり今、南委員が質問したように、民営化絡みの大規模改修が入っているということで、共産党としては問題視をしています。今もその考えは変わりがないのかどうかお伺いするのが１点です。３点目は、民営化が決まっている園を改めて伺います。いつから、どこの保育園が民営化されるのか、改めて伺います。","respondent":"吉田保育施設調整担当課長","answer":"考え方としては、先ほどの１番目で申し上げました施設水準のいいところから委託をしていくというところがありまして、この間、委託に関するプロジェクトチームで他の自治体から話を聞いた中で、やはり建物がある程度新しくないと。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"施設をきれいにリニューアルして委託をするというのは、受託業者にとって当たり前ですが、大変有利は有利ですよね。初めにできた古い保育園が全然改修されないで、そのまま放置をされている。やはり私たちはこの点、ちょっと納得できないのですが、いかがでしょうか。もっときちんと改修してほしい保育園があるのですけれども、どう考えていらっしゃるのでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"土地の確保、ここはなかなか難しいところですので、今のところ、大規模な建て替え、確かに建ててから５０年過ぎのものも結構たくさんあるのですけれども、なかなか計画を立てて、ここからやろうというのは難しい状況です。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味で、やはり声がないというのは、知らないでいるというのがかなり多いのではないかと思うので、やはり今後の状況を親御さんたちにきちんと伝える手だてをとっていただきたいと思うのですが、その点はいかがでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"その後につきましては、保育園の入園のご案内等において、ここの園はいついつから民営化いたしますということを記載しています。そのため、お入りいただくのはそれが前提ということで考えておりますので、今のところ、第１回目の説明以後、説明のほうはしていないところです。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そうですよね、０歳の子だって、３年後だと、３年間いた後の問題ですよね。入園のご案内に民営化しますと書いても、民営化が一体どういうものなのかというのがわかる方というのはほとんどいない、品川区がまだ民営化されていないというところにおいて、想像がつかないと思うのですよね。これは本当にしていただきたいと思うので、どうでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"周知の方法については、また今後検討してまいるところです。","id":"exchange-009"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"１点だけ確認をさせていただきたいのですが、いわゆる旧荏原第四中学校跡地の敷地内にほうさん保育園と南ゆたか保育園の二つの保育園ができるということですよね。一つの敷地に二つの保育園があるというのはなかなかほかのところではないケースだと思うのですが、この二つの園でのさまざまな調整が必要になってくるのかなと思います。","respondent":"吉田保育施設調整担当課長","answer":"それから動線については、この図ではわかりづらいかもしれませんが、入り口が分かれております。校庭の使い方については、前回文教委員会でご報告したとおり委託事業者が決まったところですので、その辺は区とまた事業者のほうで調整しながら進めてまいりたいと今検討しています。","id":"exchange-010"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"いわゆる問題がないようにしっかりと、調整というよりも連携というのですかね、そういったことをやっていただきたいと思いますので、それは区のほうも一緒になってやっていただければと考えています。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"渡部委員","kind":"質問・要望","question":"せっかくですから、そういうところもそろそろ改築期に来ているのであれば、やはりこれは行革的な話になるのかもしれないのですけれども、一旦全庁的にこれをどうするかというのを話し合った上で、方向性を見据えて早目に周知を始めていいのではないかなと私は思うのですが、どういうふうに民営化等もこれから先に進めていこうかとか、何かビジョンがあってやっているのか。","respondent":"吉田保育施設調整担当課長","answer":"今ある区立保育園の民営化につきましては、５園ほどお試し期間といいますか、民営化して、それでその状況等を鑑みながら今後の方針をどういうふうにしていくかを定めていきたいと考えているところです。","id":"exchange-012"},{"speaker":"渡部委員","kind":"質問","question":"お試し期間という話だったので、その辺を受けてこれからやるにしても、区のほうでも採用計画等もありますでしょうし、保育をする公務員の方々も何百人、６００人強でしょうか、いらっしゃって、それをどうするかというのも考えていかなければならないでしょうし、逆にここの旧荏原第四中学校跡地は広いですから。","respondent":"吉田保育施設調整担当課長","answer":"行財政改革特別委員会などでも報告があったと思いますが、旧荏原第四中学校跡地の使用方法につきましては、企画の部門から５年間という制限を承っているところがありまして、その５年間の中で何ができるかというところで公設民営と建て替えにつきまして。","id":"exchange-013"},{"speaker":"渡部委員","kind":"質問・要望","question":"大変失礼いたしました。承知しております。ここがあるうちに一気に仕掛けられることは仕掛けていただきたいなという要望だけをして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"八潮のほうなのですけれども、先ほど引き継ぎ保育の話が出ましたが、ほかの自治体で引き継ぎ保育を非常にきちんとやって、要するにそれをまたいで民営化した保育園に預けている保護者の声の中で、そこできちんとやってもらえたので民営化した後も安心して預けることができたというお話を伺ったことがあるので、ぜひそこのところをきちんとやっていただきたいという、確認です。","respondent":"吉田保育施設調整担当課長","answer":"給食施設については、現状の八潮わかば幼稚園のところの工事を今進めており、そちらの給食室のほうは、１２月中にはでき上がる予定で進めております。","id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そうすると、園児の移動については、混乱が出るため１カ月日程のずれがあるということですけれども、入園して１カ月で動くので、お子さんたちの慣れぐあいといいますか、ちょうどそういう混乱の時期なので、移動は十分配慮してお願いしたいと思います。給食室ですが、旧荏原第四中学校のほうの保育園の給食室はどうなるのですか。","respondent":"吉田保育施設調整担当課長","answer":"大変失礼いたしました。旧荏原第四中学校のほうの建て替えのほうの給食施設につきましては、この図で言いますと、ピンク色のところの左側のほうに給食室をつくっているところです。そちらのほうで給食の用意を行う予定です。","id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"質問","question":"旧荏原第四中学校のほうは、ピンク色の一番左側のところでつくって、そこから外を通って運ぶわけですか。両方に持っていくわけですか。","respondent":"吉田保育施設調整担当課長","answer":"説明が不足して申しわけございませんでした。南ゆたか保育園とほうさん保育園は、それぞれ別々に給食室があります。","id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"園庭に出さないとか、外に出ないとか、そういうふうに縮こまる保育であってはならないわけで、やはりそういう点でご近隣の方々へのそういう不安だとか、困ったというような状況に対しては、区がしっかりと説明をしていただいて、そして職員の方があまりそういうことを気にせずに保育が進んでいけるようにしていただきたいのですが、その件についてどうかというのを一つ伺いたいです。２点です。","respondent":"吉田保育施設調整担当課長","answer":"確かに時代の変化等で子どもの声が耳ざわりだと言われるような状況、最近はそういう状況も見受けられますが、近隣への配慮や近隣への上手な周知といいましょうか、ご理解をいただきながらこの辺は進めていければと考えているところです。","id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"八潮わかば幼稚園の関係ですけれども、私が言いたいのは、区がやはりきちんと住民に対して責任を持って対応していただきたいと、そこの姿勢を確認したいということです。４園は、実施するに当たってのテストと、そういう状況で捉えているということですか。そうであるとしたら、とんでもないと、ちょっとあまりにも無責任だなと私は思いますので、その辺についてどうなのかを確認したいと思います。","respondent":"吉田保育施設調整担当課長","answer":"子どもの声等につきましては、八潮といわず、どこでもある問題でもありますので、区のほうとしても苦情への対応、地域、近隣への理解、この辺につきましては、今後も進めてまいるところです。","id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"１０億円かかるということの意味がよくわからないので、もう一度説明していただきたいのと、民間活力とコスト削減、この２つがテストとしてやる、この４園の民間委託だと、そういうことでいいのですか。","respondent":"吉田保育施設調整担当課長","answer":"民間への委託というところは、今後も財政負担の、繰り返しになってしまいますけれども、区の一般財源の使用を抑えられるという意味では、国の補助金が使えるような民間園というのは、これはある一定程度必要なものと考えております。","id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"子どもを育てるのに経費を削減することが優先されていいのでしょうか。建て替えだけではなくて、取り壊しの費用とかも入れたら、それ以上にかかるのだろうと思うのですけれども、１０億円というのはちょっと考えられないような数字だというふうに私は思うので、ここはちょっと正確にしていただきたいと思います。次回のときでいいのですけれども、ここはきちんとご答弁をいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"つる委員","kind":"質問","question":"今、民営化の部分でかなり質疑があった中で、今最後のほうにちらっとありましたけれども、過去の質疑を見ると大体１００名定員ぐらいだと、１園当たり、ざっくり１億５,０００万円ぐらいの運営費という考え方ですかね。そうすると、国とか都の補助金をあわせると３０％で、それが来ると。だから、３分の１弱だと思うのですけれども、それぐらい来る。","respondent":"佐藤保育課長","answer":"サービス、環境、人材、特に人材の育成に関しましては、６月補正でいただきましたのびしなプロフェッショナルスクール等を創設して全力で取り組んでまいりたいと考えております。","id":"exchange-022"},{"speaker":"つる委員","kind":"質問・要望","question":"ちなみに、参考までに、八潮すこやか園に八潮南保育園が移転するに当たって、人数規模からすれば、若干名の定数の減なのですけれども、単独で例えば運営していたときに、１億５,０００万円ぐらいの運営費がかかるわけですが、幼保一体施設の中で一緒になることで、保育園の部分について、そういう意味での経費の削減というのは何かしら一緒の施設が一体になることで。","respondent":"吉田保育施設調整担当課長","answer":"例えばですけれども、保育園と幼稚園が一緒になったことによって、運動会だとかその他の事業とかを一緒にできる、こういったメリットが出てきます。金銭的なメリットのところにつきましては、今後検討の部分です。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"反対しますが、意見を一言、二言言わせてください。南ゆたか保育園、八潮南保育園、この３保育園の住所変更、また追加については可とします。しかし、今回のこの条例の一部改正は、住所変更という単純なものではありません。民営化反対、中止をこれからも求め続けていきますので、その点はしっかり言っておきたいと思います。以上、反対をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]},{"id":"topic-02","title":"第７６号議案、品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例","agenda":"第７６号議案、品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"家庭的保育事業の実態を知りたいので教えていただきたいと思います。一つは、まず家庭的保育事業の事業内容をざっくりと教えていただきたいのと、事務事業概要によると給食の提供が今、２カ所書かれていて、定員が５名と３名と２カ所あるのですけれども、ここでの給食の提供が現状どうなっているのか、具体的に中身を教えてください。","respondent":"大澤保育支援課長","answer":"家庭的保育事業ですけれども、短時間認定のお子さんを対象に８時から１８時までお預かりしている施設です。給食の状況ですけれども、今２施設あるうち、１施設は自園調理となっております。もう１施設は、外部の給食事業者からの搬入という形をとっております。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問","question":"一つは、外部の給食事業者の搬入と言われましたけれども、どういうところから、どんな給食内容が届けられるのか、あと費用等はどうなっているのか教えてください。","respondent":"大澤保育支援課長","answer":"外部搬入ですけれども、離乳食ですとか、アレルギー対応も可能な事業者から、それに対応した内容となっております。費用につきましては、運営費の中からお支払いしているという形になります。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"５人とか３人とか少ないところなので、なかなか自園でやっていく自園方式というのは難しいかなとは思うのですけれども、また反対に外からこのデリケートな離乳食のようなものを持ち込むということにおいて、やはり細菌の繁殖とか衛生面においても、アレルギー対応についても問題があるのではないかなと思うのですけれども、条例は本来５年以内に自園方式にするように求めているのだと思うのですが。","respondent":"大澤保育支援課長","answer":"区としましても自園調理が原則ということは認識してございまして、そこを変えるつもりはありません。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問","question":"保育ママの事業者の方からなかなか管理が困難ということでということですけれども、この前の段階で５年間という経過措置はあったにしても、とにかく自園方式で安全・安心な給食を提供してほしいという思いがあったからこそ法律ができて、条例に盛り込まれたのだと思うのですね。ぜひ区が支援をして、一刻も早く実現をすべきではないかと思っていますけれども、この辺はいかがでしょうか。","respondent":"大澤保育支援課長","answer":"もう１事業者に関しましては、今のところ調理員の確保についてもなかなか困難だというような状況もありますので、５年延長して、その中で区としてもできる支援はさせていただいて、何とか平成３７年度までには自園調理ができるように支援していきたいと思います。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区でできる支援というのは、どんなことを考えているのですか。条例の第７条のところに、連携協力を行う保育所と書いてあるのですけれども、これはどういう意味で、どこがこれに当たるのかを教えてください。","respondent":"大澤保育支援課長","answer":"もう一つですけれども、今５年の延長をということでご要望があるのは、調理設備が事業所内に確保することが難しいことと、先ほど申し上げたように、衛生面、維持管理が給食となると厳しいですので、なかなかそこまでは手が回らないと聞いております。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"ぜひここはお願いしたいと思います。連携園は日ごろいろいろな面で連携して支援が何か得られているということなのか、もう少しその中身を教えてください。","respondent":"大澤保育支援課長","answer":"連携園につきましては、家庭的保育事業が例えばお休みのときに区立園で預かるとか、そのような連携をしております。３歳以降に入る園を既に決めておりますので、卒園後はそちらの連携園で受け入れるという形になってあります。","id":"exchange-030"},{"speaker":"南委員","kind":"確認","question":"当面、平成２７年度から５年ということで始まったわけですけれども、この期間、品川区として外部より搬入している、そういう保育園に対して自園方式に転換していきましょうという働きかけはしてきたのかどうかの確認をしたいと思っているのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"南委員","kind":"確認","question":"だから、この５年間品川区としてはずっと働きかけをしてきたかどうか、そこのところを一番確認したいと思っているので、今のご答弁では働きかけはしてきているようにも受け取られたのですけれども、ちょっと明確にしたいと考えていますので、もう一度お願いします。","respondent":"大澤保育支援課長","answer":"働きかけというのは具体的にどういうことか、ちょっと今明確になっていないのですけれども、自園調理をしていただきたいということでお願いはしてきておりますが、まだ経過措置の最中ですので、無理やり、強制的にすぐにやるようにというふうには働きかけてはおりません。","id":"exchange-032"},{"speaker":"飯沼委員","kind":"意見","question":"反対します。自園方式が一番ということで、基本には据えていますけれども、経過措置があるからといって待つのではなく、やはり一刻も早く区が独自で支援して早急に実現すべきであると思っています。先延ばしは許されないと思いますので、反対をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"}]},{"id":"topic-03","title":"第７７号議案、品川区私立認定こども園、私立幼稚園および特定地域型保育事業の利用者負担額に関する条例の一部を改正する条例","agenda":"第７７号議案、品川区私立認定こども園、私立幼稚園および特定地域型保育事業の利用者負担額に関する条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"この改正の根拠、国のところなのですけれども、わかったら教えていただきたいのと、なぜ第３階層の(1)、(2)が該当になるのか、ここだけなのかというのを教えてください。今区外の支援制度の第３階層の方が対象となりますというご説明だったのですけれども、何人くらいいらっしゃるのか教えてください。","respondent":"大澤保育支援課長","answer":"国の政令の公布の日付につきましては、今正確な日付がわかりかねます。申しわけありません。国の改正の趣旨としましては、低所得世帯の経済的負担軽減を図るためとなっていますので、第３階層が対象となっています。区内に今のところ５名対象者がいらっしゃいます。","id":"exchange-034"}]},{"id":"topic-04","title":"第８０号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"第８０号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"意見","question":"１点だけ。２の主な改正内容のところについて、「主な」とついているのですが、中身的には政令の介護補償の限度額に準じて改正ということで、この額の変更のみなのかどうか、その１点だけお願いします。","respondent":"篠田学務課長","answer":"今回の改正内容は、それぞれ記載されておりますとおり支給限度額の改正です。","id":"exchange-035"}]},{"id":"topic-05","title":"第７４号議案、平成３０年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第７４号議案、平成３０年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"ここに示された電気設備工事設計委託のところでは、小学校１９校、中学校６校になっていますが、学校名を確認したいなと思うのです。時間の関係もあるのであれですけれども、先ほど申し上げたように、これからのところについて何校かということを伺いたいのと、工事の実施はいつごろから行われて、どういうふうになっていくのかという説明がないので、そこは教えていただきたいと思います。病児保育が。","respondent":"有馬庶務課長、佐藤保育課長","answer":"それからいつから工事かということですけれども、できるだけ早期にということですが、具体的には次年度予算の編成の中と、今この補正予算である調査結果、これらを踏まえて検討していきたいというふうに思っているところです。一方、公立保育園の保育士の一定負担にもなっているという部分もあり、区民の方のニーズも確実に病児保育室のほうに向いていますので、病後児保育室は徐々に狭めていく、縮小していく方向で検討したいと考えております。","id":"exchange-036"},{"speaker":"南委員","kind":"確認","question":"議事録を確認しないで来てしまったので申しわけないのですけれども、前回のたしか、おおしまこどもクリニックの６月の補正の最後に主張したのですけれども、保育士がなかなか休めないという現状の中で、やはり保育士も自分の子どもの具合が悪いときにきちんと休めるような、そういう状況を確保していかないと。","respondent":"有馬庶務課長、佐藤保育課長","answer":"工事するのは全ての学校ですので、この下のほうに書いてある設置の検討委託経費というほうにも、改築が済んでいる学校もあわせて検討はしていくということで、全校をやっていくという基本姿勢です。１点目の施設数は幾つぐらいつくるのかというところで、あくまで８００ぐらい受け入れられる施設であれば３つということで、定員によって受け入れられる人数が違いますので、一概に３施設、４施設というのは今現在は言えないところと。","id":"exchange-037"},{"speaker":"南委員","kind":"質問・要望","question":"職員配置も含めてちゃんととっていただくということが区の責任だと思いますので、そこは強く強調したいと思います。できるだけ第１回目のグループ、第２回目のグループというふうにしないで、来年の夏に間に合うような、そういう対応をしていただきたいというふうに思っています。そういうふうに受けとめていいのかどうかというのを確認して終わりたいと思います。","respondent":"有馬庶務課長","answer":"できるだけ早目にということでは考えておりますけれども、現実問題としてもある程度設備、設計して機械を入れるということですので、せっかく補正予算も組んでいますので何校かは夏に間に合わせたいなとは思っていますが。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問・要望","question":"補正予算書の１７ページのところに、病児保育施設開設経費助成と書いてあるので、この助成の中身とか割合を教えていただきたいのが１点です。","respondent":"佐藤保育課長","answer":"２点目の病後児保育と病児保育の線引きの部分ですけれども、病後児保育は病気が治った回復期に、回復しているにもかかわらず集団保育が難しいと判断した場合にお預かりする施設でございまして、病児保育に関しましては、重症ではないけれども。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問","question":"親の思いからすると、なかなかそこは難しくて、骨折とか、そういうのだとわかるのですけれども、病状がどういう段階にあるのかという判断はなかなか難しいと思うのですよね。その辺はどこで判断するのか、親の立場からすると、医師がすぐそばにいる病児保育のほうが安心かなという気がするのですが、その線引き等はどなたが判断するのかというあたりを教えてください。","respondent":"佐藤保育課長","answer":"その辺が１点目で強いところでございまして、委員のご指摘は、電話で事前に各保育園に病後児保育を受けたいと相談した場合のご心配だと思うのですけれども、そこはまさにちょっと保育士のほうで説明がなかなか行き届かなくて誤解を受けたりする問題もありますので。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問","question":"熱があるか、これははっきりしていると思って、医師にかかるということが前提ということですか、医師にかかった場合に、何か証明とかが必要なのですよね。それにはお金がかるのか、かからないのか、面倒ではないのか等教えてください。","respondent":"佐藤保育課長","answer":"病児保育の児童連絡票の関係ですが、医師会のほうにお願いして、無料で出していただいているところです。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"意見","question":"学校の空調の設備なのですけれども、１校およそ幾らぐらいで設計段階から設置までかかるのかというのと、先ほど早期にという願いに対して、来年の夏はちょっと難しい、でもなるべく早くとのことですが、その辺のめどがどのくらいなのかというところ、あともう一点は、避難所の機能としてもすごく期待をされるわけですけれども、やはり心配されるのが電源の問題なので、その辺をどう考えていくのか。","respondent":"有馬庶務課長","answer":"通常あるものは、やはり夜間でも避難所のトイレに行ける照明等にも使っていかなければいけないので、それを全部振り分けてクーラーに使っていくというのは、現状では難しいのではないかなというふうに考えております。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問・要望","question":"新たに冷暖房、空調設備が全学校の体育館につくというのは本当にうれしいことですし、避難所の環境改善にも大いに役立つのでうれしく思っています。電源確保の問題はさまざまな検討が必要かと思います。この間の本会議場でも自然エネルギーの活用とか、いろいろ出されていたので、本当にせっかくついた空調が稼働できるような電源の確保を考えていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"学校の屋内運動場等についてですが、我々もかねてからこの要望をずっとしてきて、実現に向かって動き出したのは大歓迎をしますが、一方で、今改築をしているところについて、いわゆる３、経費内訳の(1)の部分ですけれども、もし仮に改築をする段階で体育館に空調設備を入れるということを計画していたら、どれだけ今記載されている経費よりも削減ができたのか、まず１点教えていただきたいです。","respondent":"有馬庶務課長","answer":"３、経費内訳の(1)、上のほうからの電気設備と設置検討の絡みですけれども、基本的にこれは対象の学校が異なっていまして、電気設備工事というのは、まだ改築が終わっていない学校を対象としておりまして、今持っている電源設備、いわゆるキュービクル。","id":"exchange-044"},{"speaker":"石田（し）委員","kind":"確認","question":"設計委託の件ですけれども、いわゆる３の(1)の1)に関しては、古い学校で全体的なものをまず調査をかけないとわからないということですよね。3)は一定改築等がされていて、配管とかはある程度準備はしているけれども、何方式にするかというのを検討するということですよね。３段階あるということでいいのか、確認をさせてください。","respondent":"有馬庶務課長","answer":"設置検討した後、実施設計工事というふうに進むのかというところですけれども、現状からいけばそういうふうな形で進みます。","id":"exchange-045"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"やはりそこはできる限り未来を見据えたもの、可能な部分についてで、想定外の話は別ですけれども、例えばインターネット関係にしても、高齢者施設でインターネットの回線をつくらず、そのまま工事をしたというのが以前ほかのところの施設であって、今後絶対必要となっていくのに、それを見据えないで工事設計をしているなどというのはおかしい話ですので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"学校屋内運動場について予算書を見ると、一般財源になっているのですけれども、国と都の補助金のところが今後どうなるのか、どうしていくのか教えてください。","respondent":"有馬庶務課長","answer":"体育館については今後どうなるのか様子を見ていきたいと思っています。東京都のほうについては、はっきりと屋内運動場についての補助金を計画しているという情報が来ておりますので、今後その概要は見ていきたいと考えています。","id":"exchange-047"},{"speaker":"高橋（し）委員","kind":"質問","question":"冷暖房に関しての早急な取り組みは大変素晴らしいことだと思います。改築工事進行中の小学校でこの数字に出てきているのは３校ですね、鮫浜小学校と浜川小学校と第四日野小学校は改築に向け計画中ということなので、1)の芳水小学校的な予算の流れで、つまり改修が終わったときには何校か、芳水小学校のように入るという考え方でよろしいのでしょうか。","respondent":"有馬庶務課長","answer":"今そのほかに改築をしています浜川小学校、鮫浜小学校、これから行います第四日野小学校等につきましては、これから実施設計の段階で、体育館がいつまで使えるのかというところも見据えながらという形になります。","id":"exchange-048"},{"speaker":"つる委員","kind":"提案","question":"一般質問でも私どもの会派から屋内運動場についての空調設備設置についてはさせていただいたので、そこでの質疑も伺っているところでありますけれども、先ほど予算といいますか補助金等の話もあって、一応東京都からは一般質問でお伝えしましたが、都議会の公明党の代表質問で提案して、区市町を支援する、さらにあわせて、重ねて知事が直接受け取って、緊急要望ということで。","respondent":"有馬庶務課長","answer":"１点目の補助金の関係ですけれども、東京都のほうからも実際現状の考え方といいますか、そんな調査も来ましたので、そういったものにもしっかり回答して、補助制度活用に向けて努力してまいりたいと考えています。","id":"exchange-049"},{"speaker":"つる委員","kind":"質問・要望","question":"今回の場合、東京都に、都知事にも要望したのは、冷房だけではなくて、あくまでも冷暖房ということで、公明党としてはしっかりと明確に、小池知事に直接行って、そこでもしっかりお願いしますと言っております。１点、先ほど既に現在もというところで、戸越台中学校に設置されていると伺ったので、参考に利用状況というのでしょうか、夏、冬、教えていただければと思います。","respondent":"有馬庶務課長","answer":"基本的に何度になったら何というふうに決まりがあるのかはちょっと正式にはわかりませんけれども、夏場、冬場、セントラル方式になっており、スイッチを入れれば使えるという状況になっておりますので。","id":"exchange-050"},{"speaker":"つる委員","kind":"質問・要望","question":"この辺、既存の学校によって、さっき石田しんご委員のほうからもあったいろいろな学校の、また体育館の状況に応じて、３の(1)の1)、2)、3)にあるような形で対応が出てきてしまうというところがあるので、どんな形であれ、再三言っているように来年の夏に間に合うような形でというのを求めなければいけないところなのですが、事前にいろいろ確認させていただいた中では、現在の体育館、いわゆる別棟。","respondent":"有馬庶務課長","answer":"光熱水費抑制という面からも直していくときにはきちんと対応していきたいというふうに思っております。","id":"exchange-051"},{"speaker":"つる委員","kind":"確認","question":"最後に、１点だけ、２の導入効果の３点目のところに、一般開放における区民スポーツ活動の促進とあるのですね。学校の中でどこをそうするのかは、私も全部確認できているわけではないのですが、そういうしつらえがあるところ、ないしそれに当てているところへの冷暖房設備、このあたりの考え方はいかがでしょうか。","respondent":"有馬庶務課長","answer":"今どの学校の体育館のそばに更衣室が、幾つあるかというのはわかりませんけれども、体育館が入って、そこの更衣室もということは当然要望も出てくるかと思います。例えば個別空調で対応できるものなのか、その一体の中でできるものなのか、あわせて検討していきたいと思います。","id":"exchange-052"},{"speaker":"つる委員","kind":"質問・要望","question":"ぜひそういったところも細かい配慮になると思いますので、今回の議案は屋内体育館ということでのご説明でしたが、あわせてそこも全体の中でぜひ積極的に検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"}]},{"id":"topic-06","title":"平成３０年陳情第１８号、認可外を含む私立保育所職員に対する品川区独自の処遇改善を求める陳情","agenda":"平成３０年陳情第１８号、認可外を含む私立保育所職員に対する品川区独自の処遇改善を求める陳情","exchanges":[{"speaker":"南委員","kind":"質問","question":"今品川区内の区立の保育園は別として、私立の認可保育園、とりわけ新しくできた保育園のいわゆる賃金に関する処遇についてはどのようになっているか、改めてどう認識しているかを伺いたいと思います。とりわけ初任給がどうなのか、３年、５年経過して、その賃金はどのように推移しているのか、具体的な状況をつかんでいたら教えてください。","respondent":"大澤保育支援課長","answer":"今年の４月は２０万円から２３万円が初任給の額、来年の４月は今のところ２０万５,０００円から２３万５,０００円で、大体どこも５,０００円程度のアップはしているような状況です。","id":"exchange-054"},{"speaker":"南委員","kind":"質問・要望","question":"こういう状況、今数字を示していただいたのですけれども、一般の働く人たちとの賃金との関係で見ると、高いといっていいのか、低いのか、その辺の状況も教えていただきたいと思います。区立で働いていただいている職員の皆さんの状況とも比較をすると、どういうふうに見ているのか、その辺も教えてください。","respondent":"大澤保育支援課長","answer":"先ほど申し上げましたように、５割以上が３５０万円の収入になっておりますので、ほぼ同じような状況ではないかというふうに考えております。","id":"exchange-055"},{"speaker":"南委員","kind":"質問","question":"そうしますと、一番最初に説明していただいた５割以上が３５０万円以上になっていると、こういうことですが、短大卒という３０歳から３４歳の、ここと比較して、３５０万円以上というこの方々の年齢というのは、短大卒の３０歳から３４歳というここの年齢とほぼ同じで見ていいということなのでしょうか。","respondent":"大澤保育支援課長","answer":"今持っているのが平成２８年度の状況ですけれども、保育士の平均年齢が３４歳、平均経験年数が５.５年ですので、ほぼ同じような状況ではないかというふうに考えております。","id":"exchange-056"},{"speaker":"南委員","kind":"質問","question":"以前、直接保育支援課にお問い合わせさせていただいたときに、初任給は比較的高く募集して、そして数年経過すると、初任給のときは高かったけれども、伸びる率がずっと少なくなって、むしろ額が低くなっているというふうに説明していただいたのを記憶しているのですけれども、そういう状況ではなくなっているという認識でいいのかどうか、改めてそこを伺っておきたいと思います。","respondent":"大澤保育支援課長","answer":"数年たってから差が出るというのは、多分区の職員との差のことをおっしゃっているのかというふうに認識しておりますけれども、今保育士、私立は新しい園ができている関係で、かなり若い方が多いため、単純な比較はできないかと思いますが。","id":"exchange-057"},{"speaker":"南委員","kind":"質問","question":"この辺のとりわけ３歳児が２０対１のところを１５対１に区が加算しているという、そこのところの区の考え方について、また看護師を０歳に入れている、加配が必要だということの認識でこういう対応をしているということだというふうに私は理解するのですけれども、この辺についての加配の考え方、なぜここに加配をしているのか、それについて伺いたいと思います。","respondent":"大澤保育支援課長","answer":"加算ですけれども、０歳児園への看護師配置、また３歳児への１５対１の配置加算については、やはり保育の質という面で区の考え方をあらわしています。","id":"exchange-058"},{"speaker":"南委員","kind":"質問・要望","question":"確か１年前のときにも１歳児を６対１ですけれども、４対１に引き上げてほしいと、そういう趣旨の陳情が出されたというふうに記憶しているのですが、私は本当にそういうことで底上げをしていく、一人ひとりの子どもをしっかり捉えて、信頼関係をもって、その子の要求が受けとめられる、そのことによってほかの子どもとのかかわりができる、いろいろな遊びに展開していけると。","respondent":"大澤保育支援課長","answer":"最初に国の処遇改善ですけれども、勤続年数によって違うことについては、３年以上とか７年以上ということで、なるべく長く働いていただきたいという思いもあって設定しているものだというふうに認識しています。","id":"exchange-059"},{"speaker":"南委員","kind":"意見","question":"トイレに行けない状況、とんでもないことだと思いますよね。そういう自然生理現象に対してきちんと要求が満たされないような職場なんていうのはとんでもないことだというふうに思います。そういう状況、発言は非常に残念ですし、そういうこと自体が異常なわけです。だから、引き上げをしてほしいというのは当然の要求だというふうに思います。きちんとした底上げが必要だということを強調したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほど課長からご説明いただいて、区の個別の調査をしたら、５割以上が年収３５０万円以上であったという報告があったのですが、この調査というのはどこの部分までだったのか、今日出されている陳情は認可外を含め、私立保育園職員に対する処遇改善を求めているのですが、区が行った調査というのは、認可外とか認証とか、その他のところも含まれているのかどうか、それを１点教えていただきたいのと、冒頭。","respondent":"大澤保育支援課長","answer":"区の調査は、私立認可保育園の給与の調査です。平成２９年度は上がった額としては、平均ですけれども、６万６,０００円の見込みとなります。","id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問","question":"私立認可保育園で平均６万６,０００円の見込みだったということなのですけれども、認可外とか、認可以外のところは調べられていないのでしょうか。今日訴えていらっしゃる方の中には、結構認可外とか認証とかで働いている方がたくさんいらっしゃるところでの訴えなのです。","respondent":"大澤保育支援課長","answer":"給与の話ですけれども、認可保育園は公定価格として区が出している部分とキャリアアップも区を通して出しているので、一人ひとりの給与を報告していただくことはできますけれども、認可外については給与についての補助金を出していませんので。","id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今のところで、研修を受けなくても７割の園で出ているということですが、３割というのはなぜ受けていないのか、何か障害があるのかどうか、ちょっとそこを教えていただきたいのが１点です。保育士の配置基準のところなのですか、これによると３歳児、１５対１というふうに基準でなっているのですけれども、２０対１が１５対１に変わったのではなかったですかね。","respondent":"大澤保育支援課長","answer":"処遇改善IIというのがいわゆるキャリアアップの国の部分の加算ですけれども、行っていない園はやはり園の中で配分するのが難しいという理由で実施していませんが、平成３０年度はその配分についてかなり緩やかになって、園の中の３分の１の人しかだめであるとか。","id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問・要望","question":"５人を１人では絶対見られないというところにおいて、やはりこの基準をどうしていくのかというのが保育の質を上げていくまず第一であろうなと、保育士の目が届く、一人ひとりの気持ちがくみ取れるような保育をしていくためには、ここに例えば５対１と書いてありますけれども、６対１が戦後ずっと続いているこの基準を国にも求めなければいけないし、国が変えないのだったら。","respondent":"大澤保育支援課長","answer":"４歳児で一番今多い園が２４名ですけれども、担任は２４人に対して常勤２名と非常勤１名の３人で担当しております。国基準の３０対１では確かにきついという認識はありますので、それ以上の配置はしているところを確認しております。","id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問","question":"国基準というのは、これをベースにして公定価格で人件費などが払われているということになっていくのですが、今、看護師加配とおっしゃったけれども、品川区は看護師が配置されている分、保育士と置きかわっているのではないですか。昔は保育士がちゃんと３対１で配置されて、プラス看護師がいたのですが、そういうところが少しずつ削られて加配になっていない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だから、国基準が不十分なので、地方自治体に対して、品川区に対してもっと引き上げてほしいと求めているというところを……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問・要望","question":"はい、ぜひぜひ受けとめていただきたいと思います。やはりフランスなど、よその国の例などにぜひ目を向けていただきたいし、保育者の悲願なのですよね。それを保育課自体が受けとめられないということ自体が、変わっていかない大きな原因ではないかなと思っています。職員の声というのはどういうふうに受けとめているのか、最後に伺います。","respondent":"大澤保育支援課長","answer":"看護師は保育士のカウントに入れていません。１歳児は１対５、３歳児は１対１５で基準をつくって運営しております。","id":"exchange-067"},{"speaker":"つる委員","kind":"質問・要望","question":"平均でどのぐらい上がっているのかという先ほどの質疑の中で、６万６,０００円と、どこを基準にするかだと思うのですけれども、昨年は７万４,０００円が平均ですというご答弁があったのですが、ちょっとその数字だけ確認させていただきたいと思います。","respondent":"大澤保育支援課長","answer":"平成２９年度については、６万６,０００円の見込みですけれども、まだ平成２９年度の集計が終わっていませんので、結果として幾らになるかについては今集計中です。","id":"exchange-068"},{"speaker":"つる委員","kind":"質問・要望","question":"そういう機会があるかどうかはあれですけれども、こうした質疑の中でもそれがわかった段階でまたある程度教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"石田（し）委員","kind":"質問","question":"賃金に関してはもちろん区独自でやるという視点もなくはないですが、やはり待機児童対策も含めて考えた場合には、国レベル、東京都レベルである程度広域的に取り組んでいかなければいけない課題かなという中で、区として先ほどからのご説明で国、また東京都のさまざまな改善策、制度を使ってこれまで賃金アップに取り組んでおられるということでしたが、区として。","respondent":"大澤保育支援課長","answer":"都で待機児童対策協議会等がありますので、そういう場面で意見として出していくことはしております。特に処遇改善IIの研修については、必須だとなかなか難しいということで、それは各自治体から出た意見をもとに平成３４年まで延長されたです。","id":"exchange-070"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"いわゆる離職率が高い中で、何とかそのまま継続して、保育士として働けるような環境をつくろうということで、さまざまな加算、また制度がつくられていると思うのですが、実際ここ数年こういった改善、いわゆる賃金の中で改善がされている中で、保育士のいわゆる離職というのがどういうような傾向に来ていて、今後どのようになる見通しを区が持っているのか教えてください。","respondent":"大澤保育支援課長","answer":"そういう意味で、離職、園を変わるという意味では、少しこれからの競争の中で、もしかすると高くなってくる可能性があるのではないかというふうに考えています。","id":"exchange-071"},{"speaker":"渡部委員","kind":"質問・要望","question":"本日結論を出して、不採択にしたいと思います。この１時間の議論の中でさまざまな話を聞かせていただきました。そのような感じで、賃金等に関しても上がってきておりますし、制度に対しましてもそれぞれ国基準プラスアルファをなされているわけですから、引き続きこのまま続けていただきたいと思いますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"つる委員","kind":"質問・要望","question":"理由は、先ほど質疑をさせていただきましたことと、また、ほかの委員からの質疑も確認させていただいて、昨年の議論を参考にしながら、渡部委員のほうからもありましたけれども、答弁にもあったとおり、事業者のほうから、例えば当然保育士一人ひとりの処遇を改善してあげたいという強い思いは何度も伺ったこともありますし、逆に保育士からも処遇を改善してほしいという声もありました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今日結論を出すということで、採択を主張したいと思います。タイトルにありますように、この陳情は、認可外を含む私立保育所職員に対する品川区独自の処遇改善を求める陳情ということで、今日の説明からすると、認可外を含めた職員に対する処遇というのはまだまだ不十分ですし、報道で取り上げられたり、報告にあるほどの額が手元に行っていないということがここにしっかり書かれています。それが１点です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"しかし、一方で、先ほど質疑の中でもお伝えしましたが、これは区独自のもの、また東京都、国、そういった広域でやらなければいけない課題というのは、しっかり分けて、区でできることはもちろん全力で取り組んでいただきたいのですが、東京都や国に関しては、しっかり区が持っているノウハウや知識をぜひ届けていただいて、全体でさらに改善ができるように、その辺はお願いしたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そこのところで、区としての役割はそういった声を上げていく、また実効的であるかどうか、一番身近なところですのでチェックを今後もしていただくというような立場であるかと思います。区独自の加配や先ほどの看護師のお話ですが、そちらは区としてできることは進めているということですので、その点についても常に検証して、今後に向けて努力は続けていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"}]},{"id":"topic-07","title":"平成３０年陳情第１９号、「（仮称）空のはねこども園はたのだい」（旗の台２丁目）の事業者指導等を求める陳情","agenda":"平成３０年陳情第１９号、「（仮称）空のはねこども園はたのだい」（旗の台２丁目）の事業者指導等を求める陳情","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"そのとおりだなというふうに思っているのですが、こういうことについては、書面をもって対面で説明をしているというふうな説明だったのですけれども、この私道について、とりわけ私道のところを一つだけ取り上げるのですけれども、どういうふうに区として説明をしてこられたのか、世田谷区のような認識でいるだろうというふうには思っているのですけれども、それについてどうなっているのかを１点。","respondent":"大澤保育支援課長","answer":"事業者からは現在も承諾していただけるように個別に訪問している旨の報告を受けております。先ほどご紹介いたしました保育所を開設するにあたってという事業者への書面については、私道の持ち主に文書で許可を得る必要があるというふうに明記して説明をしているところです。","id":"exchange-077"},{"speaker":"南委員","kind":"質問","question":"そういう点で説明もしていると、事業者はそれについてどのような対応をこの間にしてきているのか。それについて教えてください。","respondent":"大澤保育支援課長","answer":"しかしながら、それ以外の部分についても承諾を得るよう区としては依頼しておりますので、事業者のほうは今努力をしているというふうに報告を受けております。","id":"exchange-078"},{"speaker":"南委員","kind":"質問","question":"北と南だと思うのですけれども、そこが私道だということで、もう一方の側は集合住宅と隣接をしているということで、非常に今までにないような地形にあるということで大変心配しておられるわけですけれども、この点、こういう形で似たような地形のところに開設された保育所があるのかどうかを聞いたのですけれども、その点についてはどうだったでしょうか。","respondent":"大澤保育支援課長","answer":"その片方が私道でございまして、そちらに公園から５ｍに満たないぐらい私道を通って保育園の出入口があるというような設計になっています。私道を避難経路として設定している園はほかにもございまして、そのときにも承諾書をとっていただいています。","id":"exchange-079"},{"speaker":"南委員","kind":"質問","question":"私が先ほど説明したようなこういう地形、隣がこうなっているという、そういうところで、同じような状況で保育園をつくっているところがあるという認識でいいのでしょうか。","respondent":"大澤保育支援課長","answer":"同じようなというのは、公園があって、私道があってという意味ではございません。避難経路として私道を使用しているところはあります。","id":"exchange-080"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、園庭もない、遊戯室もない、廊下もなくて、年齢ごとの保育室が配置されている、しかもあの周辺は私道である、こういう保育園について品川区としてもう少しきちんとした形で保育園のあり方というところの考え方を、待機児童が少ない中で保育園ができることは私もそれは受けとめていきたいとは思ってはいますけれども、つくるのであれば、やはりお隣、ご近所から理解される。","respondent":"大澤保育支援課長","answer":"区といたしましては、保育事業者が近隣要望を勘案して定員削減をしたこと、また一方で、区は集団保育の重要性や入園を希望される区民の方が多数いることから、認可保育所の定員は６０名を基本としておりますので。","id":"exchange-081"},{"speaker":"南委員","kind":"質問・要望","question":"当面２年間は４０名でいくということで、それで品川区の基準が６０名定員というふうなことなのですけれども、これはやはり園とか、その地域の状況とか、立地条件とか、そういうことを勘案して、６０名というところにこだわる必要はないのではないかなと思うのですけれども、６０名としている、その根拠というのはどういうことなのか、改めて伺いたいです。","respondent":"大澤保育支援課長","answer":"認可の平面図に関しましては、認可基準に則していれば、区としてその平面図がいけない等というような権限はございませんし、特にこの園がほかと比べて著しく劣っている配置図になっているというふうには認識してございません。","id":"exchange-082"},{"speaker":"南委員","kind":"質問・要望","question":"そちらから申し出たらということだけではなくて、地域の皆さんのご意見、ご要望を受けとめた形で区として健全な保育を進めていくというところの意見を事業者にお伝えいただくということがとりわけ必要なのではないかというふうに思うので、最後にそこだけ伺って、とりあえずこの関係での質問は、今は終わりにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"南委員","kind":"質問","question":"さっきも申し上げているのですけれども、２階のところを例に挙げて言いました。１歳児室の平米数が有効面積として５９.３５m2、そして２歳児、３歳児が同じ平面図のところに２歳児、３歳児となっていまして、有効面積が５８.２４m2で、ほぼ２階の面積の半分を分割して１歳児、２・３歳児となっているのです。ですから、それぞれ出入りをするときに、それぞれの保育室を通っていかないといけない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"南委員","kind":"質問・要望","question":"指導として、それが必要だと思うのです。そういう点で何回も繰り返しこの問題について質問をしているわけですが、必要ないというふうな、そういう考え方というのはいかがなものかということで、私はぜひそこは考えていただいて、保育の内容についてきちんと大事にしていただける、そういう立場で指導をしていただきたいと考えています。答弁が同じであれば、それはそれでいいですけども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区がどうして早い段階でこの計画をとめるような助言ができなかったのか、私は最初の入り口のところがきちんとできなかったために、こうやって地域の住民の方と保育事業者のトラブルといったらいいのですかね、住民の方にとっては青天の霹靂というか、降って湧いた災難というか、本当に知らないままにどんどん進められ、気がついたときに意見を言っても、どこも取り上げてくれなかったという。","respondent":"大澤保育支援課長","answer":"認可基準を満たしている申請が行われましたら、認可しなければいけない、東京都もそういうことになっておりますし、区市町村としても待機児童がいる以上、基本的な要件を満たしている限り提案を受け付けなければいけないということになっておりますので。","id":"exchange-086"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そこのところが多分違うのであろうなと思います。品川区も募集要項がありますよね。世田谷区と中野区の例が出ていましたけれども、その募集要項に一つひとつ、周辺住民に対する対応とか近隣とうまく物事を進めていく上でのことがきちんと書かれているのですよね。あくまでも民と民の問題だというよりも、品川区の責任であると重く受けとめていただきたいのですが、いかがでしょうか。","respondent":"大澤保育支援課長","answer":"保育所整備に関しましては、品川区においてもきちんと責任を持って住民に説明してくださいということは書面をもって、また対面でご説明をしているところです。","id":"exchange-087"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それを誰の責任にするのですか。区は責任がないと言えるのでしょうか。私はこれだけでなく、これからも起こってくると思うのです。これ、事実に反していませんか。こういったことで、住民が知らない間にどんどん進んでいる、これってないのではないでしょうか。私はとんでもないことだと思うのですが、事業者参入のときの手続の手順と区がどうかかわってきたのか、今の部分を教えてください。","respondent":"大澤保育支援課長","answer":"時系列で申し上げますと、９月の頭には保育園の開設について町会長のほうに事業者からお話をしています。同時期に、近隣住民の方に建設のお知らせを投函しています。１１月になってから具体的に説明会開催について周知をしたところです。","id":"exchange-088"},{"speaker":"飯沼委員","kind":"質問","question":"私が時系列的に言ったあたりで、住民の方が知らない間に区から都にいろいろ申請とか協議書が提出されているという問題は、事実と違うと思うのですが、この件に関してはどうでしょうか。","respondent":"大澤保育支援課長","answer":"９月に建設のお知らせについては投函していますので、時期としてずれてはいないというふうに認識しています。","id":"exchange-089"},{"speaker":"飯沼委員","kind":"質問","question":"何枚チラシが、どこの地域に入ったかわかりませんけれども、そうやってチラシを配布しましたというので、それで、これ、保育所の説明会を実施するほか、近隣住民の理解を得る努力を適切に行っている、または行う予定と、これで次の段階に行くのですかね。課長、ちょっとここのところ、事実をきちんと把握しているのかどうか、これは住民の方が怒るのは当然だと私は思うのですけれども、いかがでしょうか。","respondent":"大澤保育支援課長","answer":"説明会と意見交換会については、それぞれ４回、３回と実施しておりますので、特に事実に反しているというふうに認識してはございません。","id":"exchange-090"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この４回の説明会というのは、多分一方的な説明、打ち切られたり、１月に入って行われた部分で、決裂していたりとか、そういう中身であるので、やはりそれをやったという実績にしてしまうというのはおかしいし、私が言っているのは、住民説明会前の区の手続なのですよ。私はこれを課長に認めていただきたいと思うのですが、いかがでしょうか。","respondent":"大澤保育支援課長","answer":"申しわけありません、質問の意図がよくわからなかったのですけれども、説明会をする予定も含まれているはずなので、きちんと説明会をするという報告を受けて、説明会を実際にしていますので、何をもって違っていると言われているのか、ちょっとよくわからないので。","id":"exchange-091"},{"speaker":"飯沼委員","kind":"質問","question":"説明会が先にありきではないでしょうか。予定ですというところで、順調に進んでいますと区から都に報告が先に行っていること自体に問題があるのではないかと私は言っているのです。問題ではないですかね。やはり、ここのところで住民に説明がきちんとされる、話し合いがされていれば、違った部分もあるのではないでしょうか。私が言っていること、おかしいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"飯沼委員","kind":"質問・要望","question":"両者のことを一番よく知っているのは区ではないですか。世田谷区と中野区の例も紹介されましたけれども、やはりトラブルを防いでいくために、物事をスムーズに進めていくためにという意味で基準をつくってほしいとか、住民への対応のあり方、あと事業者の要件なども明記してほしいというところがありますので、ぜひ進んでいるところの中身は取り入れて改善をしていただきたいと思いますが、いかがでしょうか。","respondent":"大澤保育支援課長","answer":"多分民と民という言葉が出てきたのは、ご要望の内容によっては区の権限の範囲を超えてしまうために対応できないということについての説明や、保育事業者に何かを義務づけるにはどうしたらよいかというご質問に対し。","id":"exchange-093"},{"speaker":"飯沼委員","kind":"質問","question":"強制力がないからといってできないわけではなくて、強制力を持たなくても、三者の話し合いを地道に続けていく。合意のもとで行われる、事業者と住民の方をつなぐために区がしっかりと入って、三者の話し合いを続けていく、やはりこういうところをしっかりとお約束をしていただくことで住民の方がこれから本当に一緒にやっていくという立場に立てるのだと思うのですね。その辺はいかがでしょうか。","respondent":"大澤保育支援課長","answer":"繰り返しになりますが、要望については、今までも事業者に検討を促してまいりましたし、今後もそれは続けてまいります。","id":"exchange-094"},{"speaker":"飯沼委員","kind":"質問・要望","question":"よその優れた部分は品川区の要項にも取り入れてほしいということに対してぜひお答えをしていただきたいのと、あと最後に定員のことなのですけれども、私は６０人にこだわる必要はないと思います。でも、ここに書かれている５０人が適切かどうかという判断材料はちょっと持っていません。０歳から１・２歳までは２０人以上、でも、広げた場合は、４５人以上は確保できる面積、建物にしてほしい。","respondent":"大澤保育支援課長","answer":"ただ、他区の先行事例でよいところがあれば、それを受け入れる準備はもちろんありますし、今後は認可そのものが区が認可をすることに、４年たつとそうなってきますので、そういうときにはさまざまな事例を研究して。","id":"exchange-095"},{"speaker":"渡部委員","kind":"確認","question":"私道に対しても指導をなさっているということで、特段通園に対して問題はないけれども、なるべく全員の方の承諾をとってくださいというような努力をされているということですけれども、通園に支障がないという確認をとれていれば、そういうところもクリアされているのかなと思うので、クリアされていない大きな問題というのは見えないのですけれども、何なのでしょうか。","respondent":"大澤保育支援課長","answer":"合意書についても、町会のほうと合意書を締結したいということで、それは町会長からも、事業者から相談を受けている旨聞いておりますので、最終的には今定員のところかなというふうに私は認識しています。","id":"exchange-096"},{"speaker":"渡部委員","kind":"質問","question":"行政が中に入るという話ではなくて、しっかりと助言をいただいてということはなさっているわけですから、今まで文教委員会の中で結構さまざま入ってくるときに、いろいろな問題点というのは当然あって、多分保育園等ができていくためには、１年間のうちに何回かこの話というのはあるのかななどという気はするのですけれども、今までもそうだったのですけれども、基準に則っていて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"１点、いわゆるこの場所に保育園ができるのはどうなのかというような話が質疑の中であったのですが、近くに別の保育園がたしかあるのです。そこは特段問題がないのか、要はそのエリアだから保育園ができるのはどうなのかというようなことが質疑の中であったので、そこをまず確認させてください。","respondent":"大澤保育支援課長","answer":"今保育園は望まれていますので、一番近いところでは、同じ建物の上と下で保育園をつくったり、隣でつくったりというようなケースもあり、それでも入園の方はいらっしゃいますので、特にそこで問題があるというふうには認識しておりません。","id":"exchange-098"},{"speaker":"石田（し）委員","kind":"確認","question":"そこの保育所が、これができて問題があるというのではなく、そのエリアにいわゆる保育園ができるのは好ましくないというような質疑があったと思うのです。なので、その近くに実際にある保育園が何かその地域にあって、今までこの地域にあるから問題だというのがあったのかどうかというのを確認したいので、そこを改めてお答えください。","respondent":"大澤保育支援課長","answer":"地域的には何も問題ございません。","id":"exchange-099"},{"speaker":"石田（し）委員","kind":"意見","question":"もちろん住民の方の理解、先ほどからいろいろな方が住民の理解が必要だというのは、我々も同じ考えですけれども、ただ、いわゆる不備がない中で、住民の方の声もできる限り聞いて、何とかお互いの折り合いをつけるところをどこかで持たないと、それこそ保育事業者、運営サイドも運営サイドの思いがありますし、どうしてもそうせざるを得ない部分というのもあるのでしょうし、一方で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-100"},{"speaker":"渡部委員","kind":"意見","question":"結論を出して、態度については不採択です。先ほどお話しさせていただいたように、しっかり話を区としてもなさっていますし、事業者と住民の方々でさまざま、まだこれから少しお話し合いがあるのかなと思うのですが、区としては十分やるべきことはやっていると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-101"},{"speaker":"つる委員","kind":"質問・要望","question":"質疑も伺いました。それで、この地域性というところでも、石田しんご委員から確認があって、やはり再三申しあげるのですけれども、形として最終的にそこに保育園ができたときに、子どもたちというのは、すごく心が敏感で、保育していただいている保育士とか周りの方とかの言動というのは、子どもの発達にとって非常にセンシティブで影響が大きいのかなというのを私自身は懸念しています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"南委員","kind":"質問","question":"保育園施設を迷惑施設にしてはならないし、保育する責任があるのは区ですから、やはり今後基準などもつくって、責任を果たしていくということが大事であると思っています。地域から大事にされる保育園であってほしいし、地域の住民の方々の生活も守る、この指導が大事であって、私たちは区にこういった面で今後大いに期待をしていきたいと思っています。ですから、この陳情に対しては採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"結論を出すで、態度としては不採択です。理由は、先ほど意見を述べさせていただいたとおりであります。ただし、区としてしっかり事業者、また住民の、地域の方たちの声を聞いていただき、できる限りいわゆる間に入って調整というのは引き続きしていただきたいというのはありますので、ここは見します。態度としては不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"結論を出す。今多くの議論を伺って、またこの陳情を出された方々のお考えも読ませていただきました。今区側の、事業者に対する姿勢として、事業者のほうとつないで説明をしている、あるいは住民の方のお話をつないでいるなど対応していて、今後も要望をつないでいくというお話もありました。そういった形に向かうように現状までの対応を今後も続けるとありましたので、つないでいっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"}]},{"id":"topic-08","title":"本定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、文教委員会にかかわる項目","agenda":"本定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、文教委員会にかかわる項目","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"５年という存続を見据えて考えていて、心配ないというご答弁をいただいたのですが、その行方がどういうことなのか、もう少しお伺いしたいなと思っています。１人でも出してはいけないと思っていますが、そのあたりで待機児童ゼロと言われている計算式のところ、何がどう取り除かれて、認可保育園の待機児童がなくなっているのかというあたりをもう少し詳しくお聞きしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/862391?Template=document&Id=4954#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":73452,"voices":295}},{"id":"h30-20181029-5","meetingId":"h30-cm10","date":"2018年10月29日","dateIso":"2018-10-29","committee":"総務委員会","time":"午前１０時００分～午後 ０時２２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件抜き出しています。","topics":[{"id":"topic-01","title":"平成３０年請願第１５号、固定資産税及び都市計画税の軽減措置の継続","agenda":"平成３０年請願第１５号、固定資産税及び都市計画税の軽減措置の継続","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"それと、この請願は、ずっと採択されてきていて、毎年、これに携わる方というのは、ぜひ次も軽減措置の継続を求める意見書を出してくれということなのですが、ここまで来れば恒久的なものにしてもいいのかなという思いで、過去の総務委員会でいつも質問をしています。なかなかその辺について品川区としてお答えはできないとは思うのですが、品川区の思いはどういうものなのかお聞かせいただきたいと思います。","respondent":"伊東税務課長","answer":"ただ、地方税法改正とかの中で、そちらである程度クリアできればいいと思うのですけれども、なかなか全国一律ということでの改正というのは難しいかなと思いますので、その中では、その時々の地価変動を都が判断して、継続、場合によっては廃止など。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"今、課長から廃止という話が出ましたが、それはぜひ考えないでいただきたい。それは、先ほども申し上げたように、小規模事業者にとっては品川区、２３区全体にも言えることですが地価は高いですし、それなりに賦課される税金も多いと思いますので、この軽減措置は必要不可欠だと思っています。ぜひ強い発信力で、品川区も東京都に対して意見書を提出していただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"小規模住宅用地に対する軽減措置、小規模非住宅用地に対する減免措置、商業地等の負担水準上限引き下げ減額措置を平成３１年度以降も継続してほしいということですけれども、品川区としても東京都に対して求めていくことが必要ではないかと思うのですが、その点はいかがでしょうか。","respondent":"伊東税務課長","answer":"この話は区の方にも声が届いている状況です。機会を見まして、東京都にはお話しするということを考えておりますけれども、具体的にいつの時点で、どういう形というのは言えないところです。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"東京都にお話しをするということですけれども、品川区からも、また２３区からもこういう意見が上がっているということを、東京都に伝えることは必要だと思うのですけれども、伺ったのは、品川区としても、この３つの軽減措置の継続が必要ではないかということを東京都に伝えることが必要ではないかということですので、改めていかがでしょうか。","respondent":"伊東税務課長","answer":"お話は伝えると申し上げましたけれども、もともと現状の制度では、東京都が賦課徴収する形になってありますので、こちらからというよりは、周りからのお話が東京都に集まった中で、東京都が判断されるのかなと考えております。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"もちろん、東京都が判断することだと思いますけれども、だからこそ品川区としても、これを継続してほしいと東京都に要望を上げる必要があると思います。この３つの軽減措置の継続というのは欠かせないと思いますので、区としても東京都にこのことを伝えていただきたいと、強く要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"毎年この軽減措置の継続について意見書を求める請願が出ております。地価が当時これをつくったときから比べれば、相当上がっている。その辺について、どう思われますか。意見書については毎年、こういう仕組みだから出していかなければしようがないけれども、実際、路線価が、もう倍以上になっているのではないかなと思うので本当に不思議に感じるのですが、どう思われますか。","respondent":"伊東税務課長","answer":"確かに何年たっても同じような状況が続いているのかと思いますけれども、国もそれなりに対応すると思いますが、現状ではやはり東京都が２３区の状況というところで、東京都がそれぞれ判断すると思います。","id":"exchange-006"},{"speaker":"須貝委員","kind":"意見","question":"これは東京都の話なので、確かにつらいですよね。ただ毎年こうやらなければいけないのは、何か腑に落ちないところもあるのですけれども、その都度、チャンスがあれば都に話しを持っていき、先ほどほかの委員からありましたけれども、恒久的な仕組みになればありがたいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"中塚委員","kind":"意見","question":"第１５号、第１６号、ともに結論を出すということと、採択をして、都に意見書を提出すべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"いながわ委員","kind":"質問・要望","question":"結論を出すということで、先ほども申し上げたように、私の思いとしては、近い将来、恒久的なものになることがよろしいのではないかなと思いますので、ぜひそういう思いの中で、しっかり東京都に意見書を出していただきたいと思います。採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]},{"id":"topic-02","title":"平成３０年陳情第１５号、正しい公文書の情報管理と開示を求める陳情","agenda":"平成３０年陳情第１５号、正しい公文書の情報管理と開示を求める陳情","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"１点目が、公文書管理という言い方が正しいのかどうか、わからないのですけれども、品川区において公文書管理は何を根拠に行っているのか。国の公文書管理法とか、法律もあろうかと思いますので、それをお伺いしたいのです。それから公文書管理に関しては、品川区における公文書管理の正しいあり方を検討する会などの審議体または会議体があるのかどうなのかを、お聞かせいただきたいと思います。","respondent":"米田総務課長","answer":"文書管理に伴う審議体というものですけれども、現状のところ、そういうものはあるものではございませんが、国から定期に通知等があったり、あるいは区内の行政において課題が生じたというときに、一定程度、私どもを中心に検討を行っていく必要があるのだろうと。","id":"exchange-010"},{"speaker":"いながわ委員","kind":"質問","question":"要は、「この法令をもとに品川区は文書管理をしていますよ」ということではないということでいいのでしょうか。","respondent":"米田総務課長","answer":"これは絶対的な縛りというものとは違いますが、当然その趣旨を踏まえて、活用していくべきであろうと思います。それを品川区においては文書取扱規程というものに落とし込みながら、あるいは手引等に落とし込みながら、事務を進めているものです。","id":"exchange-011"},{"speaker":"いながわ委員","kind":"質問・要望","question":"たしか八王子市か何かが、結構そういった会議体をつくって、いろいろ、どうあるべきかを検討されていて報告書がネット上に出ていましたけれども、もし今後いろいろな形でＩＴ化を進めていくとか、そういうことを進めるのであれば、しっかりとした会議体をつくって、その中でどういう方向性が正しいかを、ぜひいろいろ議論していただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問","question":"公文書の管理は、保存の仕方と、公文書のつくり方と、両方から考えなければいけないなというのがあって、そういう意味で質問をしたのですけれども、もうちょっと文書のつくり方も品川区として、どういう形できちんとつくっていくべきかということとか、管理のあり方というのがきちんとあったほうがいいのではないかと思いました。","respondent":"米田総務課長","answer":"その中では、まだ紙決裁、紙で印鑑で押してという稟議のものは、まだ多数残っていると認識はしておりますが、起案文書の件名などについては電子化で、例えば件名だったりということについてはシステムに入れていこうという動きがありますので。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問","question":"わかりました。例えば、きちんと公文書として残していこうというものについて、品川区全体で何かガバナンスといいますか、品川区としてはこう考えているということがあるのかどうか、それについても伺いたいのですが、いかがでしょうか。","respondent":"米田総務課長","answer":"それに付随して、対外的にお知らせしていくようなものであるとかということについては、必然的にその意思決定の中で、添付書類として発生してくるものだと考えておりますので、まずはそこのところがきちんと適正に行われているか、この辺のところが肝になるものだと思います。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。もう片方が延べ人数で出てきた。だから、どういう文書を公文書として管理していこうとしているのかということを、品川区としてどうお考えかを伺ったのです。その解決方法がＩＴ化なのかは、私にも判断がつかないのですけれども、文書管理のあり方として、品川区としてこういうふうに管理していこうというものがあるべきなのではないかなと思いますが、その辺についてはいかがでしょうか。","respondent":"米田総務課長","answer":"ただ、今お話のあったものについては、基本的には所属のほうでとり方の判断、それは、所属のほうにも文書を取り扱う担当がおりますし、あるいは部の中にもおるわけですので、もしそこの中で対応しきれないようであれば、総務部のご相談を申し上げるという形だろうと思います。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問・要望","question":"言いたいのは、文書の抜けたものが、昨年の１２月に開示がされている。先ほども言いましたけれども、ＩＴ化で全てが解決するのかは、私にもわからないのですけれども、少なくともＩＴ化を区議会も進めておりますし、ＩＴ化は文書の管理をしやすくする手段の一つとして検討していくべきなのではないかなということで、もしできましたら、今後の方向性について一言いただきたいと思いますが、いかがでしょうか。","respondent":"米田総務課長","answer":"当然、エラーもあるので、そのエラーをどう潰していくか、あるいは対外的な所で重大な間違いというものを、どう潰していくかということは当然あるのですけれども、その辺も十分加味しつつ、ＩＴ化というものは、今までも平成１５年に導入して以来。","id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"意見","question":"ご説明ありがとうございました。私はＩＴ化を推し進めていくというのは、本当に重要なことだと思うのですけれども、一方で今も区がやっているような紙ベースも必要なのではないのかなと思います。ただ、他の自治体、東京都を含めてですが、どのぐらいの区がやっているのか、それから、ＩＴ化に取り組んでいる区からみて、本区は遅れているのか、どうなのかというところを聞きたいと思います。","respondent":"米田総務課長","answer":"そういった意味で、まだそう多くの自治体で、実施されているわけではないと感じているところでありますが、導入することによる課題なども含め、研究を行っていく必要はあるだろうと考えています。","id":"exchange-017"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"１０の自治体ということで、港区とか、葛飾区とか、板橋区もやっていると思うのです。ですから、そういった要望、区民が情報を公開してくれというのは、区に寄せられているのかどうかということをお聞きしたいと思います。","respondent":"米田総務課長","answer":"今のところ、陳情の内容にあるような趣旨での声というものが聞こえてくるということではないと考えています。むしろ、お聞きするケースはほとんどないかということではありますが、その中でも、他自治体の動向等は見きわめる必要があると思います。","id":"exchange-018"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひほかの区の動向を見きわめながら、区としても研究をいろいろしていただきたい。これは要望であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"やりとりを聞いていまして、幾つか伺いたいのですけれども、まず区民が求めている情報や、その根拠となる公文書は、しっかり区が責任を持って示すという重要な役割があると思います。事実の確認として、先ほど、実人数と延べ人数ということで数字のとり方が異なっていたというお話がありましたけれども、なぜ区民に異なるものが示されたのか、その原因と対策についてお聞きします。","respondent":"米田総務課長","answer":"指定管理書類一式の中で抜け落ちていたというのは、完全にそれを提供するのを失念していたというところのようですので、その辺については、一定程度適切な範疇であるという認識がありながらも、漏れていたということがあるようですので、その辺については。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれの課でしっかり対応していくということが大事だと思いますけれども、公文書の作成や整理や保存、また区民への説明について、一体化した仕組みをつくる責任というのは、総務課が旗を振る役割があるのかなと思うのですけれども、そういう意味で公文書の取り扱いに関する各所管への指示や研修や対応というのは、総務課が所管しているのか、確認させていただきたいと思います。","respondent":"米田総務課長","answer":"確かに公文書管理法の第３４条の中に、今お話しいただいた、保有する文書の適正な管理に関しまして必要な施策を策定し、及びこれを実施するよう努めなければならないということがございまして、国の法律ではありますが。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"この高い志の中で文書管理を行っていく、そうした意識をそれぞれの課に根付かせていく責任が、総務課には求められていると思うのです。先ほど、ほかの自治体も見ながらいろいろ進めていきたいと、ご答弁がありましたけれども、具体的に研修やシステムの構築など、何を進めていくのか、伺いたいと思います。","respondent":"米田総務課長","answer":"ただ、万全はございませんので、その辺のところは、毎年度行っております研修、役職者向け、新任者向け、それから必要に応じて適宜、文書事務を学びたい者向けの研修であったりということを実施して、ご質問にありました公文書等の管理に関する法律の冒頭等に述べられているのは。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"具体的には言いませんけれども、そういう意味では、今、体系的にできているとは言い難いと指摘をさせていただきたいと思います。ぜひ改善をしていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですから、今、一歩一歩徐々に公文書管理、情報開示を進めていると思いますが、私は徐々に、慎重にやっていただきたいと思います。品川区には今、公文書管理課というのは特段あるわけではないし、アメリカの事例を聞きましたら、政府において３,０００人規模で情報の管理担当者を配置していると。それが合っているのか、正確なのかどうなのか、管理する。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"結論を出すということで、今回の陳情の趣旨からいいますと、区民との情報共有が推進されますようといったことだったのですけれども、区としてもオープンデータ化などをしていますし、現在これで私は十分だと思っています。これから先はＩＴ化を加速というか、調査研究をしていただいて、前向きに検討していただきたいということで、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"今回この方は、自分が要望したことに対して、ちょっと違った文書が出てきたということとか、少し期間がかかっているということとか、そういうこともおっしゃっておられますが、そのことはそのことで、また受けとめていただいて、今後また区民の方が情報公開される文書を求められた場合には、意思の疎通をしっかり図っていただきながら、正確な文書を出していただきたいということ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"中塚委員","kind":"意見","question":"本日結論を出すということと、私は採択でお願いしたいと思います。理由は、今回のやりとりでも、区の公文書管理はとても不十分だと思います。このことは、区政の発展のためにも、とても大事な指摘だと思いますので、採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"いながわ委員","kind":"質問・要望","question":"本日結論を出す。一方では、こういう１つのご指摘ということで受けとめるのであれば、今後こういうことがないように、窓口での説明や公文書の出し方についてのスキルアップといいますか、そういうことをしっかりやるべきではないかなというのがあります。しかしながら、ＩＴ化をするとかそういうのは、先ほどもありましたけれども、時期尚早ということで、不採択にさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですが、先ほども申し上げましたけれども、大変だと思いますが、何かいい方策、対応、施策を考えていただいて、区も少しずつ、こういうご意見に対して少しでも近づけるように、私はやっていただきたいと思います。今回に関しては、本日結論を出すということと、私はこの件に関して、今回の陳情には不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問","question":"本日結論を出すということでお願いします。先ほども質問させていただきましたけれども、一言。そうすると、団体に調査して得るものの基準が違うものを取得してしまうということ自体が、本当にそれは所管の意識の問題でありますが、それについてもＩＴ化が全てではないと思いますが、少なくともＩＴ化はその業務をやりやすくする１つの手段であると考えますと、私は採択をすべきと主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]},{"id":"topic-03","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"こういう事故は、こちらの不注意もあるかもしれないですけれども、向こう側の不注意もある。ただ、それは、なかなかその場で、どう判断するか難しいと思います。そういうことも今後考えていただければと思います。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"いながわ委員","kind":"意見","question":"資料に自動二輪車と書いてあるのですけれども、品川区役所の施設整備課が所有している自動二輪車、原動機付自転車ではなく、自動二輪車を所有しているのかどうなのか。通常であれば保険を使用するわけであって、保険を使用するのであれば、次の掛金は多分、多少上がるのか、それとも企業同士で契約すると、そういうのは全くないのかどうなのかだけを、詳しくではなくていいので、お願いします。","respondent":"小林施設整備課長","answer":"自動二輪につきましては、おっしゃるとおり自動二輪車でございまして、施設整備課が所有しているものです。全額保険にて出捐していますが、自動二輪車については区施設営繕事務費で処理しております。","id":"exchange-032"},{"speaker":"いながわ委員","kind":"質問・要望","question":"自転車にも毎日乗っていますけれども、注意をして、事故を起こさないように、もちろん努力もしていかなければいけないし、横断歩道に人がいれば、絶対停車するし、そういう思いで運転する人間というのはやっていかなければいけないと思うので、これは１つの課がどうこうではなく、品川区、もちろん清掃事務所も含めて、その辺はしっかり指導していくべきではないかなと思いますので、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"}]},{"id":"topic-04","title":"品川区総合庁舎に設置されている免震オイルダンパー","agenda":"品川区総合庁舎に設置されている免震オイルダンパー","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"そういう思いの中でこの装置を設置しているわけですから。そうではなくて、ここまでいろいろとマスコミも騒ぎ、ほかの２３区の区役所でもそういうものがあるとか、該当するとかしないとか報道されている。なぜこういうことが実際に起きたかというのは、今、問い合わせているというのですけれども、本当に行政を欺いて商品を納品してきたわけですから、許されないことではないのかなと思うのです。","respondent":"立木経理課長","answer":"全容が明らかになったところで、行政としての、例えば業者の指名停止であるとかという行政処分などの何らかの対応というのは、行政として検討していくべきだろうと考えております。","id":"exchange-034"},{"speaker":"いながわ委員","kind":"質問・要望","question":"例えば今の免震オイルダンパーで、本来１０発揮しなければいけないのを、８しか発揮できないという改ざんがあったと。そうなると、今度は地面と庁舎をつないでいるアンカーがあるわけではないですか。相談とかがあって、実はこうなのだけれども、という話もあったのではないですかということも地域から聞くので、そういうのを払拭するためのことをやっていただければと思います。","respondent":"立木経理課長","answer":"ですので、そこの部分は部品をかえることによって、当初の性能が確保できるものと考えておりますので、メーカーにはそういったところをしっかり対応するようにということで、私どもも求めていくという考え方です。","id":"exchange-035"},{"speaker":"いながわ委員","kind":"質問","question":"それは１つ安心したところなのですが、先ほど言ったように、免震オイルダンパーを取りかえるというのは、新しいのをつければいいのですけれども、両側のアンカーの部分というのは、それに耐えられるのですか。免震オイルダンパーに負荷がかかるということは、アンカーの部分が４カ所でとまっていましたけれども、そこにも当然負荷がかかるわけではないですか。","respondent":"立木経理課長","answer":"もともと私どもの設計会社で当初見込んでいた性能の品物が入ることによって、当然そこは担保されるものですが、現状ついているデータ改ざんされたものが、ＫＹＢ株式会社からの発表によりますと、大臣認定の誤差の中には入っているけれども。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問","question":"今回のデータ改ざんの不正についてですけれども、先ほど課長は、残念でならないとおっしゃっていたのですが、そういう問題なのかと思うのです。これに対しては、もっと強い態度で対応していく必要があるだろうし、私は看過できない抗議すべき事案だと思うのですけれども、そこはいかがでしょうか。","respondent":"立木経理課長","answer":"先ほど私も、残念という表現を使ったのですけれども、こういったことが起きてしまったこと自体を大変残念に思っているということの意味でございまして、今、委員がおっしゃられましたとおり、不特定多数の来庁者の方がいらっしゃる建物ですので、そこの部分は今後。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問","question":"率直に言って看過できない事態だと、品川区として抗議する。そういうことをしっかりと態度表明するべき事案だと思うのです。本会議の質問に対する答弁の中で、遺憾と言ったのか、よく覚えていないのですけれども、残念だとかそういう思いではなくて、許されないという態度表明が必要ではないかと思うのですけれども、改めていかがでしょうか。","respondent":"立木経理課長","answer":"委員おっしゃられるとおり、本当に許されることではないと考えておりますので、抗議の部分に関しましては、また内部で検討させていただきたいと思います。","id":"exchange-038"},{"speaker":"須貝委員","kind":"質問","question":"３つがよくて、１つが悪いと。工業界でいえば、４分の１、２５％の確率で不良品が出た。これが全国に出ていると。オイルでシリンダーが動くわけですから、できないならできないと言うだろうし、できると言ってつくった以上、私はますます信じられないのかなと思います。でも、それも場所的に考えれば、私は難しいのではないかなと思うのですが、その点に関しては、どう思われますか。","respondent":"小林施設整備課長","answer":"先ほど見ていただいた一番手前のところだったとすると、駐車場の壁を一回壊して、そこから搬入して取りかえるという方法もあれば、駐車場のマシンハッチという床を壊して外して、そちらから入れるべきなのかとか、位置によっても全然違いますので。","id":"exchange-039"},{"speaker":"須貝委員","kind":"質問・要望","question":"施設整備課においても、品川区全体においても、まさか寝耳に水で、こんなことは考えられない状況です。まして病院とか公共施設という多くの方が利用する、また先ほどもありました防災拠点となる、本当にそれだけ多くの区民の方が心配されていると思いますので、できるだけ早期にいい方向に向かうように努力していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今までほかの委員の方からもさまざまな意見がありましたけれども、これは本庁舎と議会棟にまたがっているところなので、新設の杭を含めた再調査は、先ほど課長がおっしゃっていましたけれども、まずこれを調査していただいて、免震オイルダンパーについては、全部点検するというところなのですが、全国で１,０００件あって、製品が１万個ある中で。","respondent":"立木経理課長","answer":"既に設計会社、施工会社とも打ち合わせを始めております。そういった中で、できるだけ早期に交換の方向でいけるように調整を進めてまいりたいと思います。","id":"exchange-041"},{"speaker":"吉田委員","kind":"質問","question":"今まで皆さんのご質問を伺っていて、契約関係でいうと、区は直接ではないから、直接の損害賠償が難しいということなのですか。契約関係でいうと、どういうふうになっているのか。あくまで品川区としては、元請の方たちとの契約なので、その中で要求していくということになるのでしょうか。その辺の契約関係がどうなっているのか、教えてください。","respondent":"立木経理課長","answer":"ただし、それをＫＹＢ社から納品を受けて設置するというのは、確かに施工会社の工事になっておりますので、そういった面でもう一度整理をさせていただきまして、どういった形で進めていけるのか、４社での話になると思いますので。","id":"exchange-042"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういうことかと思いますが、一応、区がもともと発注してたものと違う性能のものが入ってきたということは、もともとの性能を満たすものを品川区として施工業者に求めていたわけですよね。その辺のことも含めて、それから安全性の検証等というのは、どこに対して、どういうふうにやっていくことを求めているのか、あわせて教えてください。","respondent":"小林施設整備課長","answer":"それと元請業者、これが品川区が発注した契約相手。そちらと相談をしながら検証していって、その際、取りかえる必要性が出てくれば、どういうふうに施工するのか、それは早期にわかり次第、検討に入りたいと思います。","id":"exchange-043"},{"speaker":"吉田委員","kind":"質問・要望","question":"要は、契約で求めたとおりの性能が確保されていなかったということに対しては、契約違反という形で厳しく追及していただきたい。その追及については、契約を交わしたのが、管理をお願いした設計会社と施工会社であれば、そこを通して厳しく安全性の検証も、客観性を担保するため、まるきり違う第三者によって確認した上で、厳しく追及していただきたいなと思います。これについては要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"}]},{"id":"topic-05","title":"今定例会の一般質問に係る所管質問でありますが、今定例会の一般質問中、総務委員会にかかわる項目","agenda":"今定例会の一般質問に係る所管質問でありますが、今定例会の一般質問中、総務委員会にかかわる項目","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"項目の正式名称を忘れてしまったのですけれども、藤原議員が質問なさった、さきほどの陳情にもかかわることで、公文書についてです。メモとか音声とかと公文書の境目、線引きという言葉を使われました。線引きはどこにあるのかということは、先ほどの公文書の管理の問題にも大きくかかわるところだと思います。ご答弁がなかったように認識しているのですけれども、その辺について改めて伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/643576?Template=document&Id=2120#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":33547,"voices":114}},{"id":"h30-20181030-6","meetingId":"h30-cm10","date":"2018年10月30日","dateIso":"2018-10-30","committee":"区民委員会","time":"午前１０時００分～午後 １時５４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","topics":[{"id":"topic-01","title":"特定非営利活動法人日本移植支援協会「細谷恵介くん基金」からの寄附","agenda":"特定非営利活動法人日本移植支援協会「細谷恵介くん基金」からの寄附","exchanges":[{"speaker":"田中委員","kind":"質問","question":"実際に品川区の子どもや障害者の方たちのスポーツ振興で使われるときには、「『細谷恵介くん基金』を利用しました」などと、寄附者の思いが伝わる使われ方で、表面にわかるように使われるのかということを聞きたいのですけれども、いかがでしょうか。","respondent":"池田スポーツ推進課長","answer":"今回は「細谷恵介くん基金」からの寄附ということになりまして、基金の中に入るということになってあります。実際に、こちらの基金の１,０００万円を活用した事業につきましては、その都度、「細谷恵介くん基金」からの基金を利用してということでＰＲをするつもりでおります。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、ご説明にあったとおり、基金に積み立てていくというお話でしたけれども、その後にどう活用していこうという考えがあれば、教えていただきたいと思います。","respondent":"池田スポーツ推進課長","answer":"まだ具体的なところにつきましては、決まったものはありませんが、今後考えていきたいと考えているところであります。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ本人の意向が活かされるような形で使っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"「品川区の事業承継にかかる意向調査」の報告書を見させていただきました。この調査に関して、区の分析と課題を伺いたいと思います。やはり５年を超えたあたりで取り組んでいこうというところが酌み取れるのかなと思いました。この報告書を読み取ると、まずは候補者を決めて、人材育成をして、支援としては資金調達が求められていると感じました。区の報告書と現在の分析と課題を伺います。","respondent":"山崎商業・ものづくり課長","answer":"そうなりますと、経営者は、なかなかその諸課題全てに手がつくような状況ではないのだということが通常の状態なのだという課題認識をしっかりする必要があるだろうなと調査を通じて思いました。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"そういったところで、具体的に伺いますと、今、後継者塾などを行っていますけれども、実際に事業承継に結びついた事例は幾つあるのかということ。この後継者塾は複数回受けることはできるのでしょうか。１回受けて、全てを完全に身につけるということも難しいのかなと思うのですが、伺います。","respondent":"山崎商業・ものづくり課長","answer":"例では、昨年、ご兄弟のお兄さんのほうが受けられた。今年は弟さんが受けられたという事例もありますので、さまざまなニーズに応じて柔軟に対応していこうと考えています。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり一番求められているのが後継者教育。求められているというか、課題としていたのが後継者教育ということでした。いろいろなクロスチェックでも、そこが一番大きかったので、そこをしっかりとやっていただきたいと思います。そういったところでも、今年度からは設備投資の助成が行われておりますが、この事業承継も含めて、リフォーム助成が全体的にも必要だと思いますけれども、いかがでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"いわゆる商店街の小売店舗などの内装のリフォーム助成ということだと思います。今日、ご説明申し上げました平成３０年度の(5)に、事業承継設備投資助成というものがあります。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"そういった店舗助成なども行ってやっていくべきだなと思います。これは、中小企業への大きな打撃になると思います。この非課税事業者が課税されることになってしまうということで問題が言われておりますけれども、インボイスも含めた消費税増税の問題について、区の見解を伺います。今回、区長選挙で区長が公契約条例を検討すると言われておりましたけれども、現在の状況を伺います。","respondent":"山崎商業・ものづくり課長","answer":"ご指摘の部分につきましては、私ども産業関連部門とともに、区の経理部門の主導でもって検討がなされていく部分かなというところで、そうした区全体としての検討の流れの中に、きっちり産業関連部門としてご意見を申し上げたり。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"公契約条例については、産業部門としてはどういったことを伝えているのか伺いたいと思います。消費税については、さまざまな取組みで対応していくということでしたけれども、やはり中小企業には大きな打撃になると思いますので、そういった観点からも、反対、中止の態度を示していくということも必要かと思いますが、いかがでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"そうした観点に資するような部分も考慮し、工夫ができる部分があればお願いしたいという立ち位置で検討のほうには参加させていただけたらなと思っているところです。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"公契約条例は、区内の経済の活性化ということですので、ぜひ実現させるために産業部門としても力を尽くしていただきたいと思います。あわせて、事業承継についても、この報告書から見ますと、後継者塾や融資あっ旋を求められているところで、対応されているなという認識は持っております。さらにこれが進むように、区内経済を活性化させるということで取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"おくの委員","kind":"質問","question":"関連して、この事業承継セミナーや後継者塾。先ほどのご説明の中でもちらっと出てきたのですけれども、こういうセミナーや塾を受けられた方の感想や、訪問相談を受けられた方の感想を伺っていらっしゃれば、どういうものが挙がっておられるかお聞きできればと思います。","respondent":"山崎商業・ものづくり課長","answer":"後継者塾は、２代目あるいは３代目という立場の方々ですので、今まで自分が会社の経営者として基本的に考えるべきことが広がった、あるいは、ほかの方と一緒にカリキュラムをすることによって、ふだん感じない領域での考えの幅が広がったということ。","id":"exchange-010"},{"speaker":"おくの委員","kind":"質問","question":"そうすると、言ってみれば、ワンストップ的な窓口の役割を果たし始めているというイメージ、理解でよろしいのでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"そもそも相談相手がいないところに事業承継士、先ほどのいろいろな知見がある方、専門領域の知識のある方が行かれますので、最初の相談として、ワンストップで済む問題でしたら、それで了解ということになるのですが、例えば、継ぐ人もなかなかいないので。","id":"exchange-011"},{"speaker":"おくの委員","kind":"質問・要望","question":"確かにワンストップで済むような単純な問題ではないですよね。単純な問題でないということは、少しはわかっているつもりですけれども、方向性としては必要なことだし、求められていることだと思いますので、できるだけ多くの方に知らせて、充実したものにしていってほしいとは思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"大倉委員","kind":"質問・要望","question":"少し教えていただきたいのですが、品川区内の事業者の事業承継センターへの相談件数が、どのくらい行かれているのかなというのがわかれば教えていただきたい。その辺の取組みはできるのか。今この中でされているのかというところを教えてください。","respondent":"山崎商業・ものづくり課長","answer":"この数字が、事業承継センターの相談件数ととっていただいて結構かと思います。それから、２つ目のご質問につきましては、委員がおっしゃられたようなマッチングが区内企業者同士や区内企業の健全な継続を担保するために成立できたらすばらしいなと思うところではあります。","id":"exchange-013"},{"speaker":"大倉委員","kind":"質問","question":"その辺も、情報の整理が課題なのだろうというところでは、区外の業者との承継の方法や手法というのは、この事業承継センター株式会社が持っている情報でやっていくということなのでしょうか。廃業のほうも、この中ではやらなければいけないことでやっていっているというお話だったのですけれども、数で言うとどのくらいあったのかなというのを教えてください。","respondent":"山崎商業・ものづくり課長","answer":"それで、例えば、Ａ社におきましては融資を受けられて、区のさまざまな助成金で新技術開発支援を行ったなど、そういうことはできておりますので、そうした情報の１つに本件事業の交渉の経過などもまとめていくような方向になればいいなというところで。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問・要望","question":"１万８,０００ちょっと事業所がある中で、数的にどうなのかなという思いがあって、ほんの一部だけの方だと私は思うのです。区として、この数をどのように把握して分析しているのか。アピール不足であったり、これだけ手厚い施策があるにもかかわらず、これを求めている方のニーズの問題も出てくると思うのです。その辺について、分析と今後の課題をどのようにしていくのか教えていただけますか。","respondent":"山崎商業・ものづくり課長","answer":"ここでお示しする従業員２０名以下、１万８,０００事業所の中で、本件事業承継事業のセミナーの数でいきますと、相当比率的にですが、まずは、表の製造業の１,７８５事業所のうちの半数が、事業承継にお悩みがあるのだという数字に読めますので。","id":"exchange-015"},{"speaker":"藤原委員","kind":"質問・要望","question":"資金融資について伺います。それと、これ以外にも、通常やっている中小企業への融資あっ旋、ああいう資金と並行して借りられるのかというあたりについて、特に括弧書きにも何も書いていないけれども、信用保証協会が出ていないではないですか。やはり信用保証協会ですよねという思いがあるので、オーケーを出さなければ融資されないわけですから、その辺についてはいかがですか。","respondent":"山崎商業・ものづくり課長","answer":"そういうこともありますので、区では直接、事業承継設備投資ということで、補助の支援メニューもあわせてつくっているです。","id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"お金は出ない。融資はされないということです。だから区は、今までもそうだったのですけれども、そこをどう捉えていくかです。融資を受けたい。いつもと同じ流れです。そのとき、出なかった先は、しようがないのです、信用保証協会がオーケーしなければ出せないのですとなってしまうと、その後の融資はどうなっていくか。行政としての限界はあるのですけれども、最後にその辺についてはいかがですか。","respondent":"山崎商業・ものづくり課長","answer":"そうした協力といいますか、地域経済を盛り上げる一員としての役割が、この事業をスタートする前よりは着実に協力をいただいて増えているのは事実です。","id":"exchange-017"},{"speaker":"浅野副委員長","kind":"質問","question":"そのような中で、経営者に育てていくというのは１つの大きな目標と伺っておりますけれども、例えば、ここにもありますように、後継者世代の仲間づくりのようなことも進めていくということなのです。これは、実際に今どのような形で実績として上がっているのか教えていただければと思います。","respondent":"山崎商業・ものづくり課長","answer":"そこが、すごく付加的な効果が出たなと、私も捉えているところです。こうしたことを今年度、あるいは今後も続けていくことによって、さらなる次世代のたくましい経営者が品川区の中で１人でも多く育っていっていただくことを目指したいなと思うところです。","id":"exchange-018"},{"speaker":"浅野副委員長","kind":"意見","question":"若い世代が育つことによって、区内の活性化ということも出てくると思います。同じ業種でやられている方も当然おられると思いますけれども、長く連携をとりながら、品川区の発展に寄与できるような人材を育てていただければと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/997088?Template=document&Id=2824#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":20412,"voices":59}},{"id":"h30-20181030-7","meetingId":"h30-cm10","date":"2018年10月30日","dateIso":"2018-10-30","committee":"厚生委員会","time":"午後１０時００分～午後 ３時１４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件抜き出しています。","topics":[{"id":"topic-01","title":"平成２９年度指定管理者の管理に対するモニタリング評価の結果","agenda":"平成２９年度指定管理者の管理に対するモニタリング評価の結果","exchanges":[{"speaker":"石田（ち）委員","kind":"提案","question":"ですので、全体的なことになるのですけれども、それぞれの事業者がどういった事業計画を立てているのか、毎年毎年その事業計画が出されるわけですね。ですので、そういった改善をしていただけると、私たちもさらに見やすく、そしてどういう事業がされているのかというのが大もとからわかってくると思いますので、ぜひ総括シートの改善の検討をしていただけたらと思うのですけれども、いかがでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"何かもうどうしてもこれだと用をなさないとか、見づらいとかいうことであれば、それは検討を引き続きしていきたいとは思っておりますが、まず、いろいろな経過を経てこの形で今おさまっているというのがあります。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これは要望とします。その件数の中身として、骨折何件とか打撲何件、薬の事故何件という形で、事故がこれだけあったということも書かれているので、これだけだとどれだけあったのか、どのような事故があったのかということでまた質問が細かくなっていってしまうので、ぜひそういったものもわかりやすくしていただけたらと思うのですけれども、これは１つこの総括シートへの要望です。","respondent":"寺嶋高齢者福祉課長","answer":"あざ等につきましては、それが明らかに虐待が疑われるという事例がある場合については、虐待を担当している支援係というのがありますので、そちらの職員が現場に行ったり職員から聞き取りをしたりということで、きちんと対応しているということで。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"私も上大崎特別養護老人ホームは新しくできたので、ちょっとお話を伺いに行ったときに、職員が最初すごくたくさん応募して、それで入ってきたのだけれども、大量に辞めていってしまったというお話も事業者の方がされていたのですけれども、今は「余裕を持って採用しており、想定内であった」となっていますけれども、今の職員体制と離職率というのが出ていたらわかるのですけれども。","respondent":"寺嶋高齢者福祉課長","answer":"それと、離職率の考え方なのですけれども、国の統計でとっている離職率は例えば新規採用から３年以内に辞めた人といったとり方をしていると聞いているのですが、実際には介護現場については中途採用が多いということもありますので、まずその定員をきちんと満たしていて。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"次に行きたいと思うのですけれども、６５ページの西大井つばさの家ですけれども、ここの収支のところに「西大井福祉園と一体である」となっていまして、やはり別の事業所で内容も違うわけですから、ちょっとここは別々にしっかりとそれぞれの事業所の収支を出すべきではないかと思うのですけれども、そこはどうかということと、あと。","respondent":"松山障害者福祉課長","answer":"１点目、収支の表記の問題ですけれども、こちらは実際に分けられるものか、どのような表記がわかりやすいか等々、今後検討をしていきたいと考えています。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"わかりました。事業報告が一緒になってしまっているとなると、本当に見えなくなってくると思うのです。そういうところで、そういった再委託という問題も本当に見えなくさせられてきていると思いますので、やはり別々にしっかりと収支等々を分けるべきだと思っていますので、そこは言っておきたいと思います。区の施設が老朽化をしてきているのですけれども、区としてはどのようにお考えなのでしょうか。","respondent":"宮尾高齢者地域支援課長","answer":"こういったものに関しては計画的に全体の施設整備の部門ともしっかりと連携を密にとって、区全体の改修計画の考え方とも整合性をとり、そして居住者の方に迷惑とならないように、計画的に進めていきたいと考えています。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"改善が必要とされた原因の分析のところにどの高齢者住宅も同じように書かれているので、やはり老朽化というのをどうにかしたいという思いでいると思いますので、そこは丁寧にやっていただきたいと思います。それと、高齢者住宅で「高齢者を狙った犯罪のターゲットになりやすく」という、これも全部の高齢者住宅が言っているのですけれども、被害というのは高齢者住宅で出てしまっているのでしょうか。","respondent":"宮尾高齢者地域支援課長","answer":"ですので、安易に知らない方が入ってくることに対しては、積極的にきちんと声かけを行うなどの見回りをいつも以上にお願いしているとともに、これからも、例えばハード的に防犯カメラ等設置できないかといったこともあわせて検討していきたいと考えています。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"意見","question":"やはり高齢者を狙った犯罪というのが本当に後を絶たないと思っていますので、また手口もいろいろ多様化しているので、こうした高齢者住宅と銘打っているとやはり高齢者が集まっているところとなってくるので、そこの住民への対策等々はさらにやっていただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"確認","question":"全体的な確認なのですけれども、平成２８年度の評価と平成２９年度の評価とを比べたときに、例えば改善が必要な事項が平成２８年度に出ていて、それが平成２９年度でも同じものが出ているというのはあるものなのかというのをちょっと確認します。どこの所管になるのかわかりませんけれども、それぞれ違うけれども、どこか代表的なもので。","respondent":"寺嶋高齢者福祉課長","answer":"それで、例えば１つとしては、認知症に対しては区も一緒に対策会議を開いて、あり方の検討とか効果的な策の取り組みということを一緒に考え、区も一緒になって改善に向けて支援しています。","id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今、お話のあった事故とか、利用率が大変厳しい状況の中で出てくるのはしようがないかと思うのですけれども、例えば、理学療法士が足りないから採用したいというのがあったと思うのですけれども、そういうところは、その後区としてそことの折衝、このモニタリングが終わった後に現状どうなっているのか、その辺のチェックは普段とられているのでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"ここに記載した理学療法士につきましては、細かく言うと２名のうち１名が産休に入ってしまったという個別の事情がありまして、その間の補充がなかなかうまくいかなかったと聞いておりますが、その後の補充はきちんと対応できていると。","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"どこもうまく区と連携をとって運営ができるように、またこれからもよろしく。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"こんの委員","kind":"質問・要望","question":"全体的にお聞きしたいことが、このようにモニタリングで自己分析をして、自己課題を改善をしていくというこのシートを経営会議で評価をされるというところで、いわゆる自己分析、自己課題、自己改善をするほかに、区として指定管理者に、区民の方はこういう要望がありますよ、こういうことを改善してほしいですよということが個別で入ってくる案件もあるかと思うのですが、そういうものと。","respondent":"寺嶋高齢者福祉課長","answer":"勘違いも含めて、制度的な問題でできないことに対してもやはりやってほしいみたいなときに、区のほうに要望が寄せられて、こういうことを施設に言ったのだけれどもうまくいかなかったから、区に来るということは結構多いので、いきなり区に来ることはなかなかないのですけれども。","id":"exchange-011"},{"speaker":"こんの委員","kind":"質問・要望","question":"先ほど鈴木（真）委員からもあった、前年度、今年度、毎年同じような課題が挙がってくる話の中で、稼働率というところで、要するにニーズをしっかり捉えて、そこをどのように応えてあげられるかというところが稼働率にもかかわってくるとなると、その辺の事業所が思っているニーズと、区が押さえているニーズとの連携で。","respondent":"寺嶋高齢者福祉課長","answer":"例えば特別養護老人ホームにつきましては、福祉避難所という位置づけになっておりまして、統一したマニュアル等もありますので、施設の中でさらにプラスで独自に取り組んでいただいていることはありますけれども、まず福祉避難所の機能ということも含めまして。","id":"exchange-012"},{"speaker":"こんの委員","kind":"質問・要望","question":"今、高齢者施設をお伺いしましたので、例えば高齢者住宅に関しては、管理人という方が常時いるところといないところとがあるでしょうし、そこら辺の災害時の対応はどうなっているかというのと、あわせて障害者施設は、先ほど自分で助けを求められるようにしようとしているということですが、具体的にどのようにされているのか、お伺いしたいと思います。","respondent":"宮尾高齢者地域支援課長、松山障害者福祉課長","answer":"ただ、それで災害時の対応に差があってはいけないことだと捉えておりますので、管理人が同居する、していないにかかわらず、同じ対応ができるように施設側にも求めているところです。委員お尋ねの第三者の方に助けを求める訓練の具体的なあり方なのですけれども、例えば施設外の外出先を想定しまして、お１人だというところで、電話のかけ方、あるいは使い方、誰に、どこで。","id":"exchange-013"},{"speaker":"こんの委員","kind":"質問・要望","question":"管理人がいるところといないところで本当に差があってはいけないと思うのですけれども、災害時の緊急対応のときに、以前、やはり管理人が常駐されていないところでの対応というのは、結構誰にどう助けを求めていいかというのがあって、結局その管理人にご自宅からその現場に駆けつけてもらったといったことが結構このところあるのですけれども。","respondent":"宮尾高齢者地域支援課長、松山障害者福祉課長","answer":"管理人が例えばちょっとご旅行ですとか、長期にわたってご不在されるような場合には、区のほうに届けをしてもらって、その場合、例えばシルバー人材にその間行ってもらうような対応も実際にはさせていただいているところです。委員ご指摘のヘルプカードの活用の仕方も、同じように訓練に含めておりまして、その他電話は、災害用伝言ダイヤル１７１にかける練習をしているです。","id":"exchange-014"},{"speaker":"こんの委員","kind":"質問・要望","question":"特に障害者の方々についても、災害時の要望というのはかなり挙がっていると思いますので、そうした利用者とご家族の保護者の方にもきちんとそういう体制をとって、こういうことをしているというのは多分もう周知はされていることと思いますけれども、何度言ってもやはりそうやって周知を図っていくということの体制は大事だと思いますので、その点、何かありましたらばご答弁いただきたいと思いますが。","respondent":"松山障害者福祉課長","answer":"ご利用者とご家族への説明、周知についてですけれども、区のほうにもそのお声というのは入ってきておりますし、必要なことだと認識をしております。","id":"exchange-015"},{"speaker":"こんの委員","kind":"質問・要望","question":"ありがとうございました。個別で、これはどのように数字を見たらいいのかというところなのですけれども、特別養護老人ホームの利用率ですけれども、待機者がかなりいる中で、稼働率がなぜ１００％いっていないのか、この数字はどのように見たらいいのでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"例えばそういった場合に利用率は１００を切っていくということが、一番大きな理由として挙げられます。","id":"exchange-016"},{"speaker":"こんの委員","kind":"質問","question":"わかりました。そうすると、特別養護老人ホームは非常に利用者のニーズも高いところでありますが、区としても、この特別養護老人ホームに対しては今後も考えていく方向なり、対応なりというのがあると思いますので、ぜひそういったことで稼働率が１００％行かない理由はわかりましたけれども、その点もよろしくお願いしたいと思います。何かご答弁ありましたらお願いします。","respondent":"寺嶋高齢者福祉課長","answer":"入院前の状況をよく把握して、速やかな対応に努めるといったコメントをしていた法人もありました。その辺については効率よく使っていきたいということ。","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それと、８ページのところに、これは大崎在宅サービスセンターなのですけれども、やはり４番のところなのですが、「重度の認知症状のある方や、胃ろう、腸ろうの方などの中重度者の受け入れも積極的に実施し、介護職員や看護師等の適切な人員配置を行った」とあるのですけれども、この胃ろうとか在宅酸素の方ですとか、バルーン、カテーテルだったりとかインシュリンだったりとか。","respondent":"寺嶋高齢者福祉課長","answer":"それが１点目です。それから、８ページのこちらは胃ろう等医療対応なのですけれども、まずデイサービスについては、医療対応について必ずしも必須という形での配置は義務づけられてはいないのですけれども、ご要望もあるので、可能なところはやっているという今の実態です。","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"わかりました。５３ページの平塚橋ゆうゆうプラザなのですけれども、事業報告に添付した管理運営実績というところで、有料利用件数というのが５４５件と書かれているのですけれども、これはミニデイということで考えてよいのでしょうか。そしてまた、３,７４７万円くらいが委託料ということで書かれているのですけれども、人件費はどれくらいになるのかという内訳がわかったら教えていただきたいと思います。","respondent":"宮尾高齢者地域支援課長、寺嶋高齢者福祉課長","answer":"その件数が、平成２９年度１年間で５４５件あったです。管理運営委託料の３,７００万円余に関してですが、こちらはやはり従事する人件費が一番大きくなってきております。そういった対応も含めていろいろな手を打っているというのが、今の上大崎特別養護老人ホームの状況です。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そういう点では、そういう告発もあって調査されたけれども、虐待ということではなかったということで、そういう事故ももう起こさないようにという対策がとられるという判断ということでよろしいでしょうか。それからあともう一つ、これはショートステイの利用率が５７.３％ということで、ここはたしかショートステイが４０床ぐらいありましたよね。","respondent":"寺嶋高齢者福祉課長","answer":"この利用率が低いのは、全体の話にかかわるのですけれども、やはり段階的に受付をしていった関係で、初年度かなり低く出ているのは、その辺の受け入れをある程度職員が慣れてくるまでたくさんは入れられないのでということも含めて。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"続いて５７ページ、西大井福祉園なのですが、すごく利用率が高くて１２５％までは受け入れ可能だけれども、１２５％を超えると減算になってしまうということなのでしょうか。その１２５％を超えてしまったのが３カ月あって、３カ月が減算。","respondent":"寺嶋高齢者福祉課長、松山障害者福祉課長","answer":"上大崎特別養護老人ホームの看護職員ですけれども、看護師、介護士合わせてオープンからしばらくの間入れ替わりがあったというのはまさしく事実ですが、今はかなり落ち着いていると、これも先ほど申し上げたとおりですけれども、今現在。その前のページの心身障害者福祉会館なのですけれども、対応方針のところで書かせていただいたのですが、やはりアピール不足であろうという分析をしております。","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それからあと、６１ページのフリーユニティーのゆうゆうのところなのですけれども、これは八潮と、それから戸越と、両方委託をしていると思うのですけれども、これは来年総合支援施設ができた場合はこちらはそっくりそのまま戻るとここはもう空くという形になっていくのでしょうか。","respondent":"松山障害者福祉課長","answer":"もう一つ、西大井のほうですが、ちょっと申し訳ありません。手元には一体の資料になっております。それをわかりやすくできるかどうかについては、今後検討してまいります。","id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほどのフリーユニティーのことなのですけれども、それはこの事業がそのまま総合支援施設に入るということではなくて、総合支援施設に入るときはもっと人員とか何かも増やして、それをもう既に７月から確保していると、それで半年延びるとなると、その確保がどうなるのかというあたりもあるのではないかと思いますので、そこら辺のところは事業者のことで延びるわけではないので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"若林委員","kind":"質問","question":"２３ページの八潮南特別養護老人ホームの改善が必要な事項に、「収支状況の改善」とあるのですけれども、利用率を見ると、いわゆるホームのほうが９４.８％ということで、それほど低いとは思えないのです。そういう物理的な制約があって、その上でさらに収支状況の改善というのは、どのようにしたら、どういうことをやったら改善するのかという何か手立てがあるのですか。","respondent":"寺嶋高齢者福祉課長","answer":"それで採算が取れるようになっているのですけれども、ここについてはまだそういった概念がちょうど世の中に出始めたころの改築であって、実際にはいわゆる多床室と同じような介護報酬しか入ってきていないということもありまして。","id":"exchange-024"},{"speaker":"若林委員","kind":"質問","question":"３１ページの小山地域密着型多機能ホームの一番下の改善が必要とされたというところで「利用者中心のケアが徹底できている」と。これは非常にすばらしい評価ですね。ただ、その「近隣以外の区内・都内等での発信の機会を作ることができていない」という、これはどういう意味でしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"小山地域密着型多機能ホームについては、例えば利用率のところでショートステイが比較的低めにはなっているのですけれども、通いとかそういった訪問のところ力の入れ方が特徴的なことをやって。","id":"exchange-025"},{"speaker":"若林委員","kind":"質問","question":"これは議論が大いにあっていいことなのですけれども、これを改善することによって、ほかの区内のいわゆる多機能ホームとか、今認知症デイとか認知症対応の施設に、この施設で行っていることの成果を共有したり、また波及をしていくということは、それは評価としてすごく公の施設としていいと思うのですけれども、それを区外とか都外に、それは事業者としての企業理念としてはわかるような気もしますけれども。","respondent":"寺嶋高齢者福祉課長","answer":"１つはご指摘の部分、ごもっともなところももちろんあるのですけれども、その１つ上に「離職率の低下には対策はできたが」という記述があるように、やはりどこの法人も職員の離職の防止だとか確保等に力を入れているといったところで。","id":"exchange-026"},{"speaker":"若林委員","kind":"意見","question":"何年かこの厚生委員会に所属させていただいて、特別養護老人ホーム等の施設でモニタリングの記述の中で、いわゆる介護度の改善についての記述があったと記憶をしているのですけれども、そこら辺、今回はいわゆる介護度が改善できましたとか、そういう評価は一切ないのですけれども、これはさっきもあったけれども。","respondent":"寺嶋高齢者福祉課長","answer":"そちらで全特別養護老人ホーム対象に、ほかの施設もありますけれども、この事業は定着してきているということで、その部分の改善については、おそらくその事業の中で区のほうにしっかり報告をして共有ができているという認識のもとに。","id":"exchange-027"}]},{"id":"topic-02","title":"障害者包括支援相談体制の構築検討委託事業者の選定","agenda":"障害者包括支援相談体制の構築検討委託事業者の選定","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"この障害者包括支援相談体制の構築検討委託事業者を選定したということなのですが、この検討を進めていくということ自体を障害者当事者の皆さんに説明はされてきたのでしょうか。ここでヒアリングというのが事業内容のところで出てくるのですけれども、この検討そのものを進めていくという説明はされたのか、伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"こちらの検討を進めていくことにつきましては、地域自立支援協議会、あるいは７団体の会長のほうにはもうお伝えさせていただき、これから皆様が相談しやすい体制をつくっていきますので、ぜひヒアリングにご協力くださいということで、ご承諾いただいております。","id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問","question":"団体に入っていない方のほうが多いのではないですか。それで、その入っていない人の声というのはどうやって聞くのか。団体といっても、おそらく役員中心なのではないかと思うのですけれども、役員以外の人の声というのも、団体全体の声というのはどのように聞いていくのか、そしてその検討を進めていくに当たっても、もう少し広く進めていきますというのをお知らせする方法は考えていないのでしょうか。","respondent":"松山障害者福祉課長","answer":"これから検討を進めるということなので、もちろんさまざまなお声は頂戴したいと考えています。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私はより広く聞いていくべきだと、今の課長の話なのですけれども、それをやはり実行していってほしいと思うのですけれども、先ほど７団体以外１０以上の団体とおっしゃったのは、７団体以外にプラス１０以上の団体に計画策定のときは話を聞いた、そこにも今回聞いていくということなのでしょうか。","respondent":"松山障害者福祉課長","answer":"ただ、今後これから検討するということなので、当然民間の事業者にもご意見は伺いますし、あるいは在宅介護支援センターのケアマネジャー、高齢障害者の方、あるいは高次脳機能障害の方を実際に支援しているケアマネジャーにも意見を伺い。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"なので、そういったところにもぜひ声を聞くべきではないかと思いますので、そこはぜひ検討していただきたいと思います。それとこの公募要領のところに、進捗状況を定期的に報告する、２カ月に１回ということだったり、あと業務内容に係る報告書、あと成果報告書を求めているのですけれども、これらはいつ報告されるのか、スケジュールなどが決まっていれば教えていただきたいのです。","respondent":"松山障害者福祉課長","answer":"そのヒアリングを踏まえて集約していただいて、整理・分析していただくということになっております。その中間で、地域自立支援協議会に報告をすることになっており、また、成果報告書については、３月末を予定しております。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問","question":"わかりました。この進捗状況定期報告書、進捗なのでまさにそうなのですけれども、こういった報告は、今ある先ほど言った進捗状況とか業務内容、成果報告書は、地域自立支援協議会に全部報告はされていくのですか。厚生委員会にも報告等はあるのか、聞かせてください。","respondent":"松山障害者福祉課長","answer":"もちろん厚生委員会へのご報告は中間報告ということでさせていただきたいと考えています。地域自立支援協議会の皆様方にもご報告し、お諮りし、そこでご意見をいただければと考えています。","id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問","question":"今、地域自立支援協議会にもということで、先ほどの部会にも意見を聞いてということだったのですが、この間の一般質問のときに、鈴木ひろ子議員がこの障害者包括支援相談体制のことについて質問したときに、答弁で、地域自立支援協議会相談支援部会の委員へのヒアリングもしていくとあったのですけれども、今そこで話も聞いていくという説明があったのですけれども、この部会にいらっしゃる方々は何人で。","respondent":"松山障害者福祉課長","answer":"相談支援部会ですので、拠点相談支援センターにいらっしゃる相談員の方々、それから現在指定をとっております民間の事業者の方々となっております。","id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問","question":"地域自立支援協議会で報告もされるということなのですけれども、そういう中で検討もしていくということだったのですが、地域自立支援協議会の中でも、あくまでも地域自立支援協議会が主体だというふうに、会長たちもこうしたことを進めていくに当たっては主体はこちらだということを強くおっしゃっていたのですけれども、こうした検討を進めた上で。","respondent":"松山障害者福祉課長","answer":"地域自立支援協議会につきましては、やはり地域でいかに障害者の方が住みやすい地域をつくっていくかというようなことを協議する場ですので、地域自立支援協議会が決定権を持つというよりは協議をする場でありますので。","id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問","question":"その意見を聞きながらという中に、地域自立支援協議会の中でこの間もお話の中では承服しかねるという厳しい声もあったのですけれども、これは、地域自立支援協議会との話し合いの中で、お互いによしとなった段階で進めていくということで、地域自立支援協議会が難色を示しているもとで進んでいくというものではないということですか。","respondent":"松山障害者福祉課長","answer":"なかなかお電話しても反応が遅いというようなお声も出ておりますので、相談支援体制につきましては、区としてはやはり地域で相談しやすい体制をつくるということが非常に重要と考えておりますので、結論としては、地域自立支援協議会で当事者のお声を聞きながらではありますが。","id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、裏面の選定理由のところの株式会社ナレッジ・マネジメント・ケア研究所で決まっていったということなのですけれども、この公募要領にも、応募資格の１番に品川区の福祉現場の状況に精通していることとあるのですけれども、この株式会社ナレッジ・マネジメント・ケア研究所は、この間品川区に何か精通している部分があったのでしょうか。そこを教えてください。","respondent":"松山障害者福祉課長","answer":"人材配置につきましても、在宅支援センターの特性を考えると、やはり障害福祉の知識を持つ専門職の配置が望ましいというようなご提案もいただいておりますので、きちんと品川区のことを踏まえている会社だと認識しています。","id":"exchange-036"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、ではアドバイス等は受けていたけれども、直接計画を立てたり、そういうことはこの間はしてこなかった事業者であるということですか。","respondent":"松山障害者福祉課長","answer":"ほかの地方自治体の地域福祉計画ですとか、障害者福祉計画ですとか、介護福祉計画のほうには策定支援をしている実績等はありますが、品川区の場合につきましては、計画の策定には携わってはおりません。","id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"障害者団体の１０団体ということだったのですけれども、具体的に７団体以外の３団体というのがどこなのか、教えていただけないでしょうか。","respondent":"松山障害者福祉課長","answer":"それから障害者福祉を考える会。この４団体で、あと、それから７団体のうち１団体はちょっとご都合が悪かったので除いておりますが、広く全般的にさまざまな区が把握している障害者団体にはご意見を頂戴したいと考えています。","id":"exchange-038"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"ヒアリングはこれから始めるというところなのですけれども、２つ目の相談支援専門員の配置・研修・スケジュール・事業費等を含む相談支援体制整備に向けた支援というところなのですけれども、先ほど相談支援専門員のきちんとした障害者の知識を持った人の配置が必要だろうという提案があったということだったのですけれども、区としては。","respondent":"松山障害者福祉課長","answer":"次年度につきましては、例えば民間の相談支援事業所の誘致も含めまして考えてはいきたいと思っています。在宅介護支援センターの相談員の配置というのも、モデルとしてできないだろうか、その可能性があるのかどうかも含めての検討ということをしていきたいと考えています。","id":"exchange-039"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ぜひ本当に課題等いろいろと分析もしながら、どういうあり方が一番いいのかというのは、本当に重々いろいろ検討していただいてやっていただきたいと思うのですけれども、では、もう来年の４月から在宅介護支援センターに３カ所つけて始まるという、それありきではないというところの確認だけ、ちょっとお願いしたいと思います。","respondent":"松山障害者福祉課長","answer":"次年度についてなのですが、やはり東京都の研修が５月か６月ぐらいに実際ありますので、４月にその人材が確保できたとしても、その方が資格を既に持っている場合は別かもしれませんが、ただ初めての試みということで相談については丁寧に進めていきたいと考えていますので。","id":"exchange-040"},{"speaker":"若林委員","kind":"質問","question":"さっきの１１月前半、１１月後半の話があって、いわゆる部会がその中であって、１２月以降、地域自立支援協議会がまず何回開かれるのか、何月ころどのぐらい開かれるのかというスケジュールと、やはり前回の地域自立支援協議会で、会長も含めて、いわゆるこの区の発表については決定者としての品川区。","respondent":"松山障害者福祉課長","answer":"今後の進め方ですが、先ほど伝えさせていただきましたけれども、１１月中には事業者へのヒアリング、それからご利用者の方へのヒアリングを行いまして、１２月に予定しております地域自立支援協議会の全体会。","id":"exchange-041"}]},{"id":"topic-03","title":"品川区立心身障害者福祉会館の運営事業者の選定","agenda":"品川区立心身障害者福祉会館の運営事業者の選定","exchanges":[{"speaker":"石田（ち）委員","kind":"意見","question":"両方とも人材の用意ができずということなのですけれども、昨日の多世代交流施設も１事業者が辞退して、実質１事業者ということで決まっているのですけれども、心身障害者福祉会館においては、やはり現状を変えたいと思ってプロポーザルをしたのではないかと私は思うのですけれども、それで新しい事業をやりたいと思って。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"石田（ち）委員","kind":"質問","question":"なので、品川区の事業に魅力がないのかと思ってしまうのですけれども、なぜなのかというのを区としても考えたほうがいいのではないかというぐらい、これしか来ないという思いが私はしているのですけれども、そこら辺はどのようにお考えでしょうか。","respondent":"松山障害者福祉課長","answer":"それで荏原地区の地域生活拠点として機能させるためというのが大きな公募の趣旨です。実はこの辞退された事業者も、実際に説明会あるいはその後の現場の施設見学にも来まして、提案書ぎりぎりまでやり取りはございました。","id":"exchange-043"},{"speaker":"石田（ち）委員","kind":"提案","question":"新たな事業をそのままくっつけるということでこのまま進めることもできたわけじゃないですか。そしてまたやはり医療的ケアだったりリハビリだったりというところでは、専門職が必要だと思うのですけれども、それはどのくらい配置をされるのか。今までの品川総合福祉センターでしっかりそれが確保できることになったということで選定されたと思うのですけれども、そこはどうなのか伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"委員ご指摘の医療的な部分につきましては、看護師、あるいは医師の配置というのをご提案をいただいております。医師につきましては、これまで月１回ということでしたけれども、週に１回ということでご提案いただいているところです。","id":"exchange-044"},{"speaker":"石田（ち）委員","kind":"提案","question":"そうすると、どのような人員体制でというところまではまだ決まっていなくて、看護師と医師が週１回という提案をされているというところでわかりました。それで、「別紙のとおり条件を付した上での選定とする」というのですね。要は今までの事業者だけれども、適材適所ではなかったという思いが区にはあったのか、そこら辺を伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"あるいは高次脳機能障害の方もいらっしゃる。あるいはボランティアに対しても、障害者団体への対応等、さまざまなありとあらゆる障害の方がいらっしゃいますので、その障害種別、あるいはその方に合わせたそれぞれの対応というのが必要になってきます。","id":"exchange-045"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この選定会議の選定委員のメンバーを教えていただきたいのと、それから新たな機能ということで、リハビリ機能の強化と、医療的ケアが必要な利用者の受け入れということなのですけれども、心身障害者福祉会館はそれほど広く余っているという感じがどうもしないのですけれども、スペース的にはあるのかというあたりと、その医療的ケアが必要な利用者の受け入れというのは。","respondent":"松山障害者福祉課長","answer":"看護師においてももう既に２名配置しておりますので、重度の方に対しても既に支援ができている看護師がもう前もって整備をしているです。それから、リハビリ機能の強化ということで、確かに理学療法士等の、専門職も当然増やす予定です。","id":"exchange-046"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"これは来年４月から開始ということでいいのですよね。平成２９年度の今回のモニタリングのところで１億４,０００万円という委託料が出ていると思うのですけれども、それが新しい事業が増えることでどれぐらい増えるのかという提案も出されているのではないかと思うのですけれども、そこのところも教えていただきたいと思います。","respondent":"松山障害者福祉課長","answer":"委託料の金額については、今後来年度の予算の話になりますので、今、幾らぐらいということは、配置する人数や人件費部分にもかかわってくるものだと思いますので、今後予算に向けて精査をしていくということになろうかと思います。","id":"exchange-047"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"それからあと、昨日も品川総合福祉センターの虐待の陳情も出されて、審査もされたところなのですけれども、いろいろ区としても虐待の対応をずっとされてきて、そこの改善計画のところで、虐待防止委員会の設置と、それは設置されていると思うのですけれども、どのようなメンバーで構成されているのかということと。","respondent":"松山障害者福祉課長","answer":"国の手引きに準拠した研修ですけれども、先ほどの説明資料の中の（４）の法人として中期経営計画を立てということで、中期経営計画を法人として平成３０年から平成３２年度計画ということで３年間の計画を策定をしております。","id":"exchange-048"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"本当にこれだけ区も入って、さまざま大変な状況をクリアしてきたというところでは、これを教訓にして、今回そうは言ってもこのように異例の別紙のとおり条件を付した上での選定、１事業者しか来なかったということで、品川総合福祉センターが再び選定されるということになりましたので、ぜひ区もしっかりと支援に入っていただいて、人権が守られるような中身を充実させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"こんの委員","kind":"確認","question":"いよいよ開始ということでありがたいと思います。それで確認は、スケジュール管理なので、こういう機能はついていますかという確認をしたいのですけれども、あくまでもスケジュール管理、いわゆる生年月日を入れるといついつに接種しましょうというお知らせが来るということで、接種後にその子がちゃんと接種しました、終わりましたという記録を残す機能はついているのでしょうか。","respondent":"鷹箸保健予防課長","answer":"生年月日を登録します。一番初めですと、今２カ月から予防接種が始まりますけれども、そのお知らせが来て、接種が終わると、終わりましたというのを今度保護者の方が入れていただくと、それも記録として残ります。","id":"exchange-050"},{"speaker":"若林委員","kind":"確認","question":"１０月２６日に、東京都知事のほうで全く同じ内容と私は認識しているのですが、発表が行われました。都の発表の内容と同じ内容のものなのかという確認です。ということは、都の助成、補助金で全部賄って、区の単費での支出はないのかという確認をします。","respondent":"鷹箸保健予防課長","answer":"今、その対象変更前と対象変更後についてご報告させていただいたのは、あくまでも品川区の対象でございまして、東京都でこれまで対象としていたのは、先ほどご説明させていただいた中で、（１）妊娠を予定または希望する女性を東京都ではこれまで包括補助の対象としておりまして。","id":"exchange-051"},{"speaker":"石田（ち）委員","kind":"質問","question":"この対象拡大の前と後で、どれぐらい対象人数が増えるか、大枠でそういう想定はあるのでしょうか。","respondent":"鷹箸保健予防課長","answer":"対象拡大をしなくても、見込みとしては当初１,２００件だったところを、その半分増、１,８５０件ぐらいに増えると見込んでいたところですが、対象を拡大したことによってプラス３００件程度で、今の見込みでは概ね２,２００件ぐらい。","id":"exchange-052"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"具体的に抗体検査の予算というのが、検査とそれから予防接種それぞれ今年幾らぐらいになるのかというところだけ教えてください。","respondent":"鷹箸保健予防課長","answer":"抗体検査１件当たりが６,２４２円、予防接種が１万５０２円となっておりますので、それを掛けた額ということで、もともとの予算が１,２００万円ぐらいだったところ、対象拡大後は２,４００万円足らなくなるので、３,６００万円ぐらいかかるということを予想しております。","id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/246103?Template=document&Id=3522#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":73394,"voices":149}},{"id":"h30-20181030-8","meetingId":"h30-cm10","date":"2018年10月30日","dateIso":"2018-10-30","committee":"建設委員会","time":"午前１０時００分～午後 ０時５０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件抜き出しています。","topics":[{"id":"topic-01","title":"体験型環境学習施設の整備","agenda":"体験型環境学習施設の整備","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それと、公園の中につくるということで、ちょうど建設予定地のところが、若干ではありますが、お子さんが遊べるスペースになっていまして、私も娘が小さいので、こちらで、違うところにもありますけれども、ここにもそういった遊具などもあるということなので、子どもたちが楽しむ親水スポットなどもありますので、そういったところの配慮というのはあると思うのですけれども。","respondent":"小林環境課長、溝口公園課長","answer":"１点目、そもそもなぜというところかと思います。区としては２点あると考えております。１点目ですが、先ほどもご説明しましたとおり、学びへの需要の高まりというところがあるかと考えております。環境学習施設も公園としっかり連携を図って、つくっておしまいではありませんので、つくった後、どういう形でのフィールドワークをやっていくのか、そういったところも今後、環境課と連携しながら、さらに深度化していき。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"ぜひよろしくお願いいたします。どのような意見交換の場を設けて、またそれがどのくらい反映されたのか伺いたいと思います。それと、環境情報活動センターですけれども、もともと区役所の防災センターにあったものが、こみゅぷら八潮に移って今活動しているわけですが、将来的にはこの施設などに入ったりするのかというところはどうなのかお伺いします。","respondent":"小林環境課長","answer":"２点目ですが、こみゅぷら八潮に今ある施設の機能につきましては、基本的には環境に関する類似の施設ですので、最終的には戸越公園に集約されると考えております。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"中途半端な施設にしても意味がないと思いますので、しっかりとした内容で、展示の内容を決めてほしいと思います。ここに「温暖化の現状や適応・緩和策を学習」とありますけれども、具体的にはどういった内容の展示になるのか教えていただきたいと思います。それが１点です。この点もお伺いします。","respondent":"小林環境課長","answer":"その中身、内容等についてなのですが、やはり先ほども申し上げましたとおり、区民の皆さんが非常に関心が高い内容、環境に対する関心が非常に高いということはあるものの、やはり何をしていいかわからないとか。","id":"exchange-003"},{"speaker":"安藤委員","kind":"意見","question":"身近なところから、何をしていいかというのはすごく大事だと思うのですが、やはり環境問題というのはいろいろなところに大きくかかわってくる問題だし、それぞれの方々がそれぞれの努力をしていくというのはものすごく大事なのですけれども、ただ、それだけでは決して解決できない問題というのがありますので、そういった視点にとどまらず、先ほど少し意見を述べさせていただきましたけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひとも、この体験型環境学習施設を、やはり子どもたちに対して積極的に伝えていっていただいて、活動していっていただきたいと考えておりますけれども、先ほど、社会科見学などで使われるという旨のご答弁がありましたけれども、そうした教育面で、子どもたちにどうやってこの施設に来ていただくのか、所管が違うのかもしれませんけれども、教育面でどのような活用方法を考えておられるのか。","respondent":"小林環境課長","answer":"そういった意見も参考にしながら、社会科見学の一環としてお話を聞いた中では、中学年の方が対象だというふうに聞いておりますが、そういったところの意見を聞きながら、最終的には取りまとめていくという考えです。","id":"exchange-005"},{"speaker":"筒井委員","kind":"質問・要望","question":"わかりました。施設についてなのですけれども、環境系の施設、先ほど、温暖化などの話も出ましたけれども、施設に太陽光発電やほかの再生可能エネルギーを利用した機器の導入などは考えておられないのでしょうか。ポイント制とか、そういったことを利用してつないでいくのかなというイメージを今持っているのですけれども、そのつなぐということで、どのようなことをお考えになっているのでしょうか。","respondent":"小林環境課長","answer":"区内のこういった施設を回遊することで、例えば、複数の施設に行くことによって、１つの情報発信ができるように、ホームページなどを含めて、各課連携を図りながら検討を進めている最中です。","id":"exchange-006"},{"speaker":"筒井委員","kind":"質問","question":"ぜひとも、そのつなぐという点で、こうした各種多様な施設がありますので、身内的な連携というものを図っていただいて、例えば、スタンプカードとか、楽しみながら品川区の施設を回っていただけるような仕組みづくりというのは一つおもしろいかと思うのですけれども、その辺のお考えなどはいかがでしょうか。","respondent":"小林環境課長","answer":"ポイントカードのご提案もいただいたところですが、そういったことを含めて、どういった形が回遊性として楽しめる方法なのかということにつきましては、引き続き検討に努めてまいりたいと考えております。","id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私どもの会派でもいろいろ話をして、うちの会派からもいろいろな話が出たので、幾つかお伺いをしたい点があるのですけれども、私が個人的に１つ確認をさせていただきたいのですけれども、先ほど、つなぐというところについての説明が詳細にあったのですが、このつくり出すという、「つなぐつづけるつくりだす」、つなぐ、つづけるはわかるのですけれども、つくりだすということで、にぎわいをつくり出す。","respondent":"小林環境課長","answer":"そのにぎわいの１つとしまして、例えば、公園利用者も一体的に利用できるウッドデッキの整備、あるいは親水スポットの整備というところ、例えば、例示として出していますが、それ以外のにぎわいの創り方等につきましては、引き続き検討を続けてまいりたいと考えております。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それと、済みません。これは、先ほど安藤委員からもありましたけれども、広い視野に立って、ぜひ、世界中が取り組んでいるのだよと言うことを、環境問題というのはやはりどうしても漠然としてしまうのですが、きちんと数値目標を持ってやっているのだよということを明確に示す指標になると思いますので、ぜひその点のコンセプトをとり入れていただきたいと思いますが、いかがでしょうか。","respondent":"小林環境課長","answer":"その一環として、先ほどご紹介いただきましたさまざまなイベントでの、今、フードドライブの実施について積極的に進めているところです。その中で得たアンケート結果など、区民の方の意識を見定めた上で、その辺についての検討は進めてまいりたいと考えております。","id":"exchange-009"},{"speaker":"大沢委員","kind":"意見","question":"環境学習施設、皆さんおっしゃったように、横文字ばかり、この環境に関することは多いのですけれども、その辺をどう子どもたちに説明をされていくのかで、学習、学びの場所ということなので、教育委員会との連携も必要、当然あると思いますけれども、どのような連携体制をとって、要は、教育、学びの上での教えるカリキュラムなのか、それとも形なのかというところで、どのような連携をとっていくのか。","respondent":"小林環境課長","answer":"八潮の近くには緑豊かなところもありますので、そういった講座については今現在も進めているところでございまして、八潮がある間は引き続き講座は運営していきたいと考えているところです。","id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"建設委員会なので、あくまでも箱についてお尋ねをしなければいけないのですけれども、頂戴しました資料の中に、ターゲットとして子どもを支える人、地域、学校ということなのですけれども、この学校、学校と称するもの全てだと思うのですけれども、どういう範囲の学校まで考えてらっしゃるのでしょうか。","respondent":"小林環境課長","answer":"一方で、他区との連携というのも非常に重要かと思っているところですが、それについては、非常にハードルが高いところもありますので、まずは区内全域のところはしっかりと考えていきたいと考えております。","id":"exchange-011"},{"speaker":"大沢委員","kind":"質問・要望","question":"学習をする人、逆に学習を与えるほうの立場になった場合に、近くに大崎高校もあったり、大学も幾つかあるわけですけれども、その辺と、今後の動き次第だとは思うのですけれども、そのあたりも視野に入れながら検討されていくような目線もお持ちだと思うのですけれども、そのプランを確認させていただきたいと思います。","respondent":"小林環境課長","answer":"それぞれのイベントとの連携というところでいけば、近くの大学、高校、小・中学校を含めて、連携・交流するためのスペースとして、例えば、先ほど口頭で申し上げましたが、企画展示をするようなスペースも検討しているところでございまして、そういった場での何か発表。","id":"exchange-012"},{"speaker":"大沢委員","kind":"質問","question":"これが離れた、例えば清泉とか、立正とか、離れたところになるとどうしても問題意識とか、親近感というのがどうしても湧かない、都立である、公立という部分で、多少なりともの距離感を縮められて、活動を一にしてできるのではないかと思うのですけれども、その辺はできるものなのでしょうか、できないものなのでしょうか、お考えと言うか、現状と言うか、都と区の教育に関する連携はできるものなのですか。","respondent":"小林環境課長","answer":"細かいところになると把握できない点はあるのですが、１つは、大崎高校と環境課のつき合いと言う中では、エコフェスティバルの中で、ボランティアとしても会場にお越しいただいている状況です。お互い協力して進めているところです。","id":"exchange-013"},{"speaker":"松永副委員長","kind":"質問","question":"私からは４点ありまして、１つ目は建設予定地付近にある事務所と公衆トイレについてなのですけれども、どのようになっていくのか。３つ目が、駐車・駐輪スペース等はあるのかどうか。４つ目が、区民への周知、また、現地まで行くサイン表示はどのように考えているのか、教えてください。","respondent":"溝口公園課長、小林環境課長","answer":"そういったところでいきますと、今現在ある事務所、また公衆便所があるところが予定されているところですが、そのほかにも、仮設が建ったりというお話もありますので、そういったところを総合的に踏まえて、公園の事務所、また公衆便所。周知についてですが、これから施設を建設していく、また整備していくところですが、周知についてはこれからさまざま検討していかなければいけないと考えておりますが、フェイスブックやツイッター、区のホームページ。","id":"exchange-014"},{"speaker":"松永副委員長","kind":"質問・要望","question":"駐車・駐輪に関しては、ぜひ誰もが利用する施設にするためには、障害を持った方々とか、そうした方々が利用できるように、ぜひ設置をしていただきたいと思います。先ほどのサイン表示についてなのですけれども、ご存じのように、戸越小学校体育館の前の歩道というのはやはり少し狭いというイメージがあるのですけれども、そこを道路課と連携して、安全なルートを確保できるような道順ですか。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-02","title":"平成３０年度ウォームビズキャンペーンの実施","agenda":"平成３０年度ウォームビズキャンペーンの実施","exchanges":[{"speaker":"横山委員","kind":"意見","question":"ご説明ありがとうございました。今回、こういう形でやられようとしたきっかけですとか、区の発信の仕方であったり、どういった情報が区民に効果的に届いて、それが１人１人の行動を変えていく、エコにつながると考えてらっしゃるのか、その考え方をお知らせください。","respondent":"小林環境課長","answer":"引き続き検討を進めてまいります。","id":"exchange-016"}]},{"id":"topic-03","title":"大井町駅前パブリックスペース設計コンペティションの結果","agenda":"大井町駅前パブリックスペース設計コンペティションの結果","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"それと、３３７の事務所からの参加表明で、２２７の提案作品がついているので、結構かなりの数かという印象があるのですけれども、反響は割と大きかったかと思うのですけれども、区としては、この反響の大きさの理由をどのように考えているかという点についてお伺いします。３点目は、今後公開コンペというやり方を広めていくのか、他に実施の予定はあるのかということをお伺いします。","respondent":"溝口公園課長","answer":"今回の公開コンペにつきましては、少し説明が足りなくて申しわけありませんが、ＪＩＡの日本全国の大会の開催に合わせて開催しているという形になっておりますので、参加者の方、事前に申し込みがあったとかではなくて、フリーで入れている関係で。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回のような形というのは、なかなか一般的には広められないとは思うのですが、ジェンダーフリートイレという視点というのは引き続き区全体として問題意識を持っていただきたいと考えています。そういった点で、この区ヒアリングということで、区としてはどういうことを、この選定に当たって考えを持っていたのか、それをどのように審査に反映させたのかという点だけ、最後にお聞かせください。","respondent":"溝口公園課長","answer":"建築家として３名、また、うちの行政職としても２名、計５名の審査員を用意して審査をしていったという過程を設けております。最終的に決定するに当たっては、やはり区の計画ですので、要領の中でも品川区が決定するという形をとらせていただいてコンペを開催したところです。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"提案","question":"今、最後の説明であったのですけれども、これはスケジュールで見ると平成３１年度が改修工事となっていますが、今、現状のものと全く違うような形、これだけで集客できるような、そういうもののご提案がされているというところで、これは本当に工事が間に合うのかということが１つと、あと、先ほど予算が膨らみ過ぎないかというところで、これは、予算は区の単費でやるのですかね。そのところ。","respondent":"溝口公園課長","answer":"先ほども少しご説明をさせていただいたところですが、来年の１月まで、まず設計に入らせていただきます。その後、３月に契約をさせていただいて、翌年度、１年間ぐらいかけて工事をやっていこうという考えでおります。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"ホームページに載っているものを見せていただいているのですけれども、先ほどのご答弁では、全てジェンダーフリートイレというような旨のご答弁がありましたけれども、ホームページに載っているＰＤＦの資料だと女子トイレとか男子トイレとかで分かれているような感じなのですけれども、そのあたり、どういったことなのかということと、あとは高さが違うのは。","respondent":"溝口公園課長","answer":"ジェンダーフリーの考え方、済みません。説明が悪くて申しわけありません。","id":"exchange-020"}]},{"id":"topic-04","title":"立会川における高潮発生時の避難基準","agenda":"立会川における高潮発生時の避難基準","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"昨年１０月２３日の高潮を受けて基準を定めたということなのですけれども、前回、平成２９年１０月２３日のときは基準がなかったということになるわけでしょうか。当時はどういった基準で、避難勧告まで出されたのだと思うのですけれども、そういった発令をしていたのか伺いたいのが１点です。","respondent":"持田河川下水道課長","answer":"その段階では基準というものは設けていなかったということです。気象庁の高潮警報の発令のタイミングですとか、あとは、実際の水位の状況などを見ながら、区としてその場で、いろいろ検討しまして避難勧告を出したというのが昨年度の対応でございました。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"今回は、避難情報緊急通知コールというのがありますよとポスティングするだけで、それでは大事なこういった情報というのが、やはり当事者の方々に十分に伝わらないのではないかと思うのですけれども、少なくとも、土砂災害と同じように説明会は開くべきなのではないかと思うのですけれども、いかがでしょうか。","respondent":"古巻防災課長","answer":"説明会に関してですけれども、まだ、資料の一番最後に、区民に対して町会を通じての周知のほか、避難情報緊急通知コールの登録案内等をポスティングということでしていますけれども、その後のさまざまな、説明会も含めまして。","id":"exchange-022"},{"speaker":"横山委員","kind":"質問","question":"こちらの保護者ですとか、対象地域の区民ということの範囲はどのように捉えてらっしゃるのかというところと、あとは働いている方もいらっしゃるでしょうし、また、広く情報発信したときに、なかなか内容の詳細が届きにくいような配慮の必要な方というのも、外国人の方ですとか、いらっしゃるのかと思うのですが、そのあたりはどのような想定をされていて、どういった形で周知を行っていく予定でしょうか。","respondent":"古巻防災課長","answer":"配慮が必要な方につきましても、先ほどのお答えの中でも申し上げましたけれども、名簿等を含めて、具体的に把握をいたしまして、しっかり届くようにということで、今、具体的なところについては現在内部で検討を進めているところですので。","id":"exchange-023"},{"speaker":"あくつ委員","kind":"質問","question":"私からは２点ですけれども、まず１点目なのですが、こういった避難基準ができることはいいことだと思うのですけれども、カラー刷りの下のところで、注意水位Ｔ.Ｐ.＋１.２０、警戒水位がＴ.Ｐ.＋１.５０、３０センチ刻みということでいいのですかね。それで、護岸の最低天端ですかね、この一番上、これを超えてしまうと、いわゆる溢水と言うか、氾濫ということでいいのかということ。","respondent":"持田河川下水道課長","answer":"避難指示と７センチという部分ですが、こちらのほうとしては、やはり避難勧告の段階でできれば避難を開始していただきたいというのが区としての思いでございまして、避難指示になりましたら、確かにもうあと数センチですので、この段階では。","id":"exchange-024"},{"speaker":"あくつ委員","kind":"質問","question":"わかりました。この週末、秋の地区防災訓練が各地であって、私も防災ラジオを平成２４年に買って置いてあるのですが、かなり優秀で、各地の防災訓練の朝のお知らせが全部入るようになっている。それと、交換と言うか対応の時期というのはどのようにお考えになっているのか、非常に大事なことだと思いますので、お伺いしたいと思います。","respondent":"古巻防災課長","answer":"ですから、それまでに、今現在の防災ラジオの代替手段を検討しなければいけないということですけれども、具体的にはまだ、来年度中ぐらいには、どういった形で代替手段がとれるのかということを、ＦＭの放送も始まりますし、そういったことで。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問・要望","question":"最後にしますけれども、これは、確か平成２４年に導入されたときに、各地の自主防災組織であるとか、各種団体などにも配布をされ、あとは高齢者等については助成をして、少し補助を付けられていて、私は実費で８,０００円出して買いましたけれども、これはある程度お金をかけて皆さん買っていますので、それについてはやはり、代替手段についても、その点も含めてお考えいただきたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-05","title":"平成３０年度区内一斉防災訓練の実施","agenda":"平成３０年度区内一斉防災訓練の実施","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それと、避難所訓練と言いますけれども、実際に参加しますと、町会ごとに教室が割り振られていますので、その教室を確認するというような内容になっておりましたけれども、よく災害時に見受けられる光景は、体育館に避難しているという光景がよく見られるわけですが、体育館の避難所の開設というのはどのような位置づけになっているのでしょうか。伺います。","respondent":"冨澤災害対策担当課長","answer":"各避難所におおむね１０名前後の職員が参集をいたしまして、避難所の防災区民組織の皆様と一緒に設営・運営を行うものです。各避難所に参集した区職員の動きですが、それは各避難所によってさまざまあります。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"例えば、段ボールベッドや、間仕切りなどを実際にセットしてみるとか、あるいはスマホを、今回の北海道胆振東部地震でも現地の動きは大変でしたけれども、スマホが充電できる設備環境をチェックしてみるとか、あるいは職員の方が１０名程度配置されるということでしたけれども、職員と地域の方が組んだ要支援者の避難訓練ですとか、そういった内容を追加できないかという思いがあるのですけれども。","respondent":"冨澤災害対策担当課長","answer":"毎年の訓練、繰り返しですけれども、さまざまなご提案を差し上げて、ぜひとも訓練内容を充実したものにしていけるように、今後とも検討してまいりたいと思います。","id":"exchange-028"},{"speaker":"あくつ委員","kind":"確認","question":"内容について確認をさせてください。私も毎年出ていますけれども、ここについて確認をさせてください。","respondent":"冨澤災害対策担当課長","answer":"今回、区民の皆様がやっていただく訓練の中には、いろいろこういった学校や、医療救護所になりますけれども、それと連携した訓練については今回は想定はしておりません。合わせて医療関係者のご参加につきましても、基本的には、今の段階では参加の話は聞いてございません。","id":"exchange-029"},{"speaker":"あくつ委員","kind":"提案","question":"本当に年末の大変な時期に、皆さん、町会の役員の方が、あとは自主防災組織の委員の方が集まっているのですけれども、ここで、先ほどほかの委員からもあったのですけれども、やはり段ボールベッドの設営、せっかく協定を結んだにもかかわらず、こういったことをやはり、それは避難所連絡会議の中で決めることだということであったのですけれども、ご提案はするというお話があったのですが。","respondent":"冨澤災害対策担当課長","answer":"今、委員からご指摘がありました新しいメニューの提示ですけれども、今後、区としてもいろいろなメニューを考えながら、各避難所連絡会の中でご提示をしてまいりたいと考えております。","id":"exchange-030"},{"speaker":"大沢委員","kind":"質問","question":"都の防災アドバイザー派遣事業については、今回も派遣が予定されているのでしょうか。今年度についてはこれはどうなっているのか、都と区の、逆に言えば都の広域防災体制の中で、非常に重要な事業だと思いますけれども、本区の現状、都のほうの防災計画を反映するためにも、重要な事業だと思いますけれども、今年はどのような形、派遣事業があるのか、今年は行われないのか、そこのところをお聞かせください。","respondent":"冨澤災害対策担当課長","answer":"以前ございましたが、今年度につきましては、その予定はございません。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"先ほど、ほかの委員の方からもお話が出ましたけれども、品川区と協定を結びました段ボールを利用した間仕切りシステムの設置などの運営をやっていただけるボランタリー・アーキテクツ・ネットワークさん、通称ＶＡＮさんなのですけれども、これは実際に品川区で最後に防災訓練が行われたのが今年３月４日のスクエア荏原なのですけれども、今回、わかる範囲で。","respondent":"冨澤災害対策担当課長","answer":"これから１１月末ぐらいに私どものほうに情報が入ってくる予定ですので、現在の中では状況が、この訓練をやるのかどうかもはっきりしていない状況です。","id":"exchange-032"},{"speaker":"筒井委員","kind":"提案","question":"もちろん、各避難所の避難所連絡会のお考えであるとか、ボランタリー・アーキテクツ・ネットワークさんの人手の問題などもありますけれども、ぜひ積極的に、ほかの委員の方からもありましたけれども、区からもご提案を積極的にやっていただけたらと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"}]},{"id":"topic-06","title":"所管事務調査を一括して議題に供します。 本日の所管事務調査は、水辺の利活用","agenda":"所管事務調査を一括して議題に供します。 本日の所管事務調査は、水辺の利活用","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"報告事項(6)も舟運社会実験ということで、要はライトアップですが、これは費用的には幾らぐらいかかるのか、みんなのイルミネーションというものと、今回の目黒川ライトアップというものがあると思うのですけれども、それぞれについて、費用が幾らなのか伺いたいと思います。この事業の目的について、改めてもう少しお聞かせください。","respondent":"持田河川下水道課長、稲田都市開発課長","answer":"目黒川のライトアップにつきましては、金額は主に１,０００万円ぐらいという形でのライトアップ事業という予定です。こちらにつきましては、常設のライトアップを今後やっていく中での１つの社会実験という位置づけで考えております。目黒川の桜のほうなのですけれども、実行委員会がございまして、そちらのほうに大崎エリアマネージメントが事務局の１つというところでやっておりまして、食用の油、廃油を集めて使う発電機を借りるお金など。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、所管事務調査のほうで、いろいろ規制緩和や河川敷地占用許可準則などのお話もありましたけれども、この運河ルネサンスとして指定され、規制が緩和されているという話がありましたけれども、これは若干、説明があったのですが、船着き場が設置できるというふうになるということですが、どこの制度を利用した規制緩和なのか、どういった内容なのか、もう少し伺わせていただきたいのと、今後。","respondent":"持田河川下水道課長、稲田都市開発課長","answer":"規制緩和の部分につきまして、運河ルネサンスというのは何かということですが、これは基本的には東京都のほうの、水辺のにぎわいをつくるための取り組みということで、地域の皆様での。先ほどの目黒川の桜のイルミネーションの件なのですけれども、地元の実行委員会がやるものに対しての補助金が４００万円ということでしたけれども、あと、区の観光課のほうでやっている、同じエリア内なのですけれども。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"ただ、やはり、親しむという上では、目黒川などはやはり水質が改善されるということが本当に重要なのではないかと思っていますが、ここに(7)で書いていますけれども、都へは引き続き合流改善施設の整備ということで要望していくということなのですけれども、合流改善施設の改善の見通しはどのような感じなのか。","respondent":"持田河川下水道課長","answer":"もっと必要だということを、やはり東京都のほうに伝えまして、何とか事業化する中で、目黒川エリアを優先できないかというところも含めて、そのような要望をしていきたいと考えています。","id":"exchange-036"},{"speaker":"あくつ委員","kind":"確認","question":"私も、会議に何回か出ましたけれども、当然、オブザーバーで品川区役所の方もいらっしゃいましたが、そこのところのスタンスをお伺いしたいのと、もう１つ、河川の部分で、ここに私どももこの前視察で、名古屋の堀川の取り組みについて視察をさせていただきましたが、やはり河川、名古屋市は政令市ということで、河川管理者も兼ねているということで。","respondent":"持田河川下水道課長","answer":"今後ということでいきますと、またそういった観光のほうで、しながわ観光プランという中で、水辺の部会というのを開いているというのを聞いておりますので、そういったところを、我々所管のほうもその水辺の部会の動きというのはいろいろ情報をいただきながら。","id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これはうまく行く、行かないがあると思うのですけれども、そういった中で、本当にせっかく連携している取り組みが、こういったことがうまくいかない、これはやはり、民間同士のやりとりというよりは、どちらかというと役所同士のやりとりがあったほうがよかったのかななどと思ったものですから、ぜひ今後、やはり水辺というものを大きく育てていただきたい、こういう思いで今日は質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"横山委員","kind":"確認","question":"水辺の利活用について、今までさまざまな、イベントですとか、社会実験ですとか、やっていただいているかと思っていまして、細かい部分も含めて確認の意味も込めて、この間、行政視察で名古屋市の堀川に行ってきたときに少し感じたのですけれども、江戸時代などにはメーンの生活空間として水辺というのは人々に受け入れられていて、とても生活に身近な存在だったという話もお聞きしてまいりました。","respondent":"持田河川下水道課長","answer":"水辺がないエリアというところでいくと、これはなかなか難しいところではありますが、やはり、品川区はエリアとしてそれほど大きくないところもありますので、やはり水辺のにぎわいをつくっていきながら、そういった中で。","id":"exchange-039"},{"speaker":"筒井委員","kind":"質問","question":"今回の、舟運社会実験の目黒川ライトアップについてお聞きしますけれども、これはもう少し、東品川海上公園あたりまで伸ばせなかったのかということと、また、これは民間の事業者、昼間に舟で通られていると思うのですけれども、ライトアップにあわせて夜間に舟を出すということを考えなかったのでしょうかということ。２点お伺いします。","respondent":"持田河川下水道課長","answer":"舟運の件ですが、夜間のクルーズというのは、これはいわゆる舟運事業者が企画するクルーズですが、それにつきましては、昨年度も夜間のクルーズというのが発着されておりまして、今年度も少し聞くところによりますと、この１１月。","id":"exchange-040"},{"speaker":"筒井委員","kind":"質問・要望","question":"今現在、品川埠頭橋の辺り、東品川清掃事務所の前の桟橋の近くに待合所があると思うのですけれども、あれは行くたびに大体閉まっておりまして、ぽつんと寂しく置いてあるという状況なのですけれども、あれはせっかく待合所を置いたわけですから、何かに活用できないのかなと思っているのですけれども、あの待合所の活用方法というのはどのようにお考えなのかということと、また、親水。","respondent":"持田河川下水道課長","answer":"現段階では防災桟橋という位置付の中で、そういった使い方が難しいところもありますが、それについては今後、五反田の桟橋ができたりとか、桟橋の改修等をやる中で、そういった使われ方、またはそういった使い方の利用例などにつきましても。","id":"exchange-041"},{"speaker":"筒井委員","kind":"質問","question":"水上タクシーなどはどのようになりますでしょうか。","respondent":"持田河川下水道課長","answer":"水上タクシーも含めて、今、区のほうでの社会実験という中では、既存の区内事業者を中心にやっておりまして、水上タクシーというのは今はつけられない状況でございまして、こちらにつきましても、桟橋の利用という中で、そういった非動力の関連のものですとか。","id":"exchange-042"},{"speaker":"筒井委員","kind":"質問・要望","question":"わかりました。積極的にそういった新しい取り組みというのを行っていっていただきたいと考えております。ぜひやっていただきたいのですけれども、今の区のお考えはいかがでしょうか。","respondent":"持田河川下水道課長","answer":"今、目黒区のほうで水質改善のいろいろ実験をやっていると聞いておりまして、品川区のほうも検討会に参加していますが、なかなかたちどころによくなるというのは難しいというところについては、やはりそういった施設をつくっていくですとか、浚渫するとか。","id":"exchange-043"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"１点だけ確認をさせてください。それについて、これは深夜、夜間であってもしっかりと対応していただけるのか、確認させてください。","respondent":"古巻防災課長","answer":"ただ、現時点で、何かそういった物件を確保しているかということはございませんが、避難所ですとか、そういったものの開設を含めて、避難所等につきましてもいろいろな対応ということが必要になってくるということも内部では検討を進めているところですので。","id":"exchange-044"},{"speaker":"あくつ委員","kind":"確認","question":"もう１回確認させてください。その場合に、もし何か支障を来した場合には、今、そもそも確保していないというお話があったのですけれども、それは提供していただけるのか、いただけないのか、そこについて、私もこれからそういうことをご案内する上で、必要なことなので確認をさせてください。","respondent":"古巻防災課長","answer":"現状、例えば今すぐ被害があった場合に、なかなか対応というのは難しい面もありますけれども、ただ、実際にお困りになっている方がいらっしゃるという状況においては、何らか退避できるような場所については考えて、ご提供、情報提供させていただきたいと思いますので。","id":"exchange-045"},{"speaker":"あくつ委員","kind":"意見","question":"わかりました。情報提供と言うか、何らかの形で、区民の方がお困りになっているときには、検討と、先ほどお話もあったのですけれども、今後については、言い方は申しわけないですけれども、品川区は責任を持って、区民の方の住居と言うか、避難場所の確保はお願いをしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"横山委員","kind":"質問","question":"今回、この台風第２４号の対応についてのご報告なのですけれども、やはり今年は災害ですとか、天候的に火事も多くなっているかと思うのですが、災害が増えることによって、人的被害、浸水被害、物的被害と出ていますけれども、それ以外に何かほかの影響というのは、少し見えにくい部分も含めてなのですけれども、出ていたりするのでしょうか。","respondent":"古巻防災課長","answer":"そういったところに関しましては、的確な情報提供をするところも含めて、どういった準備を進めればいいのか、またそういったときに、どういった行動をとればいいのかということも含めて、いろいろそのあたりも、情報と言うか、広報のあり方と言うか、考え方と言うか。","id":"exchange-047"},{"speaker":"横山委員","kind":"質問・要望","question":"これから、また年末、また春にかけてもそういうことが起こる可能性もありますので、今年は重なっているということもありまして、そのあたりのご配慮をいただけたらと思いますので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"被害状況というところで報告があるのですけれども、被害のところで７２件、８件という数字があるのですが、こういった被害件数の把握の仕方というのはどのようになっているのか、お伺いしたいと思います。どのようなものがどう把握をされてこういう数字になっていくのか教えてください。それと、個人の住宅の被害、そういったものはどう把握するのでしょうか。そこについてもお願いします。","respondent":"古巻防災課長","answer":"民間の住宅の被害の把握ですけれども、これは１００％は難しく、軽微なものについては特に区へ報告するなり、そういったことはなく、ご自宅を片づけるという程度で済ませてしまうお宅もあろうかと思いますので、１００％は難しいかと思いますけれども。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問","question":"１００％は難しいということなのですけれども、今回、一定程度は民間の住宅のこういった物的被害というのも、件数としては把握しているということでよろしいのでしょうか。","respondent":"古巻防災課長","answer":"樹木に関してもそうですけれども、実際に区のほうで対応した件数というふうにご理解いただければと思います。","id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/602656?Template=document&Id=4248#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":59100,"voices":165}},{"id":"h30-20181030-9","meetingId":"h30-cm10","date":"2018年10月30日","dateIso":"2018-10-30","committee":"文教委員会","time":"午前１０時００分～午後 ３時１８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を75件抜き出しています。","topics":[{"id":"topic-01","title":"平成３０年度移動教室実施結果","agenda":"平成３０年度移動教室実施結果","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"事故もなく終了したということで大変よかったと思うのですが、１つ、ざっくりでいいのですが、小学校と中学校の移動教室の中身を教えてほしいのと、参加できなかった児童・生徒の方がどのぐらいいるのかと、その理由がわかったら教えていただきたいと思います。","respondent":"篠田学務課長","answer":"中学校ですけれども、こちらは磐梯高原ということで、主な体験としては、猪苗代ですとか会津藩校、野口英世記念館等の見学ですとか、あるいは登山、ハイキングということで、雄国山等のハイキング等を実施しています。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"参加できなかった児童・生徒の方への後のフォローなど、何か具体的にされていることがあったら教えてください。","respondent":"篠田学務課長","answer":"例えば、お子様同士で現地の思い出、状況を話し合ったり、場合によってはお土産などを買われていったりされる方もいらっしゃるとはお聞きしています。教師も寂しい思いをしないような形でフォローしていると聞いております。","id":"exchange-002"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"２点お伺いします。１点目が、参加されているお子様の中で、いわゆる財政的な支援を受けている生徒はどのぐらいいるのか、わかる範囲で教えていただきたいです。それと、もう一点は携帯電話なのですが、移動教室等で外に行かれる際に、携帯電話の取り扱いはどのようになっているのか教えてください。","respondent":"篠田学務課長、大関教育総合支援センター長","answer":"財政的支援のほうをお答えいたします。携帯電話等、連絡手段につきましては、基本的にトランシーバー等の貸し出しと、それから必要に応じて、貸し出しのＰＨＳ・携帯等は対応しますが、ただ、管理職が持っておりますので。","id":"exchange-003"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"特別支援学級の実施についてお尋ねしたいのですけれども、教員の数はここに出ているのですけども、それ以外に、付き添いといいますか、一緒に行かれた方というのは、どのような立場の方がどんな基準で一緒に行かれるのか、もし行っていないなら、教員だけということで。小学校、中学校ともに教えていただきたいのが１つ。","respondent":"大関教育総合支援センター長","answer":"教員以外の支援者ですが、日常、普段学校にＮＰＯから支援が入っており、基本的には同じ方になるのが一番望ましいというふうに教育総合支援センターで支援しておりますので、実際に移動教室の方にも行っていただいております。","id":"exchange-004"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"マイスクールのほうは、宿泊体験も彼らができるということで、非常にいいことだと思います。こちらも続けていただきたいのですが、またその一方で、事故などないように十分注意していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"つる委員","kind":"確認","question":"別紙２にもあるので確認ですが、移動は、バスでするということでよろしいのでしょうか。","respondent":"篠田学務課長","answer":"移動教室の移動は全てバスを使ってあります。","id":"exchange-006"},{"speaker":"つる委員","kind":"質問・要望","question":"移動教室なので、移動教室自体の時期というのは、さほど直接的な影響はないとは理解するのですが、ただ、林間学園については、まさに時期が重なるということで、そういう要請があるという中で、報道では情報収集という表現でしたが、まさに２年後ですけれども、どういう手だてが考えられるのかという現状のところを教えていただきたいのと、移動教室そのものは影響がないという確認と。","respondent":"篠田学務課長","answer":"そうしますと、学年で言いますと二千四、五百人の方が全体でおりまして、実際にこの時期に実施するのが、冬に林間学園のかわりにスキー教室を行っている学校もありますので、全部の学校ではありませんけれども、大体二千二、三百人のお子さんに影響が出るという中で。","id":"exchange-007"},{"speaker":"つる委員","kind":"質問・要望","question":"今、現段階でのというところもあると思いますが、これだけ大きい規模だと、予約といったものも、かなり早い段階で調整しなくてはいけないというのがあるのでしょうから、今ご答弁の中でもあったとおり、品川区も、競技開催都市というのがある中で、子どもたちにとって、オリンピックに触れる機会、それから林間学園という、いろんな日常とは違う学びの場というのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"南委員","kind":"質問","question":"それで、この表にあるところの限りでは、いろんな媒体を使って周知をするということなのですが、一番肝心なのは、平成３２年度に１年生になる方、７年生になる方の保護者あるいは子どもにきちんと変更した状況を理解していただいた上でということで、選択制にせずに、自分の学区域のところに行きたいという方は別としても、学区域が変わるわけですから。","respondent":"若生学校制度担当課長","answer":"こちらは、かなりわかりやすいものを作成する予定で考えてございまして、こちらをまず、就学前の通われている保育園や幼稚園、児童センター、あるいは健診の場や、いろいろな区の施設を利用される、小さい子が行かれるようなところに幅広く置かせていただいて、なおかつ、個々に。","id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"同時に、直接的に説明する立場にないとは思いますけれども、非常にかかわるところとしてＰＴＡがあると思うのです。そういうときに、電話での相談だけではなく相談ブースのようなものを設けるなども含め、きちんと不安を払拭して入学していただくということが一番大事ですので、そういうこともどういうふうに捉えているか、その辺も伺いたいと思います。","respondent":"若生学校制度担当課長","answer":"区への問い合わせへの対応等についてですが、ブース等も設けてというご提案がありましたが、そういったことも含めまして、きちんとこれは対応できるような対処をとってまいりたいと考えています。","id":"exchange-010"},{"speaker":"南委員","kind":"意見","question":"かなりの労力を費やして学事制度審議会を１年間やり、そしてその答申をいただいて、１年間の時間を要しながら実施に移していくということなのですけれども、学校選択制はかなりのところで、２３区の中でも廃止している状況がある中で、こういうふうにしていくという、かなりの労力を費やさざるを得ないということについての、やはり矛盾というか問題というか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私もこれは２日かけて見たのですが、本当に、個別の事例で比較して見ていかないと、なかなかわからないです。やはり地元の方の意見をしっかり聞いて、これから町会に聞いてというのももちろんですけれども、地元の声を聞いていくという、そこのところの重要性をしっかり捉えていただきたいと思うのですけれども、具体的にどんな説明をして意見を聞かれているのでしょうか。","respondent":"若生学校制度担当課長","answer":"２点目の、地元の意見等、ご説明の仕方につきましては、今後、来月以降、町会・自治会等、ＰＴＡも含めまして、これは、例えば町会・自治会関係につきましては、もう連合町会は満遍なく変わるものですので、ここはやって、ここはやらないというわけにはいきませんので。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはりわからない、いろいろ質問が出たから来てほしいと言われたら、ぜひ出向いていって説明もしていただきたいと思います。もっとシンプルな状況の中で安心して地域に暮らせるというところがやはり大事で、検討した結果、評価的にはさらに難しくなっているのではないでしょうか。今からでも遅くないので、見直せるのだったらぜひ見直していただきたいという意見を述べて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"なので、例えば別紙３にあるような、例えば品川・大崎ブロックとか、見るのは各ブロックぐらいなのかと。いわゆるピンポイントで。これは要望で終わります。いわゆるコミュニティ・スクールというもの、また地域というもの、学校というもの、この辺をどうやって今後、見直しをした後にクリアにしていくか、活動しやすいようにしていくか、何かお考えがあればお聞かせください。以上、質問は３点です。","respondent":"篠田学務課長、若生学校制度担当課長","answer":"私からは、いわゆる学年の途中の学校選択の考え方についてご説明します。荏原地区と大崎地区との関係で、ちょっと分かれてしまっているところに関しての考え方ですが、第四日野小学校に関しましては、上の図を見ていただくと、現行も荏原第一中学校との連携が行われておりまして、お子様の進学につきましても。","id":"exchange-014"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"年度途中ですが、最初のご答弁を聞いて、そうなのです。そうなのですけれども、現実はそうではなくて、途中で学校を変えたいという人は、その理論でいいかもしれないけれど、引っ越しをされたお子さんというのは、月が違うだけで、初めてそこに入学するのですから、入学の選択権というのはここに与えられるべきであって、それを、年度途中だからといってだめだというのはどうなのでしょうか。","respondent":"篠田学務課長","answer":"指定校変更で今、対応しているということで、実際になかなか条件が厳しいというのは、確かにご指摘のとおりです。さまざま課題等あることは私どもも認識しておりますし、今後どういった形で対応できるのかというのは研究していく必要はあるのかなとは考えているところです。","id":"exchange-015"},{"speaker":"渡部委員","kind":"質問","question":"ただ、今、これは新たな大きな制度変更を、品川区の長期基本計画が始まる、そして、日本の国の中で教育要領が変わっていくという、このタイミングで、平成３２年というすばらしいタイミングでできるのですから、そこも研究材料で間に合うのであれば、年度途中、学校選択にしていいのではないかと思います。その中で学校をお選びくださいでもいいのかなと。そこだけ「検討します」と言ってほしいのですが。","respondent":"篠田学務課長","answer":"それで、今回の見直しに当たってすぐにこれを打開できるかどうかはなかなか難しい部分もあるかと思うのですけれども、今後、こういった部分がどういった形で対応できるのかどうかということも含めて研究していく必要はあるかと思います。","id":"exchange-016"},{"speaker":"渡部委員","kind":"質問・要望","question":"そこは丁寧に、まずご説明いただきたいと思います。それで、問い合わせに関しても、ブースだ何だというのですが、なるべく問い合わせが出ないような仕組みでお伝えできるようにしてほしいと思います。例えば、私たちはこういう仕事をやっていて、こういう議論をしているので、隣接校と言われたら、地元の学校であれば、すぐわかるのですけども、普通の住んでいる人は、隣接校がどこかわからないですから。","respondent":"若生学校制度担当課長","answer":"スケジュールに関してのご質問ですが、まず周知に関しましては、当然、平成３２年度から実施していくには、その前の年度、平成３１年度の秋、１０月からの学校選択制の手続に間に合わせるように、１カ月先取していくということが必要になりますので。","id":"exchange-017"},{"speaker":"渡部委員","kind":"質問・要望","question":"選択行動がどうなる、こうなるというよりも、仕組みがあるということが、十何年続けてきて、それの、ある程度集大成で、これから１０年も２０年も多分この仕組みでいけるような仕組みなのだと思いますので、しっかり丁寧に周知を進めていただいて、平成３２年には新しい形で進めていただきたいと思います。ここにいる人たちも普通の議員もみんな、町場のことが来ますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"つる委員","kind":"質問・要望","question":"この経過措置は、多分、十分にいろいろ対応いただいているということで、他区ですけれども、「突然、選択制が中止になってしまって、本当に大変で」と、該当区ではないのですけれども、私のところに「どうしたらいいのでしょうか、何とかならないのですか」とその方が相談に来たというようなことがありました。まさに目の前のところが、２０２０年の４月入居です。","respondent":"若生学校制度担当課長","answer":"武蔵小山駅前の開発に伴って、学区域の小学校のほうの変更の対象となる、特にマンションを購入される予定の世帯の方、ご家族がいらっしゃってというところに関して、きちんとやはり周知する必要があると考えています。","id":"exchange-019"},{"speaker":"つる委員","kind":"質問・要望","question":"先ほど渡部委員から言っていただきましたとおり、飯沼委員も先ほど言っていましたけれど、本当におそらく問い合わせ、私もエリア的に相当数あるのだろうと想像すると、やはりそうした資料なども早目に頂戴できると、それはそれでありがたいです。本当に、まさにたまたま、これは２０２０年、平成３２年４月というところに、ちょうどぴったり来てしまっているので、そこだけはお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"さまざま、今、質問と答弁があったので、いろいろ理解させていただいたのですが、ちょっと確認で、１つは、今、原案という形で出てきているのですが、スケジュールの中で、「説明・調整」とあり、そして「新制度の決定」とあるのですけれども、決定というのは一体、どこでどうなると決定であり、それが、パンフレットは４月からといいますけれども、「決定した」というのは、もう一度。","respondent":"若生学校制度担当課長","answer":"学校選択等が変わることによって、中学校に関しても抽選等の可能性が出てくるというようなことは、もちろん、そういったことも必ず、制度としてやはり抽選というのは現状もあるものですので、そういったことはきちんと周知できるような形で、資料。","id":"exchange-021"},{"speaker":"高橋（し）委員","kind":"質問","question":"ですから、決定というのは施策等の決定で決定ということなのですけど、それは教育委員会として決めると。それで、それが来年度になってから要綱に変えられていくという流れになっていくという説明だと、今、思ったのですが、何といいますか、決定したということ、これは今日をもって決定ではないわけですよね。ですから、そこのところがちょっとわからないのですみません。","respondent":"若生学校制度担当課長","answer":"決定するというのは、教育委員会として決定していくということで、教育委員会の審議の中で、今年度中に制度を決定するといった手続きをとるです。","id":"exchange-022"},{"speaker":"高橋（し）委員","kind":"意見","question":"ということは、教育委員会の中の会議で、来年度の学事制度はこうしますということを教育委員会で決定して、そこで決定という理解でよろしいですね。それが今年度中ということで。それで、決定はしていないけども、説明とか、そういうのはしていくということですよね。","respondent":"篠田学務課長","answer":"要は、教育委員会の権能として学区域の設定等がありますので、そちらは最終的に、今回、原案を出させていただいて、地域に対してご説明をする。","id":"exchange-023"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうなのです。今お話があったように、そこの調整のところで、また変わってくる可能性があるという話でした。そういう時にそれはもう一度、こちらに出てくるのでしょうかということなのです。もう一度、委員会で言っていただいて、今回、原案はこうでしたけれども、ここを少し変えて、教育委員会で決めていきますというお話をしていただけるのかというところをお伺いしたいです。","respondent":"篠田学務課長","answer":"基本的には、権能としては教育委員会の権能ですけれども、当然、文教委員会のこの場においても、いろいろ、もし変わるようなことがあれば、最終的にはご報告をさせていただいた上で、教育委員会で決めていくという段取りになろうかと思います。","id":"exchange-024"}]},{"id":"topic-02","title":"平成３０年特別区および東京都人事委員会勧告の概要","agenda":"平成３０年特別区および東京都人事委員会勧告の概要","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"こんなに大幅に額が下がるというのは、なかなか今までにない、額的には初めての金額ではないかと思っているのですけれど、公務員の皆さんに限らず、下がること自体、非常に影響が大きいのではないかと思うのですけども、業務委託、あるいはいろんな意味で仕事を委託している方々、非常勤採用の方々等々についても、公務員本人以外に影響がどのぐらいまで広がるのかというところを伺いたいです。","respondent":"熊谷指導課長","answer":"月例給の公民較差、今回、下がった要因なのですけれども、人事委員会によると、平成３０年４月より実施した行政系人事・給与制度の見直しに伴う改正に伴って、職員構成に変化があったことによる影響と聞いております。それから、公務員以外というのは非常勤等でしょうか。","id":"exchange-025"},{"speaker":"南委員","kind":"確認","question":"とりわけ年末に向かう時期、消費拡大が見込まれるときに、そういう状況になってきているということと、来年は消費税が１０％に増税されるという点で、本当にかなり深刻ではないかと私は思うのですけれど、そういう心配についてはどういうふうに受けとめているのか伺います。","respondent":"熊谷指導課長","answer":"それから２番目なのですけれども、勧告内容としまして月例給について大幅な引き下げ幅となっていますので、非常に厳しい内容と受けとめているのですけれども、ただ、公務員の労働基本権の代償措置として社会一般の情勢に適応できるよう確保するものとして。","id":"exchange-026"},{"speaker":"南委員","kind":"意見","question":"報告ということであっても、かなりひどいのではないかと思っていることはお伝えしておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"渡部委員","kind":"質問","question":"意見だけ述べます。だから、今日は文教委員会ですから、総務委員会でどういう議論があるかわからないのですけれども、多分、私たち、これのみというわけではなくて、当然、そうなるのはやむを得ない部分で、労使が妥結してしまえばそれまでなのでしょうけれども、それが、さっき言ったように、１２月の賞与で一括、がつんとされたら、大変な人は大変だと思います。意見だけ言っておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-03","title":"平成２９年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"平成２９年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"図書館のところなのですけれども、職員の状況を知りたいのですが、職員数と職種と、あと正規・非正規の人数、司書がどのぐらいいるのか、３つのグループでいいのか。所管ごとに違うのか、どういう聞き方がいいかわかりませんが数字的なものを教えてください。本来であればここに載せていただきたいと毎回言っているのですけれど、聞かないとわからない中身なので教えてください。","respondent":"横山品川図書館長","answer":"職員数ですが、品川図書館の職員数は３０名だけです。の図書館につきましては指定管理で、全て委託の形になっているため人数は分かりません。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"委託の部分は、ではわかったら数字で教えてくださるということで、ぜひ司書の方がどの程度なのかという中身もわかるのでしょうか。","respondent":"横山品川図書館長","answer":"指定管理の条件としまして、半数程度以上、確保してほしいという要望を出しております。それに対応しまして、指定管理の提案で、５割、６割という提案をいただいておりますので、今現在もそれ以上を確保しています。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"図書館法とか、あと民間のところ、図書館協会などでも、とにかく司書を中核とした運営が大事であると求められているので、その辺はやはり大事にしていただきたい、確保していただきたいと思います。多分、品川区はずっとないと思うので、ぜひこの設置を求めたいのですが、いかがでしょうか。","respondent":"横山品川図書館長","answer":"地域とのかかわりにおいて、この間、いろいろな地域に赴いてお話しする中で、各地区の図書館長が中に入っていろいろなことをすることで、地域の方とのかかわりも持っている状態なので、委員会という形が適切なのかどうかは引き続き検討していきたいと考えています。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問・要望","question":"家庭あんしんセンターのところなのですが、中央のところに育児支援ヘルパーが平成２８年度から独自事業に変更となっているのですが、この中身をひとつ教えていただきたいです。裏面の苦情解決第三者委員会、平成２９年度は苦情の申し入れはなかったということなのですが、これは、どういう構成で委員会が設置されているのか、中身を教えてください。やはりここの施設の特有なところが含まれているのですかね。","respondent":"高山子ども育成課長、廣田子ども家庭支援課長、吉田保育施設調整担当課長","answer":"こちらにつきましては、従前、養育支援訪問事業と育児支援ヘルパー事業を一体的に運営していたところですが、平成２８年度より。家庭あんしんセンターの苦情解決第三者委員会なのですけれども、こちらにつきましては、家庭あんしんセンター独自というよりも。ぷりすくーる西五反田の認定こども園化の方向性がいつぐらいかということなのですけれど、これは今、検討している最中でございまして、まだはっきり。","id":"exchange-032"},{"speaker":"南委員","kind":"質問","question":"図書館というのは、改めて私たち住民が読書したいという、読書する権利というか、あえて権利と使いたいのですけれども、あるいはいろいろな調査をしたりして、状況を知りたいという学習権とか、そういうことを保障する施設、機関ではないかと思っているのですが、まずそういう認識でいいのかどうかということを、１つ伺いたいと思います。","respondent":"横山品川図書館長","answer":"図書館の幾つかの機能の中で重要な一つだと思っています。","id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点で、先ほど飯沼委員の質疑の中で、利用者協議会というのですか、その問題については、土地柄必要なのかどうかということも含めて研究したいとおっしゃったのですけれども、私は、法律との関係で言うと、設置を求めている。だから、この間、少なくとも２年にわたって、そういう指摘がされてきている中で、どういうふうに改善しているのかという認識を持っているのか伺いたいと思います。","respondent":"横山品川図書館長","answer":"委員ご指摘のとおり、利用者協議会については図書館法で一応、望ましいという形で表記されておりますので、品川区においても引き続き検討は進めします。","id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"これだけのモニタリングをやって、同じような状況が出るということはいかがなものかと思いますので、やはり指定管理というのはやめて、経験豊かな職員による地域住民との、いろんな本に対するカンファレンスとか、そういうことも対応できるような、そういう中身で事業を運営していくべきだということを、つけ加えておきたいと思いますし、判断に手間取るというところについては。","respondent":"横山品川図書館長","answer":"それと、今、蔵書管理について引き続き何度も指摘がされている点につきましても、先ほどもご説明しましたように、事業者と職員と協働しまして、一つひとつ、どんなやり方が適しているかというのを進めながら、また、本そのものについても、これから電子化が進む中で。","id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"大変、残念だと思います。そういうことを指摘して、少なくとも短期間の間に、改善を求める点についてはきちんとレベルアップしていけるようにしていただき、指定管理にこだわらずに、やはり住民サービスというところをとって、指定管理という制度を導入したということについてもきちんと検証するべきだということを言って終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"石田（し）委員","kind":"質問","question":"図書館ですけれども、これは利用者数が減っている中で、このシートには、その点に関して何も記載がない。業務改善に関しては、いろいろ防災訓練に参加したり、地域に根づいた活動をしたりと、利用者サービスが向上しているように理解はするのですが、利用者数について各指定管理者たちはどのように捉えているのか、把握していたら教えてください。","respondent":"横山品川図書館長","answer":"これは、全体の状況なのか、図書館だけの状況なのか、はっきり数値では確認できませんが、おそらくはＣＤから別の媒体へ移っているということのあらわれではないかと考えています。取り次ぎにつきましては、昨年から１万６,６８３冊の増加が見られます。","id":"exchange-037"},{"speaker":"石田（し）委員","kind":"質問","question":"いろいろ時代が変わって、区民の方たちのいわゆるニーズも変わってきているというのを把握しているにもかかわらず、これまで何も電子図書に関して、このシートにも出てこないですし、図書館長のお話の中でも、研究をするというのにとどまっている。利用者のニーズをそこまで把握しているにもかかわらず、なぜ、いまだに検討段階にも入ってこないのか教えてください。","respondent":"横山品川図書館長","answer":"ほとんど著作権フリーになったものなので、新しいものを求める電子書籍の主たる需要者に対して対応していない状況があるのと、電子書籍の利用が所有権ではなくて、２年間もしくは５２回貸し出しで権利が消えるという貸し出しの方式になりますので、図書館としては。","id":"exchange-038"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。違ったら違うと言っていただきたいのですが、それにもかかわらず、こちらも来館者数等々は減っているように、このシートでは見えるのですが、この辺の要因というのが何なのか、このシートを見る限りだとわからないので、担当課として把握されていたら教えてください。","respondent":"廣田子ども家庭支援課長","answer":"入所者については、全体で定員２０世帯のところで、現状、９世帯２１人なのですけれども、２年で自立させていくという目標を立てているので、もちろん短い方も長い方もいらっしゃいますけれども、順調に出て回転しているというところです。","id":"exchange-039"},{"speaker":"石田（し）委員","kind":"質問","question":"このシートだと、運営の委託料というのが、若干ですが減っています。私のイメージだと、それこそ母子家庭の支援というのは、年々必要なものが多くなってきているという認識なのですけれども、運営費が減っている理由というのが、もしあるのであれば、そこだけ教えてください。","respondent":"廣田子ども家庭支援課長","answer":"運営費については、ひまわり荘等については２０定員で、今、暫定定員が１３定員にされてしまっているのですけれども、いつ入ってもいいように２０定員分、規定のとおりにお支払いをしているところです。","id":"exchange-040"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ぷりすくーる西五反田のほうでお尋ねしたいのですが、先ほど幼保連携型認定こども園についてはお話があったのですが、今年の１月の文教委員会で社会福祉法人化の準備ということでシートが配られて、それで、このままではそれができないので環境整備を検討するというお話だったのですが、具体的にどこをどう検討し、どこに問題があって社会福祉法人化できないのか。","respondent":"吉田保育施設調整担当課長","answer":"その辺のところを、どうやって今後解決していくかというところと、認定こども園化に当たっては、その運営母体として社会福祉法人という形になりますので、認定こども園化の時期に合わせた形での社会福祉法人化を今予定しており、１月２２日の文教委員会では。","id":"exchange-041"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、平成３２年に社会福祉法人化。ということは、もう今からさまざまな条件整備をして、１カ月で社会福祉法人化ができるというのではないと思うので、そういう意味では、現状の社会福祉法人化の準備はどういう感じなのかを伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"現在、社会福祉法人につきましては、新しい社会福祉法人ということで考えているところです。それと、社会福祉法人の申請の時期などにつきましては、今のところ、平成３１年度の中ほどで予定しています。","id":"exchange-042"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今度どこになるかというのは、プロポーザル等だと思うのですけれども、そうすると、社会福祉法人化し、そしてその後、認定こども園化していくという条件がプロポーザルの中にあり、子育て品川も含め、プロポーザルあるいは指定管理の選考をしていくのかと思うのですが、そのあたりの来年度以降の指定管理の話についてご説明をいただきたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"現行のぷりすくーる、これで１５年目になりますけれども、指定管理、第３期目は今年度で終わります。第４期目につきましては、選定委員会を新たに開きまして、その中で選んでいくという形を、予定しています。","id":"exchange-043"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ただ、仕事をされている方々が、この先どうなるのだろうといった面で、先が少し見えない中での不安をお持ちの方もいらっしゃるということもありますので、ぜひ、今お話があったように、新たな認定こども園化に向けて、先が見えるような形で区も支援して、バックアップしていただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これはグループに分かれているから載せにくいのかどうか、ぜひ委託の費用もわかったほうがいいので、今日は結構ですが、次回からぜひ、ここに載せていただきたいという要望が１点です。先ほど職員の人数をお伺いしたら、品川図書館は３０人ということでした。","respondent":"横山品川図書館長","answer":"品川図書館で司書資格を持っている人は、実質１人になります。人数については、調査時点の差だと思います。休職等で出入りが激しいものですから、申しわけないです。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問・要望","question":"司書については、今の課長の責任ではないのです。そういった点で、先ほどの指定管理のところには、半分以上ですか、司書を置いているということなのですが、やはり図書館というのは本当に教育的な場であり、専門職がとても大事という意味で、ぜひ司書の役割をきちんと位置づけた図書館運営をしていただきたい。ここはぜひ改善していただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木（博）副委員長","kind":"質問","question":"最初の指導課長から説明があった品川英語力向上推進プランのほうなのですが、ＡＬＴとＪＴＥと書いてあるのですが、これは何の略なのでしょうか。それと、あと二点。だから、食べなれていないものとか、何が入っているかわからないものに関しては、食物アレルギーに関して何が起こるかわからないという点も考慮されているのでしょうか。その２点をお伺いします。","respondent":"熊谷指導課長、篠田学務課長","answer":"実際に十二単の着つけ体験等も行っているのですけれども、着て終わりではなくて。それで、物によってアレルギーのものが当然ありますので、実際に現地で料理をつくるときの食材はどんなものが必要で。そして２点目のＪＴＥ、日本人英語専科指導員ですが、これはJapanese Teacher of Englishということで、その略です。","id":"exchange-047"},{"speaker":"鈴木（博）副委員長","kind":"質問・要望","question":"それと、あと食物アレルギーなのですけれど、食物アレルギーの研究をするのではなくて、外国で使う食材にどういうものが入っているかを調べてほしいのです。それで、除去する場合は、では除去してどうするのかとか、当然そういうことを考えなければいけません。ですから、その辺はしっかりと対応をよろしくお願いします。要望ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"南委員","kind":"質問","question":"グローバル人材のほうの背景の４点目に、「海外留学や海外赴任を敬遠するなどの、日本の若者の内向き志向」と書いてあって、これは本当に英語教育を、また国際社会化がどんどん進んでいく中で、こういう現象があるということは事実なのかなと思って、何が原因でこんなふうになっているのだろうと、すごく気になるところなので、どういうふうに捉えているか教えていただければと思います。","respondent":"熊谷指導課長","answer":"楽なところを選んでしまう。あえて、挑戦していこうというチャレンジ精神といったものが、なかなか育っていない若者が多いのではないかというところが１つの要因ではないかと思われます。","id":"exchange-049"},{"speaker":"南委員","kind":"質問","question":"なるほど。そういうところもあるのかと思ったのですけども、でも、わりと、小学校の時代からいろんなことにチャレンジしようという、意識的なそういう教育的指導はずっとしていると思うのです。果たしてそれがいいかどうか、適切、言い得ているかどうかは別としても、教育委員会としてはどういうふうに見ているのかを教えていただければと思います。","respondent":"熊谷指導課長","answer":"ただ、９年生になると自分の将来が見えてくるというところもあって、５割程度、４７.６％の子どもが、将来、外国に留学してみたいと答えていますので、時期もあるかと思うのですけれども、やはり怖がらずに自分の力を試していこうという。","id":"exchange-050"},{"speaker":"南委員","kind":"質問","question":"一人ひとりの、やはり子どもですから、当然、自分の力などというのは、自分で見定める能力など到底ないわけですけれども、やりたいという意欲だけは本当にいっぱい出てくると思うので、伸びていくというか、「あなたの存在自体が大事よ」ということも含めて、やはり一人ひとりの個の状況を認めながら、発展していけるような指導、やっていただいているとは思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ここに書かれている楽しむ英語という中身、一緒にゲームをするとか、カードで発音をみんなでやりとりするとかというところを見せていただいたのですが、内容を教えていただきたいのと、ＡＬＴやＪＴＥの先生はすごく担任の先生にとって頼りになるというか、力強い立場にいらっしゃると思うのですが、どうやって探していらっしゃるのか、どこから来ているのかというのを教えてください。","respondent":"熊谷指導課長","answer":"ＡＬＴと一緒の授業ということで、１・２年生の授業をご覧になったと思うのですけれども、ゲームをやったり、それから歌を歌ったりというところからスタートいたします。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問","question":"ＡＬＴのさまざまな人種ということで、私が伺ったときは東南アジアの方だったのです。ちょっと皮膚の色も日本人に近い方でした。そういった意図があって、いろいろな方を採用されているということなのですね。オリンピック・パラリンピックの教育やプログラミング教育は、どういう授業というか時間帯、市民科もかなり入っていますが、どういう時間を使ってこういうものを取り入れているのか教えてください。","respondent":"熊谷指導課長、大関教育総合支援センター長","answer":"そのためにやるというよりは、例えば市民科でこれまで行ってきた授業と関連づけて行ったり、また保健体育等もそうですけれども、品川区で言うと、品川区立学校教育要領に準じて、その内容と関連づけて行ってきております。先ほどもご紹介しましたように、理科の発表で使う場面もあれば、あるいは市民科の中でステップ５として、自分の取り組んだ内容を発表したり、友達の発表を聞いたり、そういった場面で使うような場合もあります。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問","question":"結構、プログラミングのところは、いろんな授業の展開があるのかと思うのと、今、学びの素材が本当にいろいろ多様化して、私たちの育った環境と違うので、やはりある意味では学校で誰もが触れられるというのはとても大事かと思いますけれども、苦手な子もいるのでしょうか。みんな、ついていけているのでしょうか。","respondent":"大関教育総合支援センター長","answer":"品川区の区立学校はＩＣＴ環境が早い段階から整ってきておりますので、多分、他区に比べても、比較的いろいろな場面で、教員も使いますし、子どもたちもグループで実際に触れるという場面はとても多いと感じているところです。","id":"exchange-054"},{"speaker":"つる委員","kind":"質問","question":"これはいわゆる日常の授業で実践されていることだと思うのですが、特に英語などについては、最初に、どういう目的観、これをやるのだという意味みたいなところを児童・生徒に伝えているのかとか、あとは、その取り組みの一番最初だけではなくて、都度都度、授業の中でどういうふうに教員の方が上手に工夫して伝えているのかというのを、まず教えてください。","respondent":"熊谷指導課長","answer":"１年生から７年生に関してなのですけれども、ＪＴＥも必ず今日の目的ということは最初に伝えるようにしているのですが、なかなか１・２年生のＡＬＴとの授業のときには、担任が伝えそびれてしまうということもありますので。","id":"exchange-055"},{"speaker":"つる委員","kind":"質問","question":"これは、決算特別委員会などで活用をどういうふうにしていくのかと伺おうと思ったら、もう既にやられているということで、これは一般利用もある中で、学校が積極的にというところだと思うのですが、非常にいい機会だと思いました。主だったもので結構なので、いわゆる品川区の伝統として児童・生徒が学んでいるものというのはどのようなものがあるのか教えてください。","respondent":"大関教育総合支援センター長","answer":"まさにさまざまな地域ごとに品川区ならではの文化と伝統があると考えまして、実際、本年度より各学校では、地域の方を招いて地域の文化と伝統について教えていただくなどというところも取り組みを始めたところです。","id":"exchange-056"},{"speaker":"つる委員","kind":"質問","question":"具体的な内容が欲しかったのですけれど、今のは多分、歴史みたいなイメージで私は理解したのですが、品川区の各地域でいわゆる伝統と言われているもの、どういったものを皆さんに伝えていただいているのかというのを教えてください。","respondent":"大関教育総合支援センター長、熊谷指導課長","answer":"歴史以外に、例えば地域の、もうそれこそ品川甚句や品川音頭といったものも１つの伝統だということで、連合体育大会で子どもたち全員で踊ったりというような取り組みもしております。は遊船であったり、釣りざおであったり、そういったこともオリンピック・パラリンピック教育の一環として、まず品川区を知るというところで掲載しています。","id":"exchange-057"},{"speaker":"つる委員","kind":"質問","question":"そういったところの大切さということも、地域に対する誇りなどということになっていくのかと思うので、またぜひ別の機会で品川区の伝統を、ちょっと具体的にいろいろ伺えればと思ったので、また改めてこれについてお聞きしたいと思います。人と人との中では出てこないということを、逆にどうつかませていくのかというきっかけにしていかなければいけないのかなと思うのです。","respondent":"大関教育総合支援センター長","answer":"あるいは逆に、それよりはコンピューターに頼らないほうがかえってねらいは達成しやすかった。そのような意見も踏まえて、それぞれの各校の取り組みを今後、情報共有して、取りまとめてまいりたいと考えております。","id":"exchange-058"},{"speaker":"つる委員","kind":"質問・要望","question":"そこがまさにＡＩとの違いだと思うので、そこを本当に意識しながら、活かすものはしっかり活かしていきながら、本来の趣旨といいますか目的感をしっかり達成しつつ、そういったところにもきちっと対応した活かし方をやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"地域の方に学ぶ授業のような、学校で行うのか分かりませんが。それで、プログラミングのところにも、ＩＴ企業との連携と、第二延山小学校のところに書いてあるのですけれども、そういった専門的な講師をお呼びするときというのは、教育委員会主導なのか学校主導なのか、もちろん物によって全然違うのだとは思うのですけれども、どういったマニュアルというか方針みたいなものがあるのか教えてください。","respondent":"熊谷指導課長、大関教育総合支援センター長","answer":"先ほどお伝えした４技能のテストの中で９年生で実施したスピーキングなのですけれども、６５％以上の子どもがいわゆる英検３級以上ということで。外部講師選定に当たっての１つの目安、基準という部分ですが、まず学校と教育委員会が十分に相談しながら選定に当たるというのは前提となります。オリンピック・パラリンピック教育につきましては、本区開催・応援競技の３競技については、私ども指導課でご紹介して、そして予算もつけているところです。","id":"exchange-060"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そういった新しい技術もあって、もちろん人間が教えるというのはもう大前提なのですけども、別の部分、要は授業ではないところで、どうやってその子どもたちを教えていくかというところで、こういった新しい技術を活用したものというのは取り入れられるのではないかと思うのですけれども、そういった部分というのはどのように考えているのでしょうか。そういったときにどのように対応していくのか。","respondent":"熊谷指導課長","answer":"やはり、どうしても苦手なところというのが出てきますので、そうした中で取り組んできているところですけれども、例えば先ほどお伝えした品川区グローバル人材育成塾で英会話のレッスンを行うということも、１つのそういった苦手部分を克服する。","id":"exchange-061"},{"speaker":"石田（し）委員","kind":"質問","question":"ＡＩのロボット等もなのですけれど、楽しく学ぶと言うと、子どもたちはすっと入るので、飽きてしまうかもしれないけれども、１つのツールとして活用できるのであれば、特に英語の発音の部分などロボットは得意で、発音を学ぶというのは、実はあまり日本の担任の先生だと難しかったりするので、その点は、活用できるようなものにはぜひ常にアンテナを張っていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"渡部委員","kind":"質問","question":"英語をしゃべることもできる委員の質問の後で英語のことを話したくないのですけれども、グローバル人材育成塾はもう始まって大分、５年になるのですかね。それと、何年かやってきて、何か変更点があったのかというところを教えてほしいのと、これは１年間を通してではないですか。部活動などの配慮。抽選でふるいにかかるようなことがないのかというところをあわせて教えてください。","respondent":"熊谷指導課長","answer":"変更点なのですけれども、平成２６年度にスタートしたもので、後のご質問にもかかわってくるのですが、４月スタートにしてしまうと、部活動がどの程度あるのか、７年生がわからないということがあって、結局、ドロップアウトしていく人数が毎年２０人ぐらいいたのです。","id":"exchange-063"},{"speaker":"渡部委員","kind":"質問","question":"先ほどの質問なり課長の答弁を聞いていると、英語教育がしっかり地について実績が上がっているというのは、聞いてわかるとおりですので、引き続きお願いしたいのです。私は優先するべきだという意味で、今、質問しようと思っているのですけれども、学校長推薦枠というのがあったので、この辺との接続というのは、思いついていなかったので、何か接続しているのであれば教えてください。","respondent":"熊谷指導課長","answer":"委員ご指摘のとおり、毎年１名ずつ、各学校、校長推薦で行かせておりますが、直接的にグローバル人材育成塾に入っている子どもを優先ということにはなっていません。あくまでも校長推薦という形で行っているところです。","id":"exchange-064"},{"speaker":"渡部委員","kind":"質問","question":"品川区が英語教育にすごく力を入れていて、仕組みも別でしょうし、所管も別なので、これは一様に言えないことですけれど、希望としては、せっかく今、品川区はこれだけのことをやってきているわけですから、例えば中学生が７年生の段階でグローバル人材育成塾というチラシか何かを見て、こういうのがあるのだと知ったときに、実はプログラムとして、オークランドの語学研修があるよ、一月ぐらい行けるよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"市民科の中の将来設計でしたっけ、その領域の、ちょっとそこまで時間的に厳しいかもしれないので、日常、担任の先生などが、そういったお仕事を提示していただけるといいのですが、英語というと、学校の英語の先生だったり通訳だったりＣＡだったり、そういうイメージしかないので、本当にいっぱいあるのだということを教えていっていただけるとありがたいのですが、そのあたりはいかがでしょうか。","respondent":"熊谷指導課長","answer":"そういった方からお話を聞いていくということも重要だと思います。学校図書館にも、そうしたさまざまな職業について知るための資料等もありますので、そうしたところで、まずは紹介していく、伝えていくということが重要であると考えます。","id":"exchange-066"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"本当に身近なところで、そういった、本当に大げさに英語を使う仕事みたいなのでなくてもあるのだというのを、やはり教えていってあげるといいと思うので、ぜひ、今お話があったようなところで進めていっていただきたいと思います。","respondent":"大関教育総合支援センター長","answer":"東京都教育委員会が、全都的に、プログラミング教育推進モデル授業を、今年度より２年間行うに当たって、そこに携わっていただく企業、プログラミング教育推進企業の企業体連盟というものを、東京都教育委員会が組織しております。そこに加盟していただいている企業です。","id":"exchange-067"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、その中で品川区でやられていると、品川区にある、現状、今、品川区にかかわっている企業が多くなるのですか。","respondent":"大関教育総合支援センター長","answer":"ただ、そちらの連盟のほうには当然、今後も追加で加盟していくことは可能ですので、既に昨年、平成２９年度に、第二延山小学校に来ていただいたＩＴ系の企業は当時は未加盟でございましたので、今回、東京都のモデルを受けるに当たって加盟していただいたという経緯があります。","id":"exchange-068"}]},{"id":"topic-05","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"それで、来年も、予測すると、さっき数字を書き取れなかったのですが、４人ですか。職を求めていない人、中には、もうずっと落ちて落ちて、諦めて、４月１カ月に申請しなかっただけで待機児童から外されてしまうのです。これ自体を見直していかなければいけないという、大もとの、今、２点を私はすごく思っているのですが、この点は品川区はどう考えているのでしょうか。","respondent":"大澤保育支援課長","answer":"認可保育園、不承諾の人は全員、待機児童ではないかというお考えですけれども、やはり育休の延長や給付金申請のため、不承諾通知を得るために申し込みをされる方は一定数いらっしゃいまして、平成３０年４月の不承諾者のうち３割の方は１園しか希望していないということで。","id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問・要望","question":"すみません。育休のところで不承諾を待っている３割というのは、分母は何の３割か、もう一度教えていただきたいのと、品川区の育休を延長したいがために出している人というのは、一人ひとり当たって確認しているのでしょうか。入れたら職場に復帰するという人は絶対含まれていないのか、そこのところを教えてください。","respondent":"大澤保育支援課長","answer":"不承諾者のうちの３割は、１園しか希望されていない方です。育休中の方の取り扱いについては、５月に申し込みをされた方は、入れればすぐに復帰したいという意思表示だと思いますので、その方たちは待機児童です。","id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だから、１園のみで、私は厚生労働省がやはり待機児童問題を捉えて、自治体の判断で、厚生労働省の基本的なところはあるのですけれども、そこの範囲の見方の問題を、やはり自治体の裁量で広げて考えられるという、厚生労働省の、これは通達というのか、保育所等利用待機児童数調査に関する検討のとりまとめというのが、平成２９年３月３０日に出ているところを見ると。","respondent":"大澤保育支援課長","answer":"平成３１年度の予測数ですが、０・１・２歳に限って言いますと、申し込み数が２,９５９人、入園者数が２,３４７人、従って不承諾数は６１２人と予測しております。なお、新規園の開設ですけれども、０から２歳児の定員数は３８７人を予定しているところです。","id":"exchange-071"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今の教えていただいた数字によると、０・１・２歳の来年の希望が、入れないお子さんが６１２人で、新規で入れる部分が３８７人ということなので、やはり、今年ほどではないですけれども、入れない子どもたちが出る、やはり、これの繰り返しをどう改善していくのかという立場にぜひ立っていただきたい。終わりにします。今のだけ答えてください。","respondent":"大澤保育支援課長","answer":"保育園の利用者数ですけれども、二十数年先には必ず減少に転じるときが来ますので、そういった意味では、認証保育所等と既存の施設を活用して対応していくことが必要だと考えております。国や都の待機児童対策も、認可保育所で全てを充足するという考え方ではございません。","id":"exchange-072"},{"speaker":"飯沼委員","kind":"質問・要望","question":"いろんな意見があるので、聞いていただきたいと思います。よほど人口が減らないとやってこないと思います。これは、今の規制緩和の中の流れで行われていて、やはり子どもの育ちよりも財政面を重視した政治の流れの中にあるので、やはり子どもにとって最善の利益を求めていくという保育園が必要だと思いますので、ぜひ方向を、きちんと子どもが育つ、質の保てる方向に行ってほしいと、これは意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"南委員","kind":"質問・要望","question":"２回だけなので、簡潔に質問させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"石田（し）委員","kind":"質問","question":"質問します。人口減少が言われている中で、どうやって子どもたちを増やしていこうと言っているのだし、その支援というのもものすごくやっているのですけれども、そこの矛盾というのは、皆さん、保育支援課は感じているのでしょうか。待機児童を考えたときに、その辺はどういうふうに思っているのかというのが１点と、もう一点は、保育園に子どもを預けている家庭というのは、現在でも約半数ぐらいですよね。","respondent":"大澤保育支援課長","answer":"かなり緩やかな伸びにはなってくると思いますので、そうなると、本来であれば、育休を２年ないし３年とってから復職したいと望まれている方もいらっしゃいますので、今までのように、保育園に入れないから、０歳で無理して復帰して保育園に入れるというようなことはなく。","id":"exchange-075"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/862391?Template=document&Id=4956#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":81606,"voices":229}},{"id":"h30-20181030-5","meetingId":"h30-cm10","date":"2018年10月30日","dateIso":"2018-10-30","committee":"総務委員会","time":"午前１０時００分～午後 ４時５９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を61件抜き出しています。","topics":[{"id":"topic-01","title":"「議案審査」を行います。 第７４号議案、平成３０年度品川区一般会計補正予算","agenda":"「議案審査」を行います。 第７４号議案、平成３０年度品川区一般会計補正予算","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"今回、建築課長に確認をとったら、今回は幅広く使っていただきたいということなので、２項道路、品川区の建築基準法に定められている道路に関しては、この助成金は該当する方向でというお話を伺った中で、もともとあるブロック塀の除却とかフェンスの新設、生け垣の新設などの既存制度との整合性、今回創設されるコンクリートブロック塀等の安全化支援との兼ね合いというのは、どうお考えになっているのか。","respondent":"秋山選挙管理委員会事務局長、品川財政課長","answer":"選挙啓発物品ですけれども、寄附者の方からは選挙啓発にということでお伺いしておりますので、明推協の啓発活動で使っている、皆さんがそろいで持つバッグ、あと学校において出前模擬選挙というのをやっておりますので。こういった流れも参考にしながら、どのような方向でやっていくか、また今後検討していきたいと考えています。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ありがとうございました。本当に有効的に、この２０万円はぜひ使用していただきたいと考えていますので、よろしくお願いいたします。反面、区民の方からみるとだんだんわかりづらくなってきている。学校環境整備事業というのは今後、小学校、中学校、義務教育学校に、順次設置をしていくという解釈でいいのでしょうか。全部の設置が終わるのは何年を目途とお考えなのか、最後にお聞かせください。","respondent":"品川財政課長","answer":"設置の期間につきましては、おおむね来年度にほぼ入ると思うのですけれど、改築校に設置するのに少し時間もかかったりしますけれども、おおむね２年から３年ぐらいで全校に設置していきたいと考えております。","id":"exchange-002"},{"speaker":"いながわ委員","kind":"質問・要望","question":"体育館に関しては、本当に暑い日が続いて、１０年ぐらい前の真夏の時期を見ても、今年の気温のほうが全然高いということもあるのですけれど、その反面、体育館とか学校が置かれている地域事情によって、窓をあけられないという状況がある。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回の補正予算ですけれども、いつから検討を始めたのかということを伺いたいのですけれど、とりわけ新規事業になりますコンクリートブロック塀等安全化支援、それと学校環境整備事業の空調設備ですけれども、いつから、そしてどのような検討が行われて補正予算の計上につながったのか、伺いたいと思います。","respondent":"品川財政課長","answer":"コンクリートブロック塀等安全化支援のほうですけれども、先ほどもご説明したとおり、３・１１から区のほうでは生垣助成等、対応はとってきていた状況です。ただ、今回の地震によって、社会的なニーズがかなり上がってきたというところが制度の導入に踏み切った点だと思います。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"助成額や緊急性を見ても、パワーアップさせることは十分わかるのですけれども、生垣助成の方もしっかり継続していただきたいと思うのですが、この点伺いたいと思います。そういうところも日常的な活動はもちろん、災害時の対応も含めて、エアコンの設置を進めていく必要があると思うのですけれど、その点のお考えを伺いたいと思います。","respondent":"品川財政課長","answer":"それから学校以外の体育館はどうかですが、学校のほうを全校やっていくということで、今回補正予算を出しておりまして、ほかの施設についても今後検討していきたいと考えています。","id":"exchange-005"},{"speaker":"須貝委員","kind":"確認","question":"もしそういうことになりますと、民間の方の除却の意欲が削がれる、ブレーキがかかってしまうのではないかと思ったので、その辺を確認させてください。これは、大地震が来たら所有者に何も責任がないとは言えないので、そういう意味でも早目に協力して改善してくださいと言うことも、私は進めるべきだと思うのですが、その辺について教えてください。","respondent":"品川財政課長","answer":"そのやり方については、またご報告していきたいと考えています。そして、そういう調査をして、個別にお宅に行って啓発をすることが大事だというところも十分認識しておりますので、その考えを持ちながらやっていきたいと考えています。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"それからブロック塀については、今まで皆さんのご質疑を伺っていたのですけれど、基本的には危険なブロック塀を除去していくということですが、この間地域を歩いているとき、お隣のお父様のおうちのブロック塀が、危険かどうか審査したいのだけれども、新聞でお隣の港区では検査に助成金がつくというので、品川区はどうかと思って問い合わせたら、検査には品川区ではつかないということで。","respondent":"品川財政課長","answer":"安全なものまで壊して、また建て直すということはしませんので、その時点ではやる予定です。ただ、今回補正で計上してありますとおり、調査等もやっていきますので、その中で先ほども答弁しましたとおり、啓発等もやっていきたいと考えています。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"基金についてはぜひ何らかの形で、そういうご本人のお気持ちがちゃんと伝わる形の使い方ということが、こうして議事録に残る形で伝わっていくという感じでしょうか、ぜひせっかくのお気持ちを生かすような使い方を、いつの間にかほかの何かに紛れてしまわないようにしていただきたいと思います。","respondent":"品川財政課長、小林施設整備課長","answer":"基金につきましては、当然こういうご寄附をいただいたということがわかる形で、今後使っていきたいと考えておりますので、よろしくお願いします。ただ、難しいところは基礎の基準とか配筋という点もあるのですけれど、そこが地中に潜っている基礎についてどういうふうに判断するか、非常に難しいところがありますけれども、建築基準法の見方のパンフレットは建築課にありますので。","id":"exchange-008"},{"speaker":"吉田委員","kind":"意見","question":"そういうふうに気にされる方ですので、既に建築課にはご相談されているのです。それで解決できなかったので、私に相談がありました。この問題は、議会でも気になりますし、区民の皆さんも気になります。地域の人たちみんなが、うちのブロック塀は大丈夫かしらと思って、その方は、もう建築課にも連絡されています。そのようにお伝えしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"今回は２０件でまず補正が組まれているのですが、区民意識が高まってくる中で、危険なブロック塀の除却がメインで助成が出るということが、しっかりと周知が進んでいく中で、区民の皆様が助成があるのであればやろうと考え、今後２０件埋まったということになれば、次の動きとしてはさらにまた上乗せで助成の追加できるのかどうか、いかがお考えか確認したいと思います。","respondent":"品川財政課長","answer":"今回の助成枠ですが、どれぐらい申請があるか見えないところでの２０件という枠ですけれども、また今後の状況を見て、その辺について予算をつけていくかどうか、考えていきたいと考えています。","id":"exchange-010"},{"speaker":"吉田委員","kind":"質問","question":"周囲への相応の配慮とか、埋設物とか仕方ないと思うのですけれど、そういう方たちへのフォローと、事業者も事業計画は大分前に立てますよね、人件費も確保して、人の手当もつけて４月開設を目指していて、数カ月でできることではないので、その点への配慮もちょっと気になりますので、わかる範囲でお答えいただければお願いしたいのですが、いかがでしょうか。","respondent":"品川財政課長","answer":"利用者に対する件ですけれども、これは来月、説明会を行う予定で考えております。それから事業者に対しましては、今回の補正予算は、以前に出しました全体の総額より多少金額を上げております。そういった部分で対応しているということで、今回、債務負担行為の追加を行うです。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"例えば事業者の事業的には、もう４月分から事業計画に入っていると思うのですが、そういうところまで考えられているというふうに理解してもよろしいでしょうか。","respondent":"品川財政課長","answer":"事業者の人件費につきましては、これはまた今後、どのような方向でいくかは考えていきたいと思ってあります。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"賛成です。一言だけ。細谷恵介君からの基金ですけれども、先ほどやりとりがあったように、ご本人の気持ちをしっかり生かしていただきたいということと、あわせてこの募金活動に品川区中の区民や商店、私も大井町駅で必死に集めている若い人たちの姿も見ておりますので、金額以上の思いが私はこもっていると思うのです。そういう意味も含めて、しっかりと取り扱っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問・要望","question":"賛成ですが、最後の障害児者総合支援施設は、半年ずれるということは入られる事業者にとっても相当ダメージがあると思います。その辺のこともぜひ配慮して、考えていただきたいと思います。結論としては賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]},{"id":"topic-02","title":"」を聴取いたします。 まず、(1)「品川区長期基本計画策定委員会の設置","agenda":"」を聴取いたします。 まず、(1)「品川区長期基本計画策定委員会の設置","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"私からは大きく２点あります。その点を伺いたいのですけれども、まず委員は全員で３１名程度ということですので、ぜひ毎回の委員会で委員全員が発言できる分の時間を、確保していただきたいと思っています。ぜひ委員全員が発言できる時間を確保していただきたいというのが、１点です。以上のことを一言でまとめると、時間と回数を増やしていただきたいと思っているのですけれども、いかがでしょうか。","respondent":"大野計画担当課長","answer":"策定委員会の開催回数ですけれども、現在、全部で９回で予定しておりまして、パブリックコメントの後の策定委員会は、パブリックコメントの意見を反映したもののご審議で１回、最終の答申で１回ということで、２回を予定しているものですけれども、こちらにつきましても。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ委員会の時間は延ばしていただきたいと、要望しておきたいと思います。回数についても十分に確保されるよう要望しておきたいと思います。次に、委員会傍聴について２点伺いたいのですけれど、１つは傍聴です。もう一つは、資料の持ち帰りです。ぜひ当日傍聴に来られた方が、審議されている内容に関する資料を持ち帰ることができるようにしていただきたいと思うのですけれども、この点もいかがでしょうか。","respondent":"大野計画担当課長","answer":"傍聴の出入りを自由にということ、それから資料の持ち帰りができるようにということですが、両方とも委員長、副委員長と、委員会運営の中で原則は決めていくことと考えていますけれども、こういったご意見をいただいたということで。","id":"exchange-016"},{"speaker":"中塚委員","kind":"提案","question":"この部分は様々な審議会や委員会によって扱いがまちまちなので、ぜひ長期基本計画という上位計画の策定を機に、どの審議会や委員会でもできるようにしていただきたいと思うので、事務局として先ほどの２点についてを、委員長含めて提案していただきたいと思いますが、再度いかがでしょうか。","respondent":"大野計画担当課長","answer":"やはり一定程度、審議会その他をオープンにしていく、また資料もオープンにしていくという流れがありますので、そういったご意見をきちっと委員長、副委員長に、事務局としてお伝えしていくという形で、対応させていただきたいと思います。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"その上でルールもつくることが必要であればそれでいいと思うのですけれど、ぜひその辺はきちんとしていただきたいと思います。その上で、区内団体関係者が１６名程度ということですけれども、大体１６団体ぐらいを想定しておられているのか、どのようなところに、声をかけてその中でこのぐらいの団体は参加してくださると見込んでのことなのか、その辺を教えていただければと思います。","respondent":"大野計画担当課長","answer":"区内団体関係者１６名程度ですけれども、前回の策定時、改訂時等を参考にいたしまして、大体の数をまず出した上で、できるだけ多くの関係者の方からお声を聞きたいということで、１６名程度といったところで現在調整しています。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問・要望","question":"いろいろな立場の方たちにとってこの場はお互いの活動の理解をするいい機会にもなると思いますので、策定時がこうだったからそれを踏襲するということではなく、今現在、どういう団体があるかという目で見ていって、いろいろな方に参加していただきたいと思います。その辺、ぜひご検討いただければと思います。","respondent":"大野計画担当課長","answer":"前回の策定は１４名で、今回は１６名程度にいたしましたので、必ずしも前回を踏襲したものではございません。新しく出てきている団体、また幅広く声を聞くにはどの団体を選べばよろしいのかといったところも含めて、よく検討してまいりますので、よろしくお願いいたします。","id":"exchange-019"}]},{"id":"topic-03","title":"品川区将来人口推計結果（速報）について","agenda":"品川区将来人口推計結果（速報）について","exchanges":[{"speaker":"いながわ委員","kind":"確認","question":"聞き漏らしたかもしれないのですが、これは、将来値を仮定して、それをもとに将来人口を推計していくということだと思うのですけれど、平成３０年４月１日現在の数字を式に入れて、出てきた数字だと思うのですが、これは１０年に１回行うものなのか確認したいのですが。私は推計とか統計に詳しくないのですが、誤差が生じてくるではないですか。","respondent":"大野計画担当課長","answer":"今回、平成３０年で人口推計を行いましたけれども、前回行ったのが平成２７年に人口ビジョンというものを作成したときに行いました。その前は長期基本計画の改訂時ですので、平成２５年に行ったところです。","id":"exchange-020"},{"speaker":"いながわ委員","kind":"質問","question":"長期基本計画というのは品川区の今後の施策とか、そういうものを決めていくものだと思うのですけれど、平成２５年のときに要は誤差があった、全然違ったわけではないですか。要するに、そこでいろいろな誤差が出たのを、今回平成３０年４月１日のデータは、俗に言う将来値に当て込んで出てきた数値という、要は反映されているということでいいわけですか。","respondent":"大野計画担当課長","answer":"今回の推計に、今までの誤差等を踏まえたものが反映されて最新の推計が出ているのかといったご質問かと思います。こういったものは全て最新の値を用い、誤差等の調整されて、新しいものを出しているという認識で結構です。","id":"exchange-021"},{"speaker":"いながわ委員","kind":"確認","question":"これを見ると本当に、今日、ここで議論したくなるほど、今後の品川区はどうなるのだろうと、何をすればバランスのいい人口比になるのかということも含めて、恐らくこの長期基本計画策定委員会の中でいろいろ議論をしていく、もちろんこれが中心にとはいいませんが、こういう流れの中で特定の世代に負担がかからないような今後の品川区の理想の人口像を導き出していく、それは。","respondent":"大野計画担当課長","answer":"将来値について何をどう施策を打っていけばバランスのよい人口比になるかとか、そういったお話はまた、いろいろあろうかと思いますけれども、年齢３階級別人口推計も踏まえ、予測としてどのような形で何年後に人口が増えていくのか、そういったところを踏まえ、施策。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"２０１８年の３７万７,８７１名の総人口に、グラフのカーブが戻る時期というのは、今回の統計では３０年後までしかないので、６０年、７０年先のことは、その時代の人がしっかり議論して考えていただければいいのだけれど、今回の統計上、２０１８年の総人口に戻るのは、何十年後と予測されているのか、もし、２０４８年よりも先のデータがあれば、ご説明いただきたいと思います。","respondent":"大野計画担当課長","answer":"それから２０１８年の総人口に戻るのはいつかというお話ですけれども、２０１８年の総人口に戻る年数は、今回の推計期間の外ということで、はっきりいつということはわからないのですけれども、相当先であろうということは見込まれるところです。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"これは恐らく単純に３０代、４０代が少ないから、係数として減っているのかなと思うのです。やはり子どもの数が減っていくことは自治体の未来を思うとよい状況ではないので、単純に３０代、４０代の人口のところから出てくると、こういう結果になるという、計算上の問題なのでしょうか。そこだけ伺いたいと思います。","respondent":"大野計画担当課長","answer":"２０４８年の０歳から４歳の数が、２０１８年と比べると減っているというお話だと思いますけれども、やはり２０４８年に関しましては、ある程度計算上から出てくる部分がありますので、今の個別に設定した将来値とつき合わせていきますと、こういった数字になりますという。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問・要望","question":"産業構造の変化もあるのですけれど、地方から東京、それから２３区内で都心に近く、そして交通の便がいいところにやはり人口が集中するという流れがある中で、２０４８年まで先の予測を立てている。事業を行うには先々のことを考えなければいけないのですけれど、ただ東京都は、もう隣接して多くの区があるわけです。目黒線も３両編成が、今は７両、８両、それでもいっぱいになっている。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-04","title":"男女共同参画のための品川区行動計画等素案パブリックコメントの実施","agenda":"男女共同参画のための品川区行動計画等素案パブリックコメントの実施","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"パブリックコメントについては、毎回主張していることですけれども、ぜひ説明会を開催していただいて、区の考えと、また区民の意見が言いやすい環境づくりを進めていただきたいと思いますけれども、この点、改めて伺いたいと思います。改めて、いわゆる同性パートナーシップ制度について、このプランの中でも位置づけて、具体化していただきたいと思うのですけれども、いかがでしょうか。","respondent":"島袋人権啓発課長","answer":"パブリックコメントのあり方ですが、１２月２１日で締め切りさせていただきまして、翌年１月１８日に策定検討委員会を予定しておりますので、そこまでにはホームページ上で公表することができるかもしれません。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に、先ほどの長期基本計画策定委員会の設置ともかぶるのですけれど、ぜひこのマイセルフ品川プランの基本理念、「区民一人ひとりが互いに人権を尊重しつつ責任を分かち合い、性別にかかわりなく、それぞれの個性と能力を十分に発揮し、自らの意思によってあらゆる分野に対等に参画できる、男女共同参画社会の実現を目的として」と、共生という男女共同参画の理念はぜひ。","respondent":"島袋人権啓発課長","answer":"共生という文言を、初めてこの計画の中に取り入れさせていただいたところですけれども、どこか遠いところで多様な方々が生きているということではなく、やはり普段の日常の中で実現されて、初めて意味があるものと考えておりますので。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問・要望","question":"私も第２回定例会の一般質問で、この性的マイノリティへの理解促進ということで、ぜひ今度の計画に入れてほしいということを要望しましたので、検討の結果、こういう形で入れられたことは大変評価したいと思います。ほかの取り組んでいる自治体と比べると、それを悩んでいる方がここまで行きつけるのか、ぜひ考えていただきたいと思います。","respondent":"島袋人権啓発課長","answer":"私ども品川区は１０年の計画で、第１次から第４次までやってきた歴史的な観点にページを割かせていただきまして、誰に見ていただいても、品川区の計画の第１次から第４次まで、今後の取り組み等がわかるようなところを書きましたので。","id":"exchange-028"},{"speaker":"吉田委員","kind":"質問・要望","question":"お考えを聞いて安心いたしました。それからもう１点、パブリックコメントは期間の定めがあったかと思いますが、最低３週間でしたっけ、もう少し長くてもいいのではないかと思ったのですけれど。その期間について、お考えをお聞かせください。","respondent":"島袋人権啓発課長","answer":"今回は大きな計画になりますが、１カ月という長い期間を設定しても、期間ばかりが長く、皆さん目にしていただけないこともあるかということと、年末の忙しい時期なので、３週間とさせていただいているところです。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは人権啓発課の問題でなく、広報広聴課の問題になるかと思いますけれど、今、この計画でパブリックコメントを募集していますというのが、ちょっと深いところまで探さないと出てこないという、当事者の方からのご意見もあって大分改善されたというふうには聞いておりますが、ぜひ、今こういうパブリックコメントが募集されているということが、新しいニュースの欄に出てくるとか、期間を長くとれない分。","respondent":"中元広報広聴課長","answer":"こちらはホームページ等も工夫させていただきまして、区民の方に周知が行き渡るように、続けていきたいと思っているところです。","id":"exchange-030"},{"speaker":"須貝委員","kind":"質問","question":"品川区において男女共同参画はこれまで、さまざまな取り組みをされてきたわけですが、実状をどう思われているかだけお聞きしたいのです。実際に、大企業をはじめ中小、零細企業、一部は別ですけれど、余裕がなくて、なかなか女性の働く環境はまだまだ厳しい。現状はどのようになっているのでしょうか。教えてください。","respondent":"島袋人権啓発課長","answer":"ですので、本当に皆様方の目につき、わかっていただくような発信の仕方、啓発の仕方を考えているというところが、今の現状かなと思っているところです。","id":"exchange-031"},{"speaker":"須貝委員","kind":"質問・要望","question":"相談したいというとき、身近に相談できる場所の確保、また区のほうも他の事業部とも連携して支援できるような、そういうことはなかなか難しいと思いますけれど、区民を助けるということで、動いていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"１１月１日から始まる健康ポイントが、フェイスブックに上がったとき、一気に増えたというお話も伺ったので、やはり効果があるのかなと思うのです。ですので、この１２月１日から２１日という、年末の忙しい時期ではありますけれども、忙しい中でもやりたい人はしっかりやるのでしょうけれども、それ以外の方にも広げるというところでは、ＳＮＳの活用も効果があるのかなと思うのですが、いかがでしょうか。","respondent":"島袋人権啓発課長","answer":"先ほどお知らせいたしました男女共同参画の講座に関しましても、ツイッターといったＳＮＳで広報させていただいたところ、そちらからご参加いただく方も多うございました。今後は今の委員のご意見を参考に、そちらでも発信していきたいと考えております。","id":"exchange-033"}]},{"id":"topic-05","title":"平成３０年職員の給与等に関する報告および勧告の概要","agenda":"平成３０年職員の給与等に関する報告および勧告の概要","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"基本的には、これが決まったら、その方向で、２３区は進んでいくのか。ただ、区民感情と照らし合わせてみれば、公務員の給料は高いから減らして当然だという考え方もありますので教えていただきたいのです。それから、たしか、ここ何年か上がり続けてきた、徐々に上がっているという記憶はあるのですけれど、多分２回ぐらい上がっていたと記憶しているのですが、その辺も教えていただきたいです。","respondent":"黒田人事課長","answer":"今年度の人事委員会勧告で、なぜこのように下がったのかという要因ですが、説明の中で少し触れさせていただきましたが、人事委員会によれば、この４月に行政系人事・給与制度の改正を行いまして、今まで職員から部長まで８つの階層があったものを、６つの階層に変えました。","id":"exchange-034"},{"speaker":"いながわ委員","kind":"質問","question":"これは聞いていいのかわからないですけど、平成２６年度から４年間、ずっとプラス改定で来ていて、総額としてはどれぐらいプラスになったのですか。","respondent":"黒田人事課長","answer":"総額ということではちょっとわからないですが、単年度の改定率でいいますと、大体率にして０.１３％から０.１５％ぐらいということですので、微増で来ているという状況でございまして、マイナスからプラスに転じて、毎年少しずつプラス改定になっていたという状況です。","id":"exchange-035"},{"speaker":"いながわ委員","kind":"質問","question":"人事の給与関係はいろいろな等級があるので、一概には言えないと思うのですが、まず１点が、要するに人事の中の等級を合わせたり、いろいろな、今、制度の中身を変えたということなのだけど、たしかに、平均を出さないとどれぐらいかわからないかもしれないですが、今回は景気、不景気で下げるわけではないではないですか。答えられる範囲でお願いします。","respondent":"黒田人事課長","answer":"下げ幅につきましても、役職に応じて改定時と平均で変えてはいるんですが、平均で１２万円でも、約３０万円近く減額になる階層の職員もいますので、そういった意味ではかなり厳しいという受けとめはしています。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"私も、年間１２万３,０００円の減ということで、今回の人事委員会勧告は正直驚いているところです。管理職と一般職に分けると、この平均の影響額というのは幾らになるのか、そこをご説明いただきたいと思います。それと、今回の人事委員会勧告について、特別区長会はどういう態度というか、コメントが発表されているのか伺いたいと思います。","respondent":"黒田人事課長","answer":"改定の率の違いですが、全体の平均の改定率はマイナス２.６％となりまして、係員のところでは平均でマイナス１.９％、初任給は据え置いていますので、改定率は０％です。主任ではマイナス３.１％、係長ではマイナス２.６％です。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"職員の等級というか、正直その辺の違いは私も把握していないものの、いずれにしても月１万円以上をこれから賃下げしていくわけですから、その生活への影響があるのは明らかだと思います。そういう意味では特別区長会のほうも厳しい中身だと、慎重に検討していきたいという立場でありますので、ぜひ働いている職員の方々、組合の要求もよく聞いていただいて、労使の交渉を進めていただきたいと思います。","respondent":"黒田人事課長","answer":"労使交渉ですが、特別区全体の制度ですので、品川区単独ということでなく、２３区全体ということですので、特別区長会と特区連の中で、交渉していくという状況でございまして、例年ですと１１月２０日ごろに妥結して、期末勤勉手当の基準日が１２月１日ということなので。","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"例年ですと１１月中に妥結というのが、この間の傾向だったのかなと思いますけれども、内容が内容だけに、特別区長会と特区連との交渉になると思うのですけれど、組合からの要求に対して真摯に話し合いを、丁寧に進めるように、特別区長会にも働きかけていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"須貝委員","kind":"意見","question":"今回の勧告ですが、四、五年給与等手当が上がってきた状況があります。まして、さらに勤労者の年間平均給与というのは、４２０万から４３０万円という現状を鑑みると、やはりこの人事委員会勧告というのは、その平均を見て、民間からの比較で上がったり、下がったりしている。ですけれど、それはそれ、今回の人事委員会勧告に関しては、私はやはりきちんと受け入れるべきだと考えます。意見だけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"非常に悩ましいところで、これ以上、こうしてください、ああしてくださいというあれではないですけれど、やはり安定してしまうと、その上を目指す職員が果たして、これからもっと増加するのか、疑問だと思うので、それは何かしら考えていただいて、区民の皆さんのためにもっともっと意欲を持つ職員の人材育成に向けていただきたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"新妻副委員長","kind":"質問","question":"１点だけ教えてください。今回こういう人事委員会勧告を受けて改定された場合、退職金への影響というのはあるのかどうか。","respondent":"黒田人事課長","answer":"この勧告どおりに給与が改定されますと、退職金の算出方法は月例給掛ける支給月数という中で、定年退職の今、支給月数が４７.７月ですから、その月数だけ減ということになりますと、退職金には大きな影響があるのかなと認識しています。","id":"exchange-042"}]},{"id":"topic-06","title":"かむろ坂公園改修工事請負契約","agenda":"かむろ坂公園改修工事請負契約","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"老朽化に対応して全面改修というのは本当にありがたいので、計画を持ってやっていただきたいと思います。工期は平成３１年３月２０日と書いてありますが、３月２０日に終わって、公園が一般開放される日と思っていいのでしょうか。それに間に合うようにぜひお願いしたいというのが１点です。何かご答弁があればお願いします。","respondent":"立木経理課長","answer":"開設日に関しましては、３月２０日までに工事を全て終わらせた上で検査を受けて、全てが終了するというのがこの工期ということになっています。所管のほうから聞いておりますのは、３月２０日の工期終了日にあわせまして開設をするです。","id":"exchange-043"},{"speaker":"中塚委員","kind":"質問","question":"児童用と幼児用の遊戯施設ですけれども、この素材は何かというのが質問です。都会にいるとなかなか木と触れ合う機会もないですから、木製のよさというのもやはり強調したいと思うところもあるのですけれど、いかがでしょうか。","respondent":"立木経理課長","answer":"遊具の素材につきましては、詳細の資料がございませんのでわかりかねますが、今の委員のお話につきましては、所管のほうに申し伝えるようにいたします。","id":"exchange-044"},{"speaker":"吉田委員","kind":"質問","question":"いつもトイレのことばかり聞くので恥ずかしいのですけれど、資料には「洋式化およびだれでもトイレ」と記載されておりますが、洋式トイレとだれでもトイレなのか、どうなのか教えてください。だれでもトイレという以上、ベビーベッドは当然だと思いますけれど、ユニバーサルベッドの設置はあるのかも教えてください。","respondent":"立木経理課長","answer":"所管のほうから聞いてありますのは、洋便器化にあわせまして男子洋便器とだれでもトイレの設置ということで、オストメイト、ベビーチェア等を設置するというようなことで聞いてあります。","id":"exchange-045"},{"speaker":"吉田委員","kind":"質問","question":"トイレは１つですか。男女があって、だれでもトイレがあるということなのか、それとも１つのトイレが、本当に誰でも使えるという感じになるのか、教えてください。","respondent":"立木経理課長","answer":"大変失礼いたしました。男子、女子、それぞれ別のトイレに加えて、だれでもトイレがさらに設置されるということで、３種類という形になります。","id":"exchange-046"},{"speaker":"吉田委員","kind":"確認","question":"確認ですけれど、先ほどのご答弁だと、ベビー用はあるけれどユニバーサルベッドまでは難しかったということでしょうか。","respondent":"立木経理課長","answer":"私が聞いている範囲では、ベビーチェアまでということで聞いております。","id":"exchange-047"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。障害があっても公園に行きますから、そういう方たちが、トイレの問題があって行かれないということは現にありますし、私も高齢者介護のほうの仕事をしておりますけれど、散歩先を探すのにまずトイレを確認することが、すごく大事なことなのです。もしご見解があれば伺いたいと思います。","respondent":"立木経理課長","answer":"今いただきました視点につきましては、所管のほうにしっかり伝えします。","id":"exchange-048"},{"speaker":"高橋（伸）委員","kind":"質問","question":"では今までは、キャッチボールも両方、それこそ多目的に使っていたということでいいのですか。それで新しくフェンスをつけるので、同じように多目的広場とキャッチボールという、両方できますよということでいいですか。安全面とか考えた上でしょうか。","respondent":"立木経理課長","answer":"すみません、運用の仕方につきましては、私どもではわかりませんので、その件に関しましては所管のほうにお伝えいたします。","id":"exchange-049"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"今後、考え方としてそういう暑さ対策ということも、公園の中にしっかり取り入れて、設計を考えてほしいというのが要望です。ベンチもそうですし、日よけができるところはつくっていくという考え方を、ぜひ取り入れていっていただきたいと思うのと、少しでも熱を吸収するような地面とか、遊具とか、そういうものをご検討いただきたいと考えていますが、いかがでしょうか。","respondent":"立木経理課長","answer":"申し訳ありません。先ほど申し上げた主な施設の中に、言い漏らしがございました。改修計画図にはないのですが、パーゴラも設置されるということになっております。暑さ対策につきましては、今いただきましたご意見をまとめまして、所管のほうに伝えします。","id":"exchange-050"}]},{"id":"topic-07","title":"ふるさと納税寄附金の返礼品追加（品川区限定シナモロールぬいぐるみ）","agenda":"ふるさと納税寄附金の返礼品追加（品川区限定シナモロールぬいぐるみ）","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"野田前総務大臣が返礼品対策ということで、返礼割合が３割と、地場産品限定というルールを義務づけるような話をしていました。もしそうなると、これは地場産品というふうになるのですか。国の動向はもちろん見なければいけないですが、それはどうなのでしょうか。","respondent":"伊東税務課長","answer":"総務省からはいろいろ問い合わせがあるということは聞いてありますけれども、これから国会も含めていろいろ検討していくというような報道もありましたので、それはこの後、方針が出るのではないかと思いますけれども、今言ったようなことで、今回は進めします。","id":"exchange-051"},{"speaker":"いながわ委員","kind":"質問","question":"ぬいぐるみは、原産国証明ではないですが、何でつくられていますというタグがついているではないですか。先ほど、課長は地場産品ということで言い切りましたので、それ以上何もないですが、やはりそういうところも多少気を使ったほうが、もらった側の喜びが倍増か、半分に減るのかわからないですけれど、お考えいただければと思いますが、どうでしょうか。","respondent":"伊東税務課長","answer":"確かに、タグにどこでつくったかと明記され、商品自体を品川区でつくっているわけではございませんけれども、そういう考え方で進めします。","id":"exchange-052"}]},{"id":"topic-08","title":"品川区長・品川区議会議員補欠選挙結果","agenda":"品川区長・品川区議会議員補欠選挙結果","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"紙質が悪くて、どんなに優しく剥がしても証紙が破れてしまうような状況でした。その辺いかがでしょうか。今回、確認団体のポスターに張った証紙のことを今、私は言っているのですけれど、もしそれが、ビラがまけるようになるという話を聞いているので、それにも証紙を張るわけですから、同じような材質のであれば、公示された後は配っていかなければいけないので、時間を争うわけです。","respondent":"秋山選挙管理委員会事務局長","answer":"お伺いしたところによると、証紙を台紙から剥がすときのことですか。","id":"exchange-053"},{"speaker":"いながわ委員","kind":"確認","question":"再確認ですが、要するに、区長選挙のときは確認団体ということで、今回ポスターは台紙から証紙を剥がすとき、薄くて、ちょっと剥がすと違うところがやぶれてしまうような状況だったので、それを個人用の小さな証紙の紙質に変えると、そちらは丈夫な紙だったと、私は触っていないのでわからないですけれど、ぜひ丈夫なしっかりとしたものを、衆議院選挙では使えるようにしてもらいたいと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"中塚委員","kind":"質問","question":"期日前投票なので、後半になればなるほど結構、混雑というか列をなしている状況で、何とかならないかというご意見を伺いました。ちなみに私は、始まった初日にこのアトレで投票したのですけれども、そのときはガラガラで、こんなものかなと思ったら、後半になったら列で並んでいたという話も聞いたので、何か改善策を打てないものかと思うのですが、いかがでしょうか。","respondent":"秋山選挙管理委員会事務局長","answer":"対応として考えているのは、設置レイアウトを変えて、もう少し効率よくできないかとか、宣誓書を書くのを、今まで入ってから書いていただいていたのですけれども、並んでいる間に書けるようにするとか、いろいろ工夫できるところは幾つか。","id":"exchange-055"},{"speaker":"吉田委員","kind":"確認","question":"先月の委員会でしたか、聴覚に障害のある方のためのコミュニケーションボードを提示していただいて、これが置かれますということで、そのとき私、小さいな、もう少し大きくないとなと思って、実際どうなのだろうと思い、みんなに、こういうのがあるはずだから見に行ってね、確認してねというふうにお願いしたのです。２人聞きましたけれども、ご存じなかった。見解があれば伺いたいと思います。","respondent":"秋山選挙管理委員会事務局長","answer":"あのＡ４判のものをどこかに張るということは想定していなかったはずです。それにしても、必要とされる方が使える状態に確実にするということで、次回はしっかり注意していきたいと考えています。","id":"exchange-056"},{"speaker":"吉田委員","kind":"意見","question":"私も記憶が定かでないのですが、たしか裏面には机の上に置くか、近くに掲示するようにというような表現があったかと思います。掲示されると確かに小さいので、当初の趣旨は机の上に置く用ということであれば、やはり受付のところに置かれるのが一番正しいかなと思いますので、その辺は徹底をよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"}]},{"id":"topic-09","title":"の５の「その他」を行います。 まず(1)、所管質問","agenda":"の５の「その他」を行います。 まず(1)、所管質問","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"公文書をつくるに当たって、メモとか音声で記録とかをすると思われるのですけれども、それと実際に公文書とされるものの線引きについて、お聞かせいただきたいと思います。よろしくお願いします。","respondent":"米田総務課長","answer":"これを紙による従来からの文書、もしくは図面、もしくは電磁的記録により残しておき、それらを適正に管理することが、我々に課された役割だと考えています。その中で、例えば議事録等を起こすためにメモをとったり、録音したりということが行われます。","id":"exchange-058"},{"speaker":"吉田委員","kind":"質問","question":"そうしますと、例えば議事録をつくるためのメモとか、いわゆるきちんとした書式にするためのメモというものについても、その都度その議事録とか公文書をつくる、昨日のご答弁ともあわせると、所管がそれをきちんと、補助的な文書としてとっておこうということをそれぞれが決めるというふうに、理解していいのか、それとも品川区としてこういうことも残っていれば、公文書として扱うというような規定が。","respondent":"米田総務課長","answer":"実際の成果物ができた後、その録音媒体だったりメモだったりというのは、やはりそれは所属の判断で、一定程度役割を終えたということであれば、文書の管理というのは基本的に、きちんと保管しておくこと、残しておくこと、作成してその記録をとどめて残しておくこととともに。","id":"exchange-059"},{"speaker":"吉田委員","kind":"質問・要望","question":"昨年の暮れ、公文書管理のガイドラインが国レベルで作成された中で、身分要件、誰々が確認したものを文書としていくとなると、疑ってはいけないかもしれないけれど、疑わざるを得ない、その身分要件を課すことによって、本当は残っているものも公文書として扱わなくなり、情報公開の対象でなくなるということを、私たちはとても危惧しております。難しいかもしれませんが、ご見解があればお聞かせください。","respondent":"米田総務課長","answer":"情報公開というのは、区としていわゆる公文書として残しているものに対して、請求があったときその具体的なものを特定して、公開していく、それが基本的であることは、今までも変わりございません。","id":"exchange-060"},{"speaker":"中塚委員","kind":"質問","question":"今のやりとりの中で、議事録の関係ですけれども、録音をして、内容によっては要点筆記として残す方法と、メモをして、後から議事録をつくるものと、２種類、それぞれ所管で判断ということですけれども、録音するものと、メモするものと、同じ議事録作成でどういうふうに、どういう物差しで分けているのでしょうか。そこをご説明いただけますか。","respondent":"米田総務課長","answer":"必ずしも、そのようなやり方でやらなければいけないということで定めているわけでもございませんし、その辺のところは所属の判断だろうということで、申し述べておきます。","id":"exchange-061"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/643576?Template=document&Id=2122#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":58736,"voices":200}},{"id":"h30-20181031-14","meetingId":"h30-cm10","date":"2018年10月31日","dateIso":"2018-10-31","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 ３時４５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","topics":[{"id":"topic-01","title":"改めまして、区有施設・公有地等活用に関することのうち、庁舎のあり方","agenda":"改めまして、区有施設・公有地等活用に関することのうち、庁舎のあり方","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"どうするのか、こうするのだと、今、お話が出ていましたが、それでしたら、庁舎のあり方について話すというよりは、遠回しに、皆様に対して、どうだろうか、どっちがいいのかというのではなくて、もうここまで庁舎の課題が明確に出ていたら、新設に向けてこの委員会で討議するほうが行財政改革特別委員会のふさわしいあり方ではないかと思うのです。皆様、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"渡部委員","kind":"質問・要望","question":"皆様は、当然、庁舎は免震もして、長寿命化を図られてくるとは思うのですけれども、６５年と冒頭にありました寿命は放っておいても来るわけです。ですから、経理課長からご説明いただいたことは、まさにそのとおりの話ですので、私たちとしましても、その話し合いはどんどん進めていただきたい。須貝委員からの質問に、私たちの考えを答えさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"松永委員","kind":"質問","question":"私たちの会派としても、こうした場で早い段階から話し合いを進めていくことはとてもいいことだと考えております。先ほどの説明の中で、これから議会や区民の意見を聞き、検討を進めていくとあるのですけれども、区民の意見を聞くということは、どのような方法でその声を拾っていくのか教えてください。","respondent":"立木経理課長","answer":"例えばパブリックコメントをはじめとした意見の聴取の仕方とか、区政モニターとか、タウンミーティング等を設けるということもあると思います。さまざまな区民に声を聞く形、手法をいろいろな可能性を視野に入れながら、これから検討することになろうかと思います。","id":"exchange-003"},{"speaker":"松永委員","kind":"質問・要望","question":"とても時間がかかったかもしれませんけれども、区民がご利用になる施設になると思いますので、世田谷であった方法などをぜひ取り入れていただきたいと考えています。今後、この庁舎がどうなっていくのか、まだわかりませんけれども、もし、まだ時間があるのであれば、そうした対策も入れていただければと思うのですけれども、いかがでしょうか。","respondent":"立木経理課長","answer":"前面の１６３号線の道路が時間帯によりまして大変渋滞するということで、第二庁舎、お客様の駐車場の出口が詰まることは執務にも影響するという中では、例えば道路の導入路、地面へのマーキングは、警察など道路所管ともお話は引き続きさせていただきたいと考えております。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"一方で、世田谷区のように、非常に文化的な価値がある建物で、区民の皆様から壊さないでほしいといった声が出ている建物でもないということもありますので、一般質問で言ったように、１８年もありますので、しっかりと区庁舎のあり方を区民参加で、今から、どういう区庁舎であるべきかを議論していくことは必要だということ。詳しくは、また後ほど、うちの会派からも質疑します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"意見","question":"ですので、その課題が何かを明らかにしていくところで、今回、資料の中にも課題が６点ほど出ているのです。雑駁にはわかるのですが、イメージがつき辛いですけれども、複雑なレイアウトとあるのですけれども、区が具体的にどう思っているかを聞きたいのです。駐車場、駐輪場の不足、業務用エレベーター等の設備の不足というのは、どういうところからそう思われているのかを具体的にお聞かせください。","respondent":"立木経理課長","answer":"隣地には区有地もありますので、その有効活用等も図れるということであれば、非常に効率よくできるとの考えも含めて、今後のあり方のご説明をさせていただきました。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"庁舎には、今、職員の皆様が増えている。そういった課題を明らかにして、区民も職員もみんなで納得した上で、こういう庁舎をつくっていくことが必要だと思います。今回の課題抽出だけにとどまらず、まだ検討組織までは詰まっていないという話でしたので、そうした会議体なり検討組織を立ち上げて、引き続き、課題抽出、声を聞くところを徹底していただきたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"一言だけ。皆様も同じ考え方だと思うのですが、免震装置もつけて、この建物が本来はあと十何年はもつという構造にしました。そのときも、相当、莫大な金額を投入して、果たしていいのかどうなのかという議論もありました。職員間で連携を図るにしても、渡り廊下を考えただけでも距離があるわけですから、トータルでみれば、本当に無意味な時間を過ごしている。一言だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"大沢副委員長","kind":"質問","question":"大井町駅前のヤマダ電機が入るビルのところ、企業ですから、こちらからとやかく言う筋合いも何もないのですけれども、今後、長い年月を見た場合に、あそこが万が一、何かあった場合の方策を考える必要があると思うのです。先方のあることですけれども、そんなことも行政内部ではイメージとして抱かれているものなのですか。どうなんでしょうか。","respondent":"立木経理課長","answer":"そういった意味では、区が持っている財産とか、もしくは民間で何か活用させていただける部分があるようであれば、そういったものも１つ、検討材料として、今後、いろいろな可能性を含めて検討をするべきだろうとは考えてあります。","id":"exchange-009"},{"speaker":"こんの委員","kind":"質問","question":"今、大沢副委員長からも、立地という観点からのお話がありましたけれども、この庁舎は、平常時だったら十数年もつけれども、いざ、災害時となったときには、躯体の部分がもつかどうか個人的にはどうなのだろうと心配な気持ちがあります。地方は車社会ですから、それでもいいのですが、品川区に置きかえると、駅から離れて駐車場が確保できているかというと、品川区の庁舎ではなかなかそれも難しかった。","respondent":"立木経理課長","answer":"その区有地の再配置等、そういったものも含めて、広町のまちづくり計画の検討が進んでいる中では、どういった形が一番、まちにとって望ましいのかという部分をしっかりと考えた上で、今後、計画を進めていく。","id":"exchange-010"},{"speaker":"こんの委員","kind":"提案","question":"確認させていただきました。中身の問題については、いろいろな考え方があると思うのです。こちら側から提案したのをどうですかと言うのもそうですけれども、区民の方からの提案によって、それを形にしていく姿勢でつくり上げていった、いろいろなまちづくりの事例がありますので、ぜひ、より形にできるやり方で、そうした区民の方の意見を聴取して進めていただきたいと思いますが、いかがでしょうか。","respondent":"立木経理課長","answer":"庁舎の建て替えとなりますと、かなり大きな事業になりますので、そういった面では、私どももご意見に応えられる形で、アンケートを含めて、これからいろいろ手法は検討させていただきたいと思います。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"大きなものとしては、移動にさまざまな困難を抱えている高齢者の皆様や障害者の皆様についての要望なのですけれども、こういった方々は、初めて行く場所では、まずトイレの場所を確認してから行動すると伺うのです。入り口の近くに障害者用の駐車スペースなどを設けている公共施設、地域センターなどもそうですけれども、多く見られますが、こうした配置も重要かと思いますけれども、いかがでしょうか。","respondent":"立木経理課長","answer":"現段階でどうするということはお答えできないのですが、そういった項目をしっかり洗い出して、何が必要なのかを取り上げた上で、アンケートなどを進めてまいりたいと思います。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"もし、これからこういうことをこうするべきではないか、こうしてほしいというならば、それぞれ皆様が書面で出していただいて、それを一覧にして、今後はもう新築に向けて討議を行い、問題点があったら、それを皆様でまた議論していくほうがいいのではないかと思うのです。今、ここで我々が個別にどんどん出したら、山ほど出るのではないですか。終わらないと思うのですが、いいのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"あったとしても、防災センターの３階ですとか、あるいは第三庁舎の講堂ですとか、十分に気軽に区民の方が使用したり、発表したり、学習会をやったり、そういうときに開放されていないことに対する改善の要望も届いているのです。一般質問で、立川市の市民１００人委員会の例を紹介しましたけれども、しかるべき時期での利用者アンケートの実施とか、区民参加の会議体、検討会を立ち上げる。いかがでしょうか。","respondent":"立木経理課長","answer":"庁舎を考える際の施設規模もありますが、相談スペースとか交流スペース、そういった機能も必要とされている。特に相談スペースなどは、これからも非常に重要になってくると考えていますので、そういったものも含めて、検討の１つの材料とさせていただければと思います。","id":"exchange-014"},{"speaker":"安藤委員","kind":"提案","question":"非常に重要だという思いで提案させていただいたのですけれども、それを立ち上げるお考えがあるのか、ないのか。そこをお伺いしたいと思います。その上で、再開発主導での庁舎建て替えはやめるべきと質問して、再質問でも、まちのシンボルとなる庁舎とは超高層を目指すということなのでしょうかと伺いました。この区長の答弁について、どういう意味なのか伺いたいと思います。","respondent":"立木経理課長","answer":"もちろん財政面はこれからまた検討をしていかなければいけないところではありますけれども、一定程度、そういったことで答弁していますので、そういうことで検討を進めていくことになろうかと思います。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ、会議体も含めて検討してください。それと、区長答弁ですけれども、庁舎のあり方は区にとっても非常に重要なことで、再開発と切り離して考えることを求めたいと思います。今、ご説明がありましたけれども、区長答弁のように、豊島区のように超高層ビルの中に入る手法はやめるべきだと思います。こうした意見を述べさせていただいた上で、それぞれ現時点での区の考え、答弁を求めたいと思います。","respondent":"立木経理課長","answer":"先ほどご紹介いただいたのは、区長の個人的な思いではありますがという前置きがありますが、そういった形で答弁していますので、１つの方向性としては、そういったことで検討をすることになると思います。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"それ自体もすごいと思うのです。ただ、それにかかわらず、格安で貸し付けている。ですから、庁舎建て替えを再開発と安易にあわせることで、結果として区民の財産を失うことがあってはならないと私は思います。そこで、防災面の観点からも、超高層ではなく、停電時などでも円滑な防災活動ができる低層にするべきと私は思いますけれども、区の考えを伺いたいと思います。","respondent":"立木経理課長","answer":"超高層ビルがだめということではないとは思っておりますが、防災拠点として、より高い防災機能を持つ庁舎として、どのような形がいいのかも含めて、検討課題とさせていただきたいと思います。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"例えば立川市では、実施設計にあたっての建物の基本的な考え方を５項目にしていまして、その第１に低層と掲げているのです。こうした点からも、首都直下型地震を見据えて、特に防災面からも低層型にすべきだと私は思います。いかがでしょうか。改めて意見を述べさせていただいた上で、こういった防災面からも庁舎は低層にすべきだと思いますが、いかがでしょうか。伺います。","respondent":"立木経理課長","answer":"防災拠点としての機能は、役所の建物としては非常に重要な役割の１つです。ほかのところと比較して、品川区が今、置かれている環境や土地の利用方法なども含めまして、総合的に判断をさせていただいた中で、計画を進めていくように検討していきたいと考えております。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"防災の点からも、あるいは区民にとってわかりやすい、あるいは環境に優しいという点でも、そういった理由から低層型を選択している先進区があるわけですから、私は、防災面から低層型にすべきだと思いますけれどもいかがかと伺ったのです。防災面からどうなのか。超高層のものでいいのか。考え方をもう一度、伺わせてください。","respondent":"榎本総務部長","answer":"横に伸ばすとすれば、それなりに広大な土地のスペースが必要になる。それをやるには莫大な財源がかかるという形もありますので、そういうさまざまな機能を検討しながら、最終的にどういう形にしていくのかが必要と思います。","id":"exchange-019"},{"speaker":"安藤委員","kind":"提案","question":"防災面の区民の関心とか、まちのあり方や超高層の庁舎に対するいろいろな考え方があります。縦に伸ばすのか、横に伸ばすのかという話もありましたけれども、そういったことも含めて、先ほどから提案している区民の皆様も入った検討会を立ち上げて、ぜひ、一緒に検討をしていっていただきたいと思います。区民の関心は高いと思いますので、よろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"高橋（伸）委員","kind":"質問","question":"この１番の経過の中で、本庁舎、議会棟、第三庁舎はもう５０年たっています、建物の躯体や設備機器など寿命を延ばすために大きく手を入れる時期が来ていますと記載してあります。今後、建て替え、もしくは移転を見据えた上でも、あと１８年しかない。この数年の間にやらなければいけないことがあるのかどうか。お聞きしたいと思います。","respondent":"立木経理課長","answer":"居ながら工事というのは、ご利用の皆様にとってはご不便がかかる部分もありますので、そういったことも考えながら検討していかないといけないと考えております。","id":"exchange-021"},{"speaker":"こんの委員","kind":"質問","question":"庁舎の課題で、区民の皆様からよく聞くお声が、感覚的なことで恐縮なのですけれども、庁舎は敷居が高くて行きづらいという声がよくあります。雰囲気の問題なのか、ここに出ているレイアウトの問題なのか、さまざまな要因があると思うのですけれども、私は、区民の方が行きやすい、立ち寄りやすい庁舎のあり方は非常に大事と思うのです。その点についてはいかがお考えですか。","respondent":"立木経理課長","answer":"そういったことも含めて検討をさせていただければと考えています。","id":"exchange-022"},{"speaker":"こんの委員","kind":"質問・要望","question":"必要だから来る方ばかりではなくて、必要ではないのだけれども、庁舎に何か情報を求めて、何か情報があるかと思って来る方もいる。申請しないと来ない。ですので、まちのにぎわいとともに、区民の皆様の利便性のいい庁舎のあり方で、ソフト面なのかハード面のレイアウトなのかは両面と考えるのですけれども、何かございましたらお願いします。","respondent":"立木経理課長","answer":"区がどのようなサービスをさせていただいているかを知っていただく部分と、あとは、来ていただくことで私ども職員が知ることができる部分もありますので、ソフト、ハード両面で、立ち寄っていただける空間も検討材料として入れさせていただければと思います。","id":"exchange-023"}]},{"id":"topic-02","title":"国・都有地等の有効活用","agenda":"国・都有地等の有効活用","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"林試の森公園は今は公有地ということで、私たちも、一般質問等々、何度も区民の要望を実現させていく場にということを求めてきているのです。３、４階建てを想定し検討と書いてあるのですけれども、都市計画の用途地域から見て、ここはマックス何階まで建てることができるのかを伺いたいと思います。","respondent":"柏原企画調整課長","answer":"ですので、マックスとしては、先ほども申し上げたように５階建て程度はいくだろうと想定はありますが、この辺のボリューム感については、引き続き、いろいろお声を聞きながら、区の行政ニーズも考えながら検討できればと思ってあります。","id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"わかりました。それはもうその方向で検討が進んでいるということでいいのでしょうか。もし進んでいるのであれば、地域密着型特養ホームだと、定員が２９名以下となってくると思うのですけれども、それぞれの定員なども、もし検討をされているのであれば教えていただきたいと思います。","respondent":"柏原企画調整課長","answer":"先日の本会議におきましてもご答弁申し上げたところでございまして、今、委員がご案内いただいた内容の部分についての検討を進めてあります。ボリュームにもよってくるところがありますし、この辺はいろいろなお声を聞きながらというところもあります。","id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"特養ホームと老健施設を足した定員数は、２３区で２３位で最低なのです。先ほど高さの最大は５階くらいまでいけるのではないか、それで、どういうものにしていくか検討を進める中でというお話もあったので、ぜひ、こうした荏原地域にないというところを考えれば、ここは荏原地域ですので、さらに一歩進めていくというところで、グループホームもできないかと思うのですけれども、区の考えをお聞かせください。","respondent":"柏原企画調整課長","answer":"今、グループホームというお話も伺いましたけれども、施設構成を検討はしておりますが、確定している部分ではありませんので、今後、どういう形がよいのかは検討を進めながらといったところです。","id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"こういうところで１つ、区の姿勢として、そして障害者の支援は、本当に弱い部分ですので、２３区で最低レベルの障害者福祉ですので、そこを一歩進めていくためにも、いろいろ制約がある中で頑張っていただいているのですけれども、就労支援Ｂ型だけでなく、ぜひともグループホームを要望していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"今回、特養ホームが地域密着になぜなったのか、理由をお伺いしたい。それは土地の制約なのでしょうか。そのような観点から、今の時点で移転の計画や大まかな配置などはかたまっているわけですから、また、こうして議会にも報告されておりますので、住民の理解を得るという観点でも、今の段階から、主体者の東京都、また、隣の目黒区とも一緒に事業説明会を行うべきだと思うのですけれども、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"これは区の所管の話ではありませんけれども、こういった観点で東京都や消防署に対しても丁寧に説明をするべきであろうということで、我々からも申し出をしていますので、個別になるか、一緒になるかはこれからですけれども、丁寧な説明をこれからやっていくということで。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"区民への説明ということでは、丁寧な説明というのは一般的になってしまうので、具体的に消防署の移転に対する説明会、つくられる前に建設説明会というのではなく、あるいは、解体工事の説明会を待つのでもなく、ぜひ、そうした独自の説明会も開くよう求めていただきたいと思いますけれども、この点について、最後にお伺いします。","respondent":"柏原企画調整課長","answer":"先ほど申しましたように、都市計画の説明会、また、委員からもご指摘いただきましたけれども、解体が入ってきますので、解体に対する説明会等々がありますので、そういった機は必ず捉えるようにと考えています。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/319862?Template=document&Id=6060#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":26720,"voices":72}},{"id":"h30-20181101-18","meetingId":"h30-cm11","date":"2018年11月1日","dateIso":"2018-11-01","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午後 ３時０７分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","topics":[{"id":"topic-01","title":"の２の特定事件調査","agenda":"の２の特定事件調査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"それで、スタッフの方の説明もとてもよかったのですけれども、どのようなスタッフの方々がいらっしゃるのかがよく分からないので、そこだけ教えていただきたいなと、例えば具体的にトレーナーのような、そういう方も含めて、スタッフがどのようにいるのかということがわからなかったので、教えていただきたいということが１つです。","respondent":"いながわ委員長","answer":"スタッフ等について、まさにそのようなお話は現場でぜひしていただきたかったのですが、基本的に山口氏にご説明をいただいて、トレーナーが１人いらっしゃったのと、受付に２人女性がいたのが本日でした。大変申しわけございませんが、さすがにそこまでは私も答えようがないです。","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"特に品川区内の施設だけに。もう少し施設を中身的に知りたいなと思ったのが１つで、だから時限とはいっても、これからパラリンピックがある中で、パラスポーツをもっと広めようというようなときに、そういう設備、施設についての、もう少し具体的な中身が知りたいと思っていますので、また当委員会で別の機会に、そういうことも含めた情報を提供していただけるようにお願いをしておきたいと思いました。","respondent":"いながわ委員長","answer":"パンフレットはございませんでしたけれども、ホームページは開設していると説明がありましたので、ぜひ後ほどご覧いただければと思いますので、ご理解いただければと思います。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１つ理事者の方にお伺いしたいのは、品川区内にあのようなパラリンピックスポーツの支援施設が当時は区内にできたということで結構報道されていたのですが、品川区として今どのような関係があって、どのような協力関係があるのか、何か広報など、今回のオリンピック・パラリンピックに関して、あそこを宣伝というか、広報の場として何か使用をされているのかどうかというところを伺いたいのが１つです。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"しかしながら、委員おっしゃいますとおり、区内にあれだけすばらしい施設がありますし、案内をしてくださった方も、空いているときは何かに使うことも可能だというようなこともおっしゃっておりましたので、東京２０２０大会に向けても、何か利用できることがあるのか。","id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"何点か伺います。今、都市公園と伺って、なるほど都市公園かと思ったのですけれども、そうするとプールがあったのを壊してあのようにしていると言っていたので、その辺の位置づけが時限になっているのかなと少し思ったりもしました。それともう一つ、あのときにも少し聞いたら、まったくここの施設についてはつき合いはありませんとおっしゃっていましたけれども、笹川スポーツ財団があるではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問","question":"位置づけですか、あそこも。では国立のオリンピックセンターと一緒なのですね。ああ、都立ですか。あそこの施設については、それが１つ。もう一つは、せっかく、日本財団のようにお金があるところがあるわけではないですか。どのような形をつくるのだというのは、考えを持ってやれば私はできると思っていて、その辺の意識がないと多分できないと思うので、その辺の感覚だけは教えてほしいなと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ただ、先ほど聞いた話でも団体でほとんど埋まっているということで、なかなか調整も難しいかなという印象はあります。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問","question":"あれはどのような位置づけでやられたのかなと。ただ、あれをやろうとしたら、行政が本当に気合を入れてやらないと多分できないので、そういう意味で、せっかくこの前、障害者の部分でそのようなものからスタートしたのなら、健常者を含めて笹川スポーツ財団とつき合うにはそういうものも必要かなという感じで、やったほうがいいのではないかなと思うのですけれども、その辺のところはどうお考えですか。","respondent":"池田スポーツ推進課長","answer":"それに伴いほかの健常者の方も大勢集まるということもございまして、そういった大きなイベントの場で障害者スポーツというものを紹介し、体験してもらうということが１つの目的でございまして、さらにその体験したことによって普及をすること。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そうすると、今日のパラアリーナのようなところともおつき合いができて、いろいろな形で交流すると、その次の展開のときに、もうすぐ２年とか過ぎるわけですから、その間におつき合いができるようになれば、いろいろな話も品川区はしやすいのかなと。それは気持ちがないとできないので、それは行政の立場でぜひやっていただきたいなという意味で申しあげました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"大倉委員","kind":"質問・要望","question":"今もお話があったとおり施設自体が本当に、利用者の視点で、今以上に一歩踏み込んでさらに使いやすくというところでは、ぜひそういったこともこれから、行政とも連携して進めていっていただきたいと思います。先ほどもお話がありました小学生や中学生とのこうした施設の連携というものも、ぜひ進めていっていただきたいなと思います。１個、「あすチャレ！","respondent":"辻オリンピック・パラリンピック準備課長","answer":"教育委員会のほうでは各学校でいろいろなパラアスリート、パラの競技者を呼んで個別では行っていると聞いておりますが、こういった日本財団がやっているものもまたご紹介しながら進めていけたらと思います。","id":"exchange-008"},{"speaker":"大倉委員","kind":"質問","question":"１点、これは質問なのですが、先ほどの施設の方もお話しされていましたけれども、障害者スポーツ、もともと福祉の視点からだんだんできてきてというところと、一方ではもうアスリートとして、特に海外ではもう成り立っているというところでいうと、例えば今やっている障害者の運動教室で大会があったりしたときに、成績のいい方などがそういう、逆にアスリートに行くような連携や道筋。","respondent":"池田スポーツ推進課長","answer":"私どものほうでは、青少年、１８歳未満の子どもが東京都等の予選会を勝ち抜いて全国大会等に出場する際には、支援金としまして１回当たり１万円の支援をさせていただいている制度が、まず１つあります。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"今度１１月６日に「あすチャレ！School」で、障害者の講師の方からダイバーシティについて学ぶセミナーなどがあり、そのようなときに見学も一緒にできるので、そういうイベントのときに、同じ区内でやられているので、区でもイベントの周知をする、一緒に呼びかけたり、あと子どもたちが参加できるようになどできたらいいなと思ったのですけれども、どうでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それから「あすチャレ！School」のイベント等の話です。特にこちらのほうに情報もなかなか入ってきていなかったので、これからは向こうから要請があったり、私どもで気づいたときはうまく連携がとれるところはとっていきたいと思います。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問","question":"ぜひその情報は、ホームページなどを見に行くこともそうですし、「教えていただければ区民の方にお知らせしますよ」というような声かけもあったらいいのかなと思うので、ぜひその部分よろしくお願いします。何かそれだけでもすごいと思ったので、いろいろな人に見てほしいなと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"品川区における障害者スポーツについてなのですけれども、教室だったり、イベントだったり、大会だったりの、周知方法なのですが、今までも周知をどのように行っているかという質問をしたときに、団体に伝えているということだったのですけれども、団体に入られていない障害のある方たちにも、ぜひこのような機会があるのだということを伝えていただきたいと思っていて。","respondent":"池田スポーツ推進課長","answer":"イベント、教室等の周知についてですけれども、当然団体のほうにも周知しているところではありますが、そのほかにスポーツ協会、品川区のホームページに掲載すること、それから各地域センターや学校等にもチラシを配布させていただいているところでございまして。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひその当事者の方たちに届く周知の方法というものを、今もされているのですけれども、それ以上にもっと広がるように、ぜひ、考えていただきたいし、工夫できたらと思っているので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"いろいろと障害者スポーツについての教室やイベント、大会等々の説明をいただいたのですけれども、この間も出ている普段の練習というのでしょうか、いろいろな活動の中で楽しむ機会をどれだけ持てるかというところが一番大事だと思っているのですが、なかなか施設的にも、それから時間的にも、支援する体制的にも、ちょっと難しいところはあると思うのですけれども、率直に私の印象として思っているのは。","respondent":"池田スポーツ推進課長","answer":"実を言いますとユニバーサルスポーツ大会、こちらのほうも平成３０年度につきましてはユニバーサルスポーツフェスタというような形で、今回、皆さんが参加しやすいような形に変えているところです。","id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"ただ距離的に遠いので、やはりこちらの地域に住んでいる方々はなかなか参加しにくいということもあるのではないかと思うので、パラリンピックを契機にパラスポーツに対してももっともっと間口を広くして、いろいろな方がいろいろな形で参加できる、そのような状況を整えるということはあるべきことだと思いますので、そのような点で東京都に要請することでとどまらずに。","respondent":"池田スポーツ推進課長","answer":"今の施設につきましては、引き続き東京都のほうに要望するようにしてまいります。区のスポーツにつきましては、区のできる限りのところで、これからも障害者のスポーツについていろいろなことを企画していきたいというふうに考えているところです。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問","question":"質問ではないのですけれども、ふれあい作業所についてです。公園清掃についてなのですが。","respondent":"いながわ委員長","answer":"ふれあい作業所のパンフレットはいただいているのですが、ふれあい作業所の方々がクラブ活動をしているということで、その写真が載っているのであえてこのパンフレットをお持ちいただいたというところで。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問","question":"今の障害者スポーツをしている方というのが、この品川区に何人くらいいらっしゃるのか。つかんでいるところで構いませんので、説明いただければと思います。その現在の区の考えている課題について伺いたいと思います。こういったイベントをやる際に、企画の段階から当事者の参加を位置づけることで、より参加しやすいものになっていくのではないかと思いますが、いかがでしょうか。","respondent":"池田スポーツ推進課長","answer":"それで企画につきましても、そのような形で障害をお持ちの方ができるものは当然そうですし、また楽しんでいただけるもの、そういったものを考えながら教室を企画しています。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問","question":"今の課題としては、外に出てもらって体験をして楽しむということで進めていらっしゃるということでしたけれども、それをどうすればより進められるかというところの課題の意識をぜひお聞きしたいと思います。企画の段階からの当事者参加というところでは、今具体的に答弁がなかったように感じましたので、ぜひ企画のときから当事者の方の意見を入れていくというところをお願いしたいと思います。","respondent":"池田スポーツ推進課長","answer":"戸越体育館で行っております障害者の交流教室というものがありますけれども、そちらについては障害者の対象を毎年変えながら競技を行っているということでご説明をさせていただきました。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"当事者参加のところは、今もいろいろお話を聞いてやられているということでしたので、より積極的に意見を聞いて進めていただきたいと思います。そのようなことを計画的に、やはり障害者のスポーツ振興をしていくということで、障害者のスポーツ振興計画を策定し、普及啓発をさらに推進していくことが必要かと思いますが、いかがでしょうか。","respondent":"池田スポーツ推進課長、安藤文化スポーツ振興部長","answer":"区ではただいま長期基本計画を策定しています。そのような大きな計画の中で、こういったことやアンケート等を含めて、障害者の方のスポーツについて研究していきたいと考えています。そして特別支援学校なり、いろいろな情報を通じまして、参加を求めたり、拡大をしたりしていこうと。これは強力にスポーツ推進委員をはじめ、我々と協力してやっているところです。","id":"exchange-019"},{"speaker":"のだて委員","kind":"意見","question":"ぜひ強力に進めるためにも、長期基本計画でも計画するというお話でしたけれども、やはり具体的に進めていくには障害者スポーツ振興計画、仮にですが、こういったものをつくっていくということが力になると思いますので、これは意見として言っておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そのような中で今、地域の課題、当然地域の中でそのようなできることを探す、またそのようなものをだんだん育てていくという、これも当然大事なことですし、今着々とやられているというお話でしたけれども、そのような情報収集を今はされているのか、たしか答弁の中ではしていきますというような答弁だったと思うのですが、例えば同じ質問が区民の方から来たときに、今だったらどのようにお答えになるのか。","respondent":"池田スポーツ推進課長","answer":"情報については多少ですけれども、持っているものはあるのですが、ただ、お答えできるほどの情報量ではまだないということが事実です。その辺については今後もいただける情報というものは集めて、お答えできるような形にさせていただきたいというふうに考えているところです。","id":"exchange-021"},{"speaker":"あくつ委員","kind":"質問・要望","question":"障害といっても、身体障害、精神障害、発達障害、さまざまあります。障害のある方にスポーツをしてほしいというかけ声はできると思うのですけれども、やはりなければ一緒に探していただく。ですから、やはりそのような、精神論ではないですけれども、そのような思いを持っていただきたい。繰り返しになってしまいますけれども、何年か前にそれを質問したので、また改めてご要望させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ教えてください。町会でやるとか、そういうことだから、簡単に言えば知的障害の方の団体が一番、そのような町会だったらかけやすいかなとか、来られたときの対応がどうかなと。それほど広いところではないのだから、ブラインドサッカーやバレーができるとか、そのような広いところもあるわけではないから、ちょっとしたボール遊びなのか、ボール蹴りなのか、何かそのようなものがあるではないですか。","respondent":"辻オリンピック・パラリンピック準備課長、松山障害者福祉課長","answer":"私からスポーツ、誰でもできるスポーツのお勧めというところで、実際先週の土曜日にＯＺというスポーツフェスタをやったのですが、その中でホッケーのミニゲームを、本当にミニゲーム。団体ということですから、恐らく委員おっしゃられるとおり、育成会のほうもご自分たちの団体で運動会をやっておりますので、そういった運動会でやられるような種目でしたら、ご一緒に活動できるかと考えています。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もしあるのであればどのようなスポーツで、何団体ぐらいあるのかということを把握されていたら教えていただきたいと思います。そのような団体に対しての支援の制度というものは、区のほうとしてはあるのかどうかについても教えてください。","respondent":"池田スポーツ推進課長","answer":"障害をお持ちの方対象の、例えば水泳教室というお話がございましたけれども、私どものほうでは水泳の教室、プールを予約する際、区内の団体の方については、４カ月前の抽選という形でやっておりますので、特にその際に団体名は把握しますけれども、誰が使うかというのは。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"以前なのですけれども、障害者の子どもたちを対象にした水泳教室を民間の団体でやっているということは聞いたことがあるのですが、そのようなところがあったら、これだけ障害者スポーツの普及をどんどんやっていこうというようなところなので、ぜひ区としても把握もしていただきたいと思いますし、そういうところに対しての支援や何かも含めて、ぜひしていただきたいと思うのですけれども。","respondent":"池田スポーツ推進課長、松山障害者福祉課長","answer":"障害者のお子さんの水泳教室について、貸し切りの支援ですけれども、個人利用の場合に障害をお持ちの方は無料ということで今やっているところです。特に区民と区外との部分ですね。委員お尋ねの障害福祉計画ですけれども、来年度はアンケートを子どもたち、あと大人の方たちにも取って集約することになっておりますので、その中でスポーツについてという項目。","id":"exchange-025"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"先月２０日の日に、先ほど出たユニバーサルスポーツフェスタ、戸越体育館でやっていらっしゃった件で、障害を持った方と障害のない方がいらっしゃったのかなと思うのですけれども、その一般の方にはどの程度アピールをしたのか。殊に子どもさん向けに考えたときに、学校などにそのようなことをアピールしているのかなということを感じたのですが。","respondent":"池田スポーツ推進課長","answer":"実を言いますと、１０月２０日の日はあそこの近隣の学校はたまたま運動会と重なってしまいまして、一般の方というのはちょっと少なかったです。普段は重ならないようにやっていたのですけれども、たまたま今年戸越体育館の工事が入ることがございまして、重なってしまいました。","id":"exchange-026"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"それを感じたのです。ちょうど行ったときに隣が運動会をやっていたから、何かもったいないなと思って日程調整をどうされているのかということが疑問だったので、今年だけそういうことであればしようがないですけれども、できれば近隣のお子さんたち、小学生、中学生ぐらいに来てもらったほうが、もっとみんな活発にできるのではないかという感じもしたので、ぜひこれからもよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"伊藤委員","kind":"確認","question":"でも、現状はこのようなところに限られている。品川区のお考えを確認したいのが、恐らく陸上競技をはじめとして、いろいろなスポーツをやりたい障害者の方がいらっしゃる。だけれども、それができる機会はなかなかないということをもし聞いた場合にどのような対応をしてきたのかということと、それからこれからどうそれを展開していくのかということについてお聞かせください。","respondent":"池田スポーツ推進課長","answer":"これは研究材料といいますか、企画するところであると考えているところです。東京都のホームページのほうですけれども、こちらも東京都のホームページの部分で、教室、講座があるかと思います。","id":"exchange-028"},{"speaker":"伊藤委員","kind":"質問・要望","question":"全ての方々のご要望をかなえることが理想ではあるのだろうけれども、それは資金のことやら、介助のことやら、それから使う用具も当然変わってくるのでしょうから、簡単にはそれはできないことはわかります。でも、やはりやりたいという方がいらっしゃるわけで、だからそこのところの線引きを、私たちはさまざまな制約をかけた上だけれども、最大限取り入れていくべきでないかと思うのです。お聞かせください。","respondent":"池田スポーツ推進課長","answer":"短期的なものにつきましては、それぞれ私ども毎年目標を立てているところですけれども、長期的なものにつきましては、ただいま長期基本計画を策定しているところでございまして、そちらの中できちんとやっていきたいというようなことは考えているところです。","id":"exchange-029"},{"speaker":"伊藤委員","kind":"質問・要望","question":"まとめますけれども、全部が全部やれとは私たちは言いません。だからそのことについて品川区は、さまざまなワークや制度を検討していただいて、そのような方々の意向がくじけることがないような体制をつくっていただきたいというお願いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"つる委員","kind":"確認","question":"先ほど質疑の中で、「大会」などはなかなかハードルが高くなっているところがあると、それは当事者、ご家族の声であったのですけれども、その中で当然区としての取り組みというのはそうした視点で、そういう障害のある方がスポーツに親しむ機会をつくるという視点での取り組みかと思うのですが、当然２０２０年に向かい、パラリンピックではアスリートとして活躍されている方が当然日本。","respondent":"池田スポーツ推進課長","answer":"ただ、オリンピックのほうでは、実を言いますと、日本のジュニアオリンピックなどに出ている水泳選手がかなりおりまして、そういった大会で入賞する選手も何人かいらっしゃるということで、特に育成というところまでは私どもしてはおりませんけれども。","id":"exchange-031"},{"speaker":"つる委員","kind":"質問・要望","question":"野球などであればスカウトで大会を見に来るという流れがあると思うのですが、障害者スポーツという区でやっている中でも、そういう光るような子どもというか、そういう方がいたときのつなげる仕組みが必要なのかと思うのですけれども、そのあたりがもう既にある程度あるのか、なければぜひそういう連携だとかというところをしっかりとやっていただきたいと思うのですが、このあたりについて教えてください。","respondent":"池田スポーツ推進課長、安藤文化スポーツ振興部長","answer":"今後パラアスリートを発見した際には、そういったことで支援なり、もしくはよりよいコーチができるような部分の紹介などというものをできるようなことを研究していきたいと思います。それでＩＰＣであったり、パラ財団であったり、そういうところとは連携というか、情報提供、情報交換をしようというふうに考えてはいます。","id":"exchange-032"},{"speaker":"つる委員","kind":"提案","question":"わかりました。だから、その例として、区としてきちんとセクションとして、そういった形でやっていく。ぜひそこはしっかり、これからも一層力を入れていただきたいなと思います。２０１６年のときにも、そうしたパラの選手などを支える方々にフォーカスをした講演など、そういったものをやってみてはどうですかと提案したところ、前向きに検討しますと当時の課長からのご答弁をいただいて２年がたつのです。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"テレビ等で非常に興味深いお話をしていらっしゃるところです。これからも啓発講演会等行いますので、その中でトークセッションの形なのか、お一人の講演会なのか、その辺も含めまして、皆様に興味を持っていただけるような企画に活かしていきたいと考えています。","id":"exchange-033"},{"speaker":"つる委員","kind":"意見","question":"ぜひよろしくお願いしたいと思います。このユニバーサルスポーツなど、いろいろあるので、本当にそのような垣根を越えて、障害などというカテゴリーではないところでみんなが支え合う、まさに共生ですよね。そういったこともこのようなスポーツを通じてしっかりと感じられるような工夫、これはこのオリンピック・パラリンピックの視点からも絶対できると思うので、ぜひよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"}]},{"id":"topic-02","title":"オリ・パラ公式ＳＮＳアカウント新設","agenda":"オリ・パラ公式ＳＮＳアカウント新設","exchanges":[{"speaker":"大倉委員","kind":"質問","question":"これインスタグラム、品川区のほうでもあると思うのですけれども、そこにこのように新しくＳＮＳ始めましたよというようなものは、出ているのでしょうか。出ていればいいのですけれども、出ていなかったら出したほうがいいのではないかと思ったのですが。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"区の特設のアカウントのほうですね。そちらのほうではまだ載せていなかったと思いますので、ぜひ宣伝ということでお願いしたいと思います。","id":"exchange-035"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"巨大手形アート、たしか前に聞いたところですと５,０００人を目指すのでしたか、ギネスですからね。結構しっかりしたホームページも拝見させてもらいました。それでそのめどはつきそうなのかどうかというところが心配で、大丈夫なのか、ちょっと質問させていただきました。","respondent":"立川文化観光課長","answer":"現在、この世界記録ですけれども、韓国のソウルで４,６７５人だったと思うのですが、そういった記録があります。通常これだけの大々的なイベントを実施いたしますと、５,０００人ぐらいは軽くクリアするだろうということで、今のところ新記録達成につきましては楽観しています。","id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問・要望","question":"いざとなれば２,５００人の品川区役所の職員の方がいらっしゃいますので、両手でやれば５,０００人と。これは冗談ですけれども、ギネスということで、たしかこれ職員の方の発案ということで聞いていますので、しっかり達成をしていただきたいなと。文化プログラム、オリンピック・パラリンピックの大きな大きな、１つの大きなステップになるイベントだと思いますので、ぜひ期待をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"石田（秀）委員","kind":"確認","question":"このコンサートなのですけれども、このようなものをやることは、すごく私は大賛成なのですが、以前オリンピアンなどを呼んで、こういうものをやるときというのは、映像を使って何とかアートをやっているではないですか。大会組織委員会がやっている大きいもので。オリンピックが終わった後。名前を忘れてしまったのですが、このようなことが今できるようになったのか確認だけしたいのです。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"委員の今のお話は記録映像を流してということだと思います。今時点では、恐らくそれは、やはり大会組織委員会なりに確認をとって許可を得ないと、できないような仕組みになっているというふうに認識しております。","id":"exchange-038"},{"speaker":"田中委員","kind":"質問","question":"それで、公園にいる方たちも何をやっているか気になっているのだけれども、チラシが貼れないとか、そのような話があって、その周知の仕方、ちょっとそこで公園とスクエア荏原との利用方法が違うということで、何といいますか、同じ敷地にあるのに分断されてしまっているような状況があって、ほかのイベントのときも、やはり中のイベントの様子が全然見られない状況があるので。","respondent":"立川文化観光課長","answer":"この施設、通常スクエア荏原の部分と、あとその手前の公園、広場ですけれども、通常一体的には運営はしていないところですが、この日のイベントに限りまして、全体を１つの会場と見立てて実施いたします。","id":"exchange-039"},{"speaker":"田中委員","kind":"確認","question":"公園の遊具の部分は、テープがされたりする状況となってしまうのかという確認をさせてください。","respondent":"立川文化観光課長","answer":"その辺は、まだ確認はしていないところですけれども、一般的な利用はできないですので、通常、例えばしながわ中央公園をフェスティバル等で利用する場合と同じように、一般的な利用はできないというようなことで実施をする予定です。","id":"exchange-040"},{"speaker":"田中委員","kind":"質問","question":"しながわ中央公園で何かイベントなどがあるときというのは、そのイベントによってその遊具の開放がされているか、テープが張られていて遊べませんとなってしまうことがあると思うのですけれども、荏原のほうでは、結構広めの公園というものが本当に少なくて、スクエア荏原は結構いろいろな、休みの日は親子が結構長い時間滞在している状況なので。","respondent":"立川文化観光課長","answer":"委員ご指摘のとおり、遊ぶ場所があまりないですので、いわゆる区主催のイベントですので、その辺については事前に調整をしっかり実施いたしまして、また、もし仮にその辺が使えないということでございましたら、事前に周知をしっかりいたしまして、開催したいと考えております。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/478583?Template=document&Id=6546#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":39199,"voices":127}}]);
